const DEFAULT_CUSTOM_BULK_ACTION_RESULT: BulkActionResult = {
  clearSelection: false,
  closeMenu: true,
  success: true,
};

const DEFAULT_CUSTOM_BULK_ACTION_FAILURE_RESULT: BulkActionResult = {
  clearSelection: false,
  closeMenu: false,
  success: false,
};

