  };
}

export function shouldRenderBulkActionsMenu<TData>(
  selectedRows: Row<TData>[] | undefined
): boolean {
  return Boolean(selectedRows && selectedRows.length > 0);
}

export function createBulkActionContext<TData>(
  selectedRows: Row<TData>[]
): BulkActionContext<TData> {
  return {
    selectedRows,
    selectedOriginalRows: selectedRows.map((row) => row.original),
    selectedCount: selectedRows.length,
  };
}

const isValidBulkAction = <TData,>(
  value: unknown
): value is BulkAction<TData> => {
  if (!value || typeof value !== "object") {
    return false;
  }

  const action = value as Partial<BulkAction<TData>>;

  return (
    typeof action.id === "string" &&
    action.id.length > 0 &&
    typeof action.label === "string" &&
    action.label.length > 0 &&
    typeof action.icon === "function" &&
    typeof action.onClick === "function"
  );
};

export function resolveCustomBulkActions<TData>({
  context,
  customBulkActions,
}: {
  context: BulkActionContext<TData>;
  customBulkActions?: CustomBulkActionsInput<TData>;
}): BulkAction<TData>[] {
  if (!customBulkActions) {
    return [];
  }

  const resolvedActions =
    typeof customBulkActions === "function"
      ? customBulkActions(context)
      : customBulkActions;

  if (!Array.isArray(resolvedActions)) {
    return [];
  }

  return resolvedActions.filter(isValidBulkAction<TData>);
}

export function resolveBulkActionDisabled<TData>({
  action,
  context,
}: {
  action: BulkAction<TData>;
  context: BulkActionContext<TData>;
}): boolean {
  if (typeof action.disabled === "function") {
    return action.disabled(context);
  }

  return action.disabled === true;
}

export function buildBulkActionsMenuActionTabs<TData>({
  canSelectAll,
  customBulkActions,
  isSelectingAll,
  selectAllCount,
  selectedRows,
  showBulkDelete,
  showBulkEdit,
  showBulkExport,
}: BulkActionsMenuActionTabsOptions<TData>): BulkActionsMenuActionTab<TData>[] {
  const selectedCount = selectedRows.length;
  const context = createBulkActionContext(selectedRows);
  const customActionTabs = resolveCustomBulkActions({
    context,
    customBulkActions,
  }).map((action) => ({
    action,
    disabled: resolveBulkActionDisabled({ action, context }),
    icon: action.icon,
    id: action.id,
    kind: "custom" as const,
    label: action.label,
    variant: action.variant ?? "default",
  }));

  return [
    ...(canSelectAll
      ? [
          {
            id: "selectAll" as const,
            icon: isSelectingAll ? Loader2 : CheckCheck,
            kind: "built-in" as const,
            translationKey: "bulk.select_all",
            translationParams: {
              count: selectAllCount ?? selectedCount,
            },
            variant: "default" as const,
            disabled: isSelectingAll,
          },
        ]
      : []),
    ...(showBulkEdit
      ? [
          {
            id: "edit" as const,
            icon: Edit,
            kind: "built-in" as const,
            translationKey: "actions.edit",
            variant: "default" as const,
          },
        ]
      : []),
    {
      id: "copy" as const,
      icon: Copy,
      kind: "built-in" as const,
      translationKey: "actions.copy",
      variant: "default" as const,
    },
    ...(showBulkExport
      ? [
          {
            id: "export" as const,
            icon: Download,
            kind: "built-in" as const,
            translationKey: "actions.export",
            variant: "default" as const,
          },
        ]
      : []),
    ...customActionTabs,
    ...(showBulkDelete
      ? [
          {
            id: "delete" as const,
            icon: Trash2,
            kind: "built-in" as const,
            translationKey: "actions.delete",
            variant: "destructive" as const,
          },
        ]
      : []),
  ];
}

export async function executeCustomBulkAction<TData>({
  action,
  context,
}: {
  action: BulkAction<TData>;
  context: BulkActionContext<TData>;
}): Promise<BulkActionResult | undefined> {
  if (resolveBulkActionDisabled({ action, context })) {
    return;
  }

  try {
    const rawResult = await Promise.resolve(action.onClick(context));
    return normalizeBulkActionResult(
      rawResult,
      DEFAULT_CUSTOM_BULK_ACTION_RESULT
    );
  } catch (error) {
    const message =
      error instanceof Error && error.message.trim().length > 0
        ? error.message
        : "Bulk action failed.";
    return {
      ...DEFAULT_CUSTOM_BULK_ACTION_FAILURE_RESULT,
      message,
    };
  }
}

export function applyCustomBulkActionResult({
  onClearSelection,
  onDismissMenu,
  result,
}: {
  onClearSelection?: () => void;
  onDismissMenu?: () => void;
  result: BulkActionResult;
}): void {
  if (result.clearSelection) {
    onClearSelection?.();
  }

  if (result.closeMenu) {
    onDismissMenu?.();
  }
}

function showBulkActionResultMessage(result: BulkActionResult): void {
  if (!result.message || result.message.trim().length === 0) {
    return;
  }

  if (result.success) {
    toast.success(result.message);
    return;
  }

  toast.error(result.message);
}

export function shouldIgnoreOutsideClickForBulkMenu(
  state: Pick<
    BulkMenuOutsideClickState,
    "isConfirmingAction" | "showConfirmation"
  >
): boolean {
  return state.showConfirmation || state.isConfirmingAction;
}

export function getBulkMenuStateAfterOutsideClick(
  state: BulkMenuOutsideClickState
): BulkMenuOutsideClickState {
  if (shouldIgnoreOutsideClickForBulkMenu(state)) {
    return state;
  }

  return {
    ...state,
    hoveredAction: null,
    selectedAction: null,
    showConfirmation: false,
  };
}

async function executeImmediateBulkAction<TData>({
  actionId,
  onBulkEdit,
  onBulkExport,
  selectedRows,
}: {
  actionId: "edit" | "export";
  onBulkEdit?: (
    rows: Row<TData>[]
  ) => Promise<BulkActionCustomHandlerResult> | BulkActionCustomHandlerResult;
  onBulkExport?: (
    rows: Row<TData>[]
  ) => Promise<BulkActionCustomHandlerResult> | BulkActionCustomHandlerResult;
  selectedRows: Row<TData>[];
}): Promise<BulkActionResult> {
  try {
    if (actionId === "edit") {
      const rawResult = await Promise.resolve(onBulkEdit?.(selectedRows));
      return normalizeBulkActionResult(
        rawResult,
        DEFAULT_BULK_ACTION_RESULTS[actionId]
      );
    }

    const rawResult = await Promise.resolve(onBulkExport?.(selectedRows));
    return normalizeBulkActionResult(
      rawResult,
      DEFAULT_BULK_ACTION_RESULTS[actionId]
    );
  } catch {
    return {
      ...DEFAULT_BULK_ACTION_RESULTS[actionId],
      closeMenu: false,
      success: false,
    };
  }
}

async function executeConfirmableBulkAction<TData>({
  action,
  onBulkCopy,
  onBulkDelete,
  selectedRows,
}: {
  action: ConfirmableMenuActionId;
  onBulkCopy?: (
    rows: Row<TData>[]
  ) => Promise<BulkActionCustomHandlerResult> | BulkActionCustomHandlerResult;
  onBulkDelete?: (
    rows: Row<TData>[]
  ) => Promise<BulkDeleteCustomHandlerResult> | BulkDeleteCustomHandlerResult;
  selectedRows: Row<TData>[];
}): Promise<BulkActionResult> {
  try {
    if (action === "copy") {
      const rawResult = await Promise.resolve(onBulkCopy?.(selectedRows));
      return normalizeBulkActionResult(
        rawResult,
        DEFAULT_BULK_ACTION_RESULTS[action]
      );
    }

    const rawResult = await Promise.resolve(onBulkDelete?.(selectedRows));
    return normalizeBulkActionResult(
      rawResult,
      DEFAULT_BULK_ACTION_RESULTS[action]
    );
  } catch {
    return {
      ...DEFAULT_BULK_ACTION_RESULTS[action],
      closeMenu: false,
      success: false,
    };
  }
}

export async function executeConfirmableBulkActionWithLock<TData>({
  action,
  lockRef,
  onBulkCopy,
  onBulkDelete,
  selectedRows,
}: {
  action: ConfirmableMenuActionId;
  lockRef: { current: boolean };
  onBulkCopy?: (
    rows: Row<TData>[]
  ) => Promise<BulkActionCustomHandlerResult> | BulkActionCustomHandlerResult;
  onBulkDelete?: (
    rows: Row<TData>[]
  ) => Promise<BulkDeleteCustomHandlerResult> | BulkDeleteCustomHandlerResult;
  selectedRows: Row<TData>[];
}): Promise<BulkActionResult | undefined> {
  if (lockRef.current) {
    return;
  }

  lockRef.current = true;
  try {
    return await executeConfirmableBulkAction({
      action,
      onBulkCopy,
      onBulkDelete,
      selectedRows,
    });
  } finally {
    lockRef.current = false;
  }
}

/**
 * BulkActionsMenu Component
 *
 * Displays an overlay menu with expandable tabs for bulk actions
 * when multiple rows are selected in the data table
 */
export function BulkActionsMenu<TData>({
  selectedRows,
  onBulkEdit,
  onBulkDelete,
  onBulkCopy,
  onBulkExport,
  customBulkActions,
  onClearSelection,
  onClose,
  className,
  showBulkExport = true,
  showBulkEdit = true,
  showBulkDelete = true,
  positionMode = "anchored",
  canSelectAll = false,
  selectAllCount,
  onSelectAll,
  isSelectingAll = false,
  viewportBottomOffset,
}: BulkActionsMenuProps<TData>) {
  const [selectedAction, setSelectedAction] = useState<string | null>(null);
  const [hoveredAction, setHoveredAction] = useState<string | null>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [isConfirmingAction, setIsConfirmingAction] = useState(false);
  const [dismissedSelectionKey, setDismissedSelectionKey] = useState<
    string | null
  >(null);
  const pendingActionRef = useRef<BulkActionsMenuActionTab<TData> | null>(null);
  const confirmationLockRef = useRef(false);
  const outsideClickRef = useRef<HTMLDivElement>(null);
  const { t } = useTranslations();
  const showSelectAllAction = canSelectAll && typeof onSelectAll === "function";
  const selectedRowsKey = useMemo(
    () => selectedRows.map((row) => row.id).join("|"),
    [selectedRows]
  );
  const actionContext = useMemo(
    () => createBulkActionContext(selectedRows),
    [selectedRows]
  );
  const selectedCount = actionContext.selectedCount;
  const actionTabs = useMemo(
    () =>
      buildBulkActionsMenuActionTabs({
        canSelectAll: showSelectAllAction,
        customBulkActions,
        isSelectingAll,
        selectAllCount,
        selectedRows,
        showBulkDelete,
        showBulkEdit,
        showBulkExport,
      }),
    [
      customBulkActions,
      isSelectingAll,
      selectAllCount,
      selectedRows,
      showBulkDelete,
      showBulkEdit,
      showBulkExport,
      showSelectAllAction,
    ]
  );

  useOnClickOutside(outsideClickRef as RefObject<HTMLElement>, () => {
    const nextState = getBulkMenuStateAfterOutsideClick({
      hoveredAction,
      isConfirmingAction,
      selectedAction,
      showConfirmation,
    });

    setHoveredAction(nextState.hoveredAction);
    setSelectedAction(nextState.selectedAction);
    setShowConfirmation(nextState.showConfirmation);
  });

  if (
    !shouldRenderBulkActionsMenu(selectedRows) ||
    dismissedSelectionKey === selectedRowsKey
  ) {
    return null;
  }

  const dismissMenu = () => {
    setDismissedSelectionKey(selectedRowsKey);
  };

  const handleCustomActionResult = (result: BulkActionResult | undefined) => {
    if (!result) {
      return;
    }

    showBulkActionResultMessage(result);
    applyCustomBulkActionResult({
      result,
      onClearSelection: onClearSelection ?? onClose,
      onDismissMenu: dismissMenu,
    });
  };

  const handleTabClick = (tab: BulkActionsMenuActionTab<TData>) => {
    if (isConfirmingAction) {
      return;
    }

    if (tab.disabled) {
      return;
    }

    if (tab.kind === "custom") {
      if (tab.action.confirm) {
        pendingActionRef.current = tab;
        setSelectedAction(tab.id);
        setShowConfirmation(true);
        return;
      }

      executeCustomBulkAction({
        action: tab.action,
        context: actionContext,
      }).then(handleCustomActionResult);
      return;
    }

    if (tab.id === "selectAll") {
      if (!onSelectAll || isSelectingAll) {
        return;
      }

      Promise.resolve(onSelectAll()).catch(() => undefined);
      return;
    }

    if (tab.id === "edit" || tab.id === "export") {
      executeImmediateBulkAction({
        actionId: tab.id,
        onBulkEdit,
        onBulkExport,
        selectedRows,
      }).then((result) => {
        if (result.closeMenu) {
          onClose?.();
        }
      });
      return;
    }

    pendingActionRef.current = tab;
    setSelectedAction(tab.id);
    setShowConfirmation(true);
  };

  const handleConfirmAction = () => {
    const pendingAction = pendingActionRef.current;
    if (!pendingAction || confirmationLockRef.current || isConfirmingAction) {
      return;
    }

    setIsConfirmingAction(true);
    if (pendingAction.kind === "custom") {
      confirmationLockRef.current = true;
      executeCustomBulkAction({
        action: pendingAction.action,
        context: actionContext,
      })
        .then(handleCustomActionResult)
        .finally(() => {
          confirmationLockRef.current = false;
          pendingActionRef.current = null;
          setSelectedAction(null);
          setShowConfirmation(false);
          setIsConfirmingAction(false);
        });
      return;
    }

    if (pendingAction.id !== "copy" && pendingAction.id !== "delete") {
      pendingActionRef.current = null;
      setSelectedAction(null);
      setShowConfirmation(false);
      setIsConfirmingAction(false);
      return;
    }

    executeConfirmableBulkActionWithLock({
      action: pendingAction.id,
      lockRef: confirmationLockRef,
      onBulkCopy,
      onBulkDelete,
      selectedRows,
    })
      .then((result) => {
        if (result?.closeMenu) {
          onClose?.();
        }
      })
      .finally(() => {
        pendingActionRef.current = null;
        setSelectedAction(null);
        setShowConfirmation(false);
        setIsConfirmingAction(false);
      });
  };

  const handleCancel = () => {
    if (isConfirmingAction || confirmationLockRef.current) {
      return;
    }
    pendingActionRef.current = null;
    setSelectedAction(null);
    setShowConfirmation(false);
  };

  const handleClose = () => {
    if (isConfirmingAction || confirmationLockRef.current) {
      return;
    }
    pendingActionRef.current = null;
    setSelectedAction(null);
    setHoveredAction(null);
    setShowConfirmation(false);
    onClose?.();
  };

  const getSelectedAction = () => {
    return actionTabs.find((tab) => tab.id === selectedAction);
  };

  const getActionLabel = (tab: BulkActionsMenuActionTab<TData> | undefined) => {
    if (!tab) {
      return "";
    }

    return tab.kind === "custom"
      ? tab.label
      : t(tab.translationKey, tab.translationParams);
  };

  const resolveConfirmText = (
    value: string | ((ctx: BulkActionContext<TData>) => string) | undefined
  ) => {
    return typeof value === "function" ? value(actionContext) : value;
  };

  const getConfirmationTitle = () => {
    const currentAction = getSelectedAction();
    if (currentAction?.kind === "custom") {
      const customTitle = resolveConfirmText(
        currentAction.action.confirm?.title
      );
      if (customTitle) {
        return customTitle;
      }
    }

    return t("bulk.confirm_title", {
      action: getActionLabel(currentAction),
      count: selectedCount,
    });
  };

  const getConfirmationDescription = () => {
    const currentAction = getSelectedAction();
    if (currentAction?.kind === "custom") {
      const customDescription = resolveConfirmText(
        currentAction.action.confirm?.description
      );
      if (customDescription) {
        return customDescription;
      }
    }

    if (currentAction?.variant === "destructive") {
      return t("bulk.confirm_delete_description");
    }

    return t("bulk.confirm_copy_description", {
      count: selectedCount,
    });
  };

  const getCancelLabel = () => {
    const currentAction = getSelectedAction();
    if (currentAction?.kind === "custom") {
      const cancelLabel = resolveConfirmText(
        currentAction.action.confirm?.cancelLabel
      );
      if (cancelLabel) {
        return cancelLabel;
      }
    }

    return t("actions.cancel");
  };

  const getConfirmLabel = () => {
    const currentAction = getSelectedAction();
    if (isConfirmingAction) {
      return t("common.loading");
    }

    if (currentAction?.kind === "custom") {
      const confirmLabel = resolveConfirmText(
        currentAction.action.confirm?.confirmLabel
      );
      if (confirmLabel) {
        return confirmLabel;
      }
    }

    return t("actions.confirm");
  };

  const selectedActionTab = getSelectedAction();

  return (
    <LazyMotion features={domAnimation}>
      <div
        className={getBulkActionsMenuWrapperClassName({
          className,
          positionMode,
        })}
        style={getBulkActionsMenuWrapperStyle({
          positionMode,
          viewportBottomOffset,
        })}
      >
        <div className="pointer-events-auto flex flex-col items-center gap-4">
          {/* Confirmation dialog (consistent AlertDialog for copy/delete) */}
          <AlertDialog
            onOpenChange={(open) => {
              if (
                !(open || isConfirmingAction || confirmationLockRef.current)
              ) {
                handleCancel();
              }
            }}
            open={showConfirmation && !!selectedAction}
          >
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>{getConfirmationTitle()}</AlertDialogTitle>
                <AlertDialogDescription>
                  {getConfirmationDescription()}
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel
                  disabled={isConfirmingAction}
                  onClick={handleCancel}
                >
                  {getCancelLabel()}
                </AlertDialogCancel>
                <AlertDialogAction
                  className={
                    selectedActionTab?.variant === "destructive"
                      ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                      : undefined
                  }
                  disabled={isConfirmingAction}
                  onClick={handleConfirmAction}
                >
                  {getConfirmLabel()}
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>

          {/* Main menu with custom expandable tabs */}
          <div
            className="flex flex-wrap items-center gap-2 rounded-2xl border border-border/80 bg-secondary/95 p-1 text-secondary-foreground shadow-xl backdrop-blur-md"
            ref={outsideClickRef}
          >
            {/* Count indicator */}
            <div className="flex items-center gap-2 px-3">
              <div className="h-2 w-2 animate-pulse rounded-full bg-primary" />
              <span className="font-medium text-secondary-foreground text-sm">
                {t("selection.rows", { count: selectedCount })}
              </span>
            </div>

            {/* Action tabs */}
            {actionTabs.map((tab) => {
              const Icon = tab.icon;
              const isExpanded =
                hoveredAction === tab.id || selectedAction === tab.id;

              return (
                <m.button
                  animate="animate"
                  className={cn(
                    "relative flex items-center rounded-xl px-4 py-2 font-medium text-sm transition-colors duration-300",
                    tab.disabled &&
                      (tab.kind === "built-in" && tab.id === "selectAll"
                        ? "cursor-wait opacity-70"
                        : "cursor-not-allowed opacity-50"),
                    tab.variant === "destructive"
                      ? "text-destructive hover:bg-destructive/10 hover:text-destructive"
                      : "text-secondary-foreground/70 hover:bg-background/80 hover:text-secondary-foreground"
                  )}
                  custom={isExpanded}
                  disabled={tab.disabled}
                  initial={false}
                  key={tab.id}
                  onClick={() => handleTabClick(tab)}
                  onMouseEnter={() => setHoveredAction(tab.id)}
                  onMouseLeave={() => setHoveredAction(null)}
                  transition={transition}
                  type="button"
                  variants={buttonVariants}
                >
                  <Icon
                    className={cn(
                      tab.kind === "built-in" &&
                        tab.id === "selectAll" &&
                        isSelectingAll &&
                        "animate-spin"
                    )}
                    size={20}
                  />
                  <AnimatePresence initial={false}>
                    {isExpanded && (
                      <m.span
                        animate="animate"
                        className="overflow-hidden whitespace-nowrap"
                        exit="exit"
                        initial="initial"
                        transition={transition}
                        variants={spanVariants}
                      >
                        {getActionLabel(tab)}
                      </m.span>
                    )}
                  </AnimatePresence>
                </m.button>
              );
            })}

            {/* Separator */}
            <div
              aria-hidden="true"
              className="mx-1 h-[24px] w-[1.2px] bg-border/80"
            />

            {/* Close button */}
            <Button
              aria-label={t("bulk.close_menu")}
              className="h-8 w-8 p-0 text-secondary-foreground/70 hover:bg-background/80 hover:text-secondary-foreground"
              onClick={handleClose}
              size="sm"
              variant="ghost"
            >
              <X className="h-3 w-3" />
            </Button>
          </div>
        </div>
      </div>
    </LazyMotion>
  );
}

/**
 * Bulk Actions Components Export
 */

export type { BulkActionResult } from "../../hooks/use-bulk-actions";
export type {
  BulkAction,
  BulkActionConfirmConfig,
  BulkActionContext,
  BulkActionHandler,
  BulkActionHandlerResult,
  BulkActionsMenuProps,
  BulkActionVariant,
  CustomBulkActionsInput,
} from "./bulk-actions-menu";
export { BulkActionsMenu } from "./bulk-actions-menu";

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useSetAtom } from "jotai";
import { MoreHorizontal } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../providers/table-provider";
import type { Row } from "../../tanstack";
import { Icon } from "../../ui-custom/icon";

import type { ActionItem } from "../columns/actions-column";
import {
  type CatalogueFormState,
  catalogueFormAtom,
  openUpdateForm,
} from "../forms/atoms/catalogue-form-atoms";

// Type definition for ActionsCell props
interface ActionsCellProps<TData> {
  actions: ActionItem<TData>[];
  onRefresh?: () => Promise<void> | void;
  row: Row<TData>;
  /** When set, invalidations target ["tableData", tableId] per YaYaw Table contract */
  tableId?: string;
}

export function isStandardActionAllowed<TData>(
  rowData: TData,
  guard: ((row: TData) => boolean) | undefined
): boolean {
  return guard?.(rowData) !== false;
}

export function resolveEditFormTypeForRow<TData>({
  fallbackFormType,
  resolveEditFormType,
  rowData,
  tableId,
}: {
  fallbackFormType?: string;
  resolveEditFormType?: (row: TData) => string | undefined;
  rowData: TData;
  tableId?: string;
}): string | undefined {
  return resolveEditFormType?.(rowData) || fallbackFormType || tableId;
}

/**
 * Cell component for the actions column
 * Renders a dropdown menu with action buttons
 */
function ActionsCellBase<TData>({
  actions,
  onRefresh,
  row,
  tableId,
}: ActionsCellProps<TData>) {
  const { t } = useTranslations();
  const rowData = row.original;
  const _rowId = row.id;

  // Get query client for invalidating queries
  const queryClient = useQueryClient();

  // Create a stable version of the onRefresh callback
  const onRefreshRef = useRef(onRefresh);
  useEffect(() => {
    onRefreshRef.current = onRefresh;
  }, [onRefresh]);

  // Create a mutation for handling actions with automatic invalidation
  const actionMutation = useMutation({
    mutationFn: async (action: ActionItem<TData>) => {
      if (!action.onClick) {
        throw new Error("Action does not have an onClick handler");
      }
      return await action.onClick(rowData);
    },
    onSuccess: () => {
      // Target ["tableData", tableId] when tableId is set (YaYaw Table contract)
      const queryKey = tableId ? ["tableData", tableId] : ["tableData"];
      queryClient.invalidateQueries({ queryKey });

      // Also call the onRefresh function if provided
      if (onRefreshRef.current) {
        onRefreshRef.current();
      }
    },
  });

  // Helper function to determine if action opens a form
  const isFormAction = useCallback((action: ActionItem<TData>): boolean => {
    if (action.type !== "edit" || !action.onClick) {
      return false;
    }
    const actionString = action.onClick.toString();
    return (
      actionString.includes("openUpdateForm") ||
      actionString.includes("setFormState")
    );
  }, []);

  // Helper function to get success message for action
  const getSuccessMessage = useCallback(
    (_action: ActionItem<TData>): string => {
      // All actions use the same success message for now
      return t("common.success");
    },
    [t]
  );

  // Helper function to handle action execution
  const executeAction = useCallback(
    async (action: ActionItem<TData>): Promise<void> => {
      await actionMutation.mutateAsync(action);
    },
    [actionMutation]
  );

  // Helper function to handle toasts
  const handleToasts = useCallback(
    (action: ActionItem<TData>, toastId: string | number): void => {
      if (!isFormAction(action)) {
        const successMessage = getSuccessMessage(action);
        toast.success(successMessage, { id: toastId });
      }
    },
    [isFormAction, getSuccessMessage]
  );

  // Stable action click handler
  const handleActionClick = useCallback(
    async (action: ActionItem<TData>) => {
      try {
        const isForm = isFormAction(action);

        // Show loading toast for non-form actions
        let toastId: number | string = "";
        if (!isForm) {
          toastId = toast.loading(t("common.loading"));
        }

        // Execute the action
        await executeAction(action);

        // Handle success toasts
        handleToasts(action, toastId);
      } catch (error) {
        // Show error toast
        toast.error(error instanceof Error ? error.message : t("common.error"));
      }
    },
    [t, isFormAction, executeAction, handleToasts]
  );

  // Memoize action groups to prevent recalculation on every render
  const actionGroups = useMemo(() => {
    // Group actions by type
    const filteredStandardActions = actions.filter(
      (action) =>
        action.type === "view" ||
        action.type === "edit" ||
        action.type === "duplicate"
    );

    const filteredCustomActions = actions.filter(
      (action) => action.type === "custom" || !action.type
    );

    const filteredDestructiveActions = actions.filter(
      (action) => action.type === "delete"
    );

    // Only show separators if we have multiple groups of actions
    const calculatedShowFirstSeparator =
      filteredStandardActions.length > 0 &&
      (filteredCustomActions.length > 0 ||
        filteredDestructiveActions.length > 0);

    const calculatedShowSecondSeparator =
      filteredCustomActions.length > 0 && filteredDestructiveActions.length > 0;

    return {
      customActions: filteredCustomActions,
      destructiveActions: filteredDestructiveActions,
      showFirstSeparator: calculatedShowFirstSeparator,
      showSecondSeparator: calculatedShowSecondSeparator,
      standardActions: filteredStandardActions,
    };
  }, [actions]);

  const {
    customActions,
    destructiveActions,
    showFirstSeparator,
    showSecondSeparator,
    standardActions,
  } = actionGroups;

  // Memoize action groups rendering to prevent recalculation on every render
  const standardActionsGroup = useMemo(() => {
    if (standardActions.length === 0) {
      return null;
    }

    return (
      <DropdownMenuGroup>
        {standardActions.map((action) => {
          const isDisabled =
            typeof action.disabled === "function"
              ? action.disabled(rowData)
              : action.disabled;

          return (
            <DropdownMenuItem
              className={action.className}
              disabled={isDisabled}
              key={`standard-${action.type}`}
              onClick={() => handleActionClick(action)}
            >
              {action.icon && <span className="mr-2">{action.icon}</span>}
              {action.label}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuGroup>
    );
  }, [standardActions, rowData, handleActionClick]);

  const customActionsGroup = useMemo(() => {
    if (customActions.length === 0) {
      return null;
    }

    return (
      <DropdownMenuGroup>
        {customActions.map((action) => {
          const isDisabled =
            typeof action.disabled === "function"
              ? action.disabled(rowData)
              : action.disabled;

          return (
            <DropdownMenuItem
              className={action.className}
              disabled={isDisabled}
              key={`custom-${action.label}`}
              onClick={() => handleActionClick(action)}
            >
              {action.icon && <span className="mr-2">{action.icon}</span>}
              {action.label}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuGroup>
    );
  }, [customActions, rowData, handleActionClick]);

  const destructiveActionsGroup = useMemo(() => {
    if (destructiveActions.length === 0) {
      return null;
    }

    return (
      <DropdownMenuGroup>
        {destructiveActions.map((action) => {
          const isDisabled =
            typeof action.disabled === "function"
              ? action.disabled(rowData)
              : action.disabled;

          return (
            <DropdownMenuItem
              className={cn("text-destructive", action.className)}
              disabled={isDisabled}
              key={`destructive-${action.label}`}
              onClick={() => handleActionClick(action)}
            >
              {action.icon && <span className="mr-2">{action.icon}</span>}
              {action.label || "Delete"}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuGroup>
    );
  }, [destructiveActions, rowData, handleActionClick]);

  return (
    <div className="flex justify-center">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label="Open actions menu"
              className="h-8 w-8 p-0"
              type="button"
              variant="ghost"
            >
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          }
        />
        <DropdownMenuContent align="end">
          {/* Standard actions group */}
          {standardActionsGroup}

          {/* Separator between standard and custom actions */}
          {showFirstSeparator && <DropdownMenuSeparator />}

          {/* Custom actions */}
          {customActionsGroup}

          {/* Separator before destructive actions */}
          {showSecondSeparator && <DropdownMenuSeparator />}

          {/* Destructive actions */}
          {destructiveActionsGroup}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

export const ActionsCell = ActionsCellBase;

/**
 * Wrapper component that creates the cell content with translations
 * This is needed because we can't use hooks directly in the column definition
 */
export function ActionsCellWithTranslations<
  TData extends Record<string, unknown>,
>({
  actions,
  onRefresh,
  row,
  standardActions,
}: {
  actions: ActionItem<TData>[];
  onRefresh?: () => Promise<void> | void;
  row: Row<TData>;
  standardActions: {
    includeDelete: boolean;
    includeDuplicate?: boolean;
    includeEdit: boolean;
    includeView?: boolean;
    canDeleteRow?: (rowData: TData) => boolean;
    canDuplicateRow?: (rowData: TData) => boolean;
    canEditRow?: (rowData: TData) => boolean;
    formType?: string;
    onDelete?: (rowData: TData) => Promise<boolean | undefined> | undefined;
    onDuplicate?: (rowData: TData) => Promise<boolean | undefined> | undefined;
    onEdit?: (rowData: TData) => Promise<boolean | undefined> | undefined;
    onView?: (rowData: TData) => Promise<boolean | undefined> | undefined;
    resolveEditFormType?: (rowData: TData) => string | undefined;
    /**
     * Table ID to use for the form
     * If provided, will be used to determine the form type
     */
    tableId?: string;
    tableType?: string;
  };
}) {
  const { t } = useTranslations();
  const allActions: ActionItem<TData>[] = [...actions];
  // Get the setAtom function for the catalogue form
  const setFormState = useSetAtom(catalogueFormAtom);
  // Get the query client for invalidating queries
  const queryClient = useQueryClient();

  // Stable reference to the tableId to prevent callback recreation
  const tableIdRef = useRef(standardActions.tableId);
  tableIdRef.current = standardActions.tableId;

  // Add standard view action if requested
  if (standardActions.includeView && standardActions.onView) {
    allActions.unshift({
      icon: <Icon name="Eye" size="sm" />,
      label: t("actions.view"),
      onClick: standardActions.onView,
      type: "view",
    });
  }

  // Create an edit handler that uses the Jotai atom with stable dependencies
  const handleEdit = useCallback(
    (rowData: TData): Promise<boolean | undefined> | undefined => {
      try {
        // Only proceed if edit action is included
        if (
          !(
            standardActions.includeEdit &&
            isStandardActionAllowed(rowData, standardActions.canEditRow)
          )
        ) {
          return;
        }

        // Check if we have a tableId in the standardActions or in the row
        const tableId =
          tableIdRef.current ||
          (rowData && typeof rowData === "object" && "tableId" in rowData
            ? String(rowData.tableId)
            : undefined);
        const editFormType = resolveEditFormTypeForRow({
          fallbackFormType: standardActions.formType,
          resolveEditFormType: standardActions.resolveEditFormType,
          rowData,
          tableId,
        });

        // If we have a tableId, use it to open the form
        if (tableId && editFormType) {
          // Pass the row data directly to maintain the generic nature of the component
          const initialData = rowData;

          // Create a simple success callback that doesn't capture complex dependencies
          const handleSuccess = (_data: unknown) => {
            try {
              // Invalidate the table data query to refresh the table
              queryClient.invalidateQueries({
                queryKey: ["tableData", tableId],
              });

              // Also call the onRefresh function if provided
              if (onRefresh && typeof onRefresh === "function") {
                onRefresh();
              }
            } catch {
              // Ignore error in refresh
            }
          };

          // Create the initial state for the form
          const formState = openUpdateForm(
            editFormType,
            tableId,
            initialData, // Use the row data as initial form data
            handleSuccess,
            standardActions.tableType
          );

          // Set the form state directly
          setFormState(
            formState as CatalogueFormState<Record<string, unknown>>
          );
          return;
        }

        // Otherwise, use the standard onEdit handler if provided
        if (standardActions.onEdit) {
          return standardActions.onEdit(rowData);
        }
        return;
      } catch {
        return;
      }
    },
    [
      standardActions.includeEdit,
      standardActions.onEdit,
      standardActions.canEditRow,
      standardActions.formType,
      standardActions.resolveEditFormType,
      standardActions.tableType,
      onRefresh,
      setFormState,
      queryClient,
    ]
  );

  // Add edit action to the dropdown menu if edit is included
  if (standardActions.includeEdit) {
    allActions.unshift({
      disabled: (rowData) =>
        !isStandardActionAllowed(rowData, standardActions.canEditRow),
      icon: <Icon name="Pencil" size="sm" />,
      label: t("actions.edit"),
      onClick: handleEdit,
      type: "edit",
    });
  }

  // Add standard duplicate action if requested
  if (standardActions.includeDuplicate && standardActions.onDuplicate) {
    allActions.push({
      disabled: (rowData) =>
        !isStandardActionAllowed(rowData, standardActions.canDuplicateRow),
      icon: <Icon name="Copy" size="sm" />,
      label: t("actions.duplicate"),
      onClick: (rowData) => {
        if (
          !isStandardActionAllowed(rowData, standardActions.canDuplicateRow)
        ) {
          return;
        }
        return standardActions.onDuplicate?.(rowData);
      },
      type: "duplicate",
    });
  }

  // Add standard delete action if requested
  if (standardActions.includeDelete && standardActions.onDelete) {
    allActions.push({
      disabled: (rowData) =>
        !isStandardActionAllowed(rowData, standardActions.canDeleteRow),
      icon: <Icon name="Trash" size="sm" />,
      label: t("actions.delete"),
      onClick: (rowData) => {
        if (!isStandardActionAllowed(rowData, standardActions.canDeleteRow)) {
          return;
        }
        return standardActions.onDelete?.(rowData);
      },
      type: "delete",
    });
  }

  // Process other actions to ensure they have proper translations
  const processedActions = allActions.map((action) => {
    // If it's already a standard action with translation, return as is
    if (["delete", "duplicate", "edit", "view"].includes(action.type || "")) {
      return action;
    }

    return {
      ...action,
      // If the label looks like a translation key, translate it
      label: action.label.includes(".") ? t(action.label) : action.label,
    };
  });

  return (
    <ActionsCell
      actions={processedActions}
      onRefresh={onRefresh}
      row={row}
      tableId={standardActions.tableId}
    />
  );
}

