"use client";

import type { ReactNode } from "react";
import type {
  InlineEditColumnRuntimeConfig,
  InlineEditCommitResult,
} from "../../hooks/use-inline-edit-runtime";
import type { Cell } from "../../tanstack";
import {
  canEditInlineFormField,
  validateInlineFormValue,
} from "../forms/inline-form";
import type { FormConfig, FormConfigContext } from "../forms/types";
import { InlineEditableCell } from "./inline-editable-cell";

export function CatalogueInlineCell<TData extends Record<string, unknown>>({
  cell,
  context,
  config,
  inlineConfig,
  displayValue,
  onCommit,
}: {
  cell: Cell<TData, unknown>;
  context: FormConfigContext;
  config?: FormConfig;
  inlineConfig: InlineEditColumnRuntimeConfig;
  displayValue: ReactNode;
  onCommit: (value: unknown) => Promise<InlineEditCommitResult>;
}) {
  const field = config?.fields.find(
    (candidate) => candidate.name === inlineConfig.formField
  );
  if (!canEditInlineFormField(config, field, context)) {
    return displayValue;
  }
  return (
    <InlineEditableCell
      cell={cell}
      displayValue={displayValue}
      formFieldDefinition={field}
      inlineConfig={inlineConfig}
      onCommit={async (value) => {
        const result = await validateInlineFormValue(
          config,
          inlineConfig.formField,
          value,
          context
        );
        return result.success ? await onCommit(result.committedValue) : result;
      }}
      rowData={cell.row.original}
    />
  );
}

/**
 * Code cell component for data tables
 * Shows code values with monospace font styling
 */
"use client";

import { cn } from "@/lib/utils";

export interface CodeCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * The code value to display
   */
  value: unknown;
}

/**
 * Cell component for displaying code values with monospace font
 */
export function CodeCell({ className = "", value }: CodeCellProps) {
  // Handle Prisma JSON objects with 'set' property
  if (value && typeof value === "object" && "set" in value) {
    value = (value as { set: unknown }).set;
  }

  // Handle null or undefined
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground">-</span>;
  }

  // Convert to string
  const codeValue = String(value);

  // Display with monospace font
  return (
    <code
      className={cn(
        "rounded bg-muted px-1.5 py-0.5 font-mono text-sm",
        className
      )}
    >
      {codeValue}
    </code>
  );
}

/**
 * Date cell component for data tables
 * Shows formatted date values with appropriate styling
 */
"use client";

import { useLocale } from "../../providers/table-provider";
import type { DateDisplayPreset } from "../../types/date-types";
import { formatDateForDisplay, toValidDate } from "../../utils/date-display";

export interface DateCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Date format string (date-fns compatible)
   * @default "PPP" (localized date with month name)
   */
  dateFormat?: string;

  /**
   * Date display preset (strict preset-based formatting)
   */
  dateDisplayPreset?: DateDisplayPreset;

  /**
   * Fallback date display preset (typically table-level default)
   */
  fallbackDateDisplayPreset?: DateDisplayPreset;

  /**
   * Whether to show the time
   * @default false
   */
  showTime?: boolean;

  /**
   * The date value to display
   */
  value: Date | null | number | string | undefined;
}

/**
 * Cell component for displaying formatted date values
 */
export function DateCell({
  className = "",
  dateFormat = "PPP",
  dateDisplayPreset,
  fallbackDateDisplayPreset,
  showTime = false,
  value,
}: DateCellProps) {
  const locale = useLocale();

  // If the value is not a valid date, return a placeholder
  if (!value) {
    return <span className="text-muted-foreground">-</span>;
  }

  // If the input cannot be parsed to a valid date, keep explicit fallback.
  if (!toValidDate(value)) {
    return <span className="text-muted-foreground">Invalid date</span>;
  }

  const displayValue = formatDateForDisplay(value, {
    dateDisplayPreset,
    fallbackDateDisplayPreset,
    dateFormat,
    locale,
    showTime,
  });

  if (!displayValue) {
    return <span className="text-muted-foreground">Invalid date</span>;
  }

  return <span className={className}>{displayValue}</span>;
}

"use client";

import { ImageIcon } from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { resolveImageSource } from "../../utils/image-source";

interface ImageCellProps {
  alt?: string;
  className?: string;
  fallbackLabel?: string;
  value: unknown;
}

export function ImageCell({
  alt,
  className,
  fallbackLabel,
  value,
}: ImageCellProps) {
  const [hasError, setHasError] = useState(false);
  const source = hasError ? undefined : resolveImageSource(value);
  const label = alt || fallbackLabel || "Image";

  if (!source) {
    return (
      <div
        className={cn(
          "flex h-10 w-14 items-center justify-center rounded-md border bg-muted text-muted-foreground",
          className
        )}
      >
        <ImageIcon aria-hidden className="h-4 w-4" />
        <span className="sr-only">{label}</span>
      </div>
    );
  }

  return (
    // biome-ignore lint/performance/noImgElement: registry consumers should not need Next.js image domain configuration.
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: onError swaps broken media to the non-interactive fallback.
    <img
      alt={label}
      className={cn(
        "h-10 w-14 rounded-md border bg-muted object-cover",
        className
      )}
      height={40}
      loading="lazy"
      onError={() => setHasError(true)}
      src={source}
      width={56}
    />
  );
}

export * from "./actions-cell";
export * from "./boolean-cell";
