"use client";

import type { KeyboardEvent, ReactNode } from "react";
import { memo, useCallback, useMemo } from "react";
import {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxList,
  useComboboxAnchor,
} from "@/components/ui/combobox";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import {
  type InlineEditColumnRuntimeConfig,
  type InlineEditCommitResult,
  type InlineEditValidationSchema,
  parseInlineEditValue,
  resolveInlineEditOptions,
  resolveInlineEditor,
  toInlineEditDraftValue,
  useInlineEditRuntime,
  validateInlineEditValue,
} from "../../hooks/use-inline-edit-runtime";
import { useTranslations } from "../../providers/table-provider";
import type { Cell } from "../../tanstack";
import type { AnyFieldDefinition } from "../forms/types";

interface InlineEditableCellProps<TData extends Record<string, unknown>> {
  cell: Cell<TData, unknown>;
  inlineConfig: InlineEditColumnRuntimeConfig;
  displayValue: ReactNode;
  rowData: Record<string, unknown>;
  formFieldDefinition?: AnyFieldDefinition;
  schema?: InlineEditValidationSchema;
  onCommit: (value: unknown) => Promise<InlineEditCommitResult>;
}

interface NormalizedSelectOption {
  label: string;
  value: string;
}

function getEditorCurrentValues(
  editor: InlineEditColumnRuntimeConfig["editor"],
  editorValue: unknown
): string[] {
  if (editor === "multiSelect") {
    if (!Array.isArray(editorValue)) {
      return [];
    }
    return editorValue.map((value) => String(value));
  }

  return [String(editorValue)];
}

function normalizeSelectOptions({
  editor,
  editorValue,
  options,
}: {
  editor: InlineEditColumnRuntimeConfig["editor"];
  editorValue: unknown;
  options: InlineEditColumnRuntimeConfig["options"];
}): NormalizedSelectOption[] {
  if (editor !== "select" && editor !== "multiSelect") {
    return [];
  }

  const normalizedOptions = new Map<string, NormalizedSelectOption>();

  for (const option of options) {
    const normalizedValue = String(option.value);
    if (normalizedValue.length === 0) {
      continue;
    }

    normalizedOptions.set(normalizedValue, {
      label: option.label,
      value: normalizedValue,
    });
  }

  const currentValues = getEditorCurrentValues(editor, editorValue);
  for (const currentValue of currentValues) {
    if (currentValue.length === 0 || normalizedOptions.has(currentValue)) {
      continue;
    }

    normalizedOptions.set(currentValue, {
      label: currentValue,
      value: currentValue,
    });
  }

  return Array.from(normalizedOptions.values());
}

function InlineEditableCellBase<TData extends Record<string, unknown>>({
  cell,
  inlineConfig,
  displayValue,
  rowData,
  formFieldDefinition,
  schema,
  onCommit,
}: InlineEditableCellProps<TData>) {
  const { t } = useTranslations();

  const resolvedOptions = useMemo(
    () => resolveInlineEditOptions(inlineConfig.options, formFieldDefinition),
    [formFieldDefinition, inlineConfig.options]
  );

  const resolvedEditor = useMemo(
    () =>
      resolveInlineEditor({
        explicitEditor: inlineConfig.editor,
        columnType: inlineConfig.columnType,
        formFieldType: formFieldDefinition?.type,
        hasOptions: resolvedOptions.length > 0,
      }),
    [
      formFieldDefinition?.type,
      inlineConfig.columnType,
      inlineConfig.editor,
      resolvedOptions.length,
    ]
  );

  const runtimeCommit = useCallback(
    async (draftValue: unknown): Promise<InlineEditCommitResult> => {
      const parsedResult = parseInlineEditValue({
        editor: resolvedEditor,
        rawValue: draftValue,
        options: resolvedOptions,
      });

      if (!parsedResult.success) {
        return {
          success: false,
          errorMessage: parsedResult.errorMessage ?? t("inline.invalid_value"),
        };
      }

      const validationResult = validateInlineEditValue({
        editor: resolvedEditor,
        candidateValue: parsedResult.value,
        formField: inlineConfig.formField,
        rowData,
        schema,
      });

      if (!validationResult.success) {
        return {
          success: false,
          errorMessage:
            validationResult.errorMessage ?? t("inline.invalid_value"),
        };
      }

      return await onCommit(parsedResult.value);
    },
    [
      inlineConfig.formField,
      onCommit,
      resolvedEditor,
      resolvedOptions,
      rowData,
      schema,
      t,
    ]
  );

  const {
    commitAndClose,
    delayProgress,
    draftValue,
    errorMessage,
    isDirty,
    isEditing,
    isSaving,
    scheduledAt,
    startEditing,
    stopEditing,
    cancelEditing,
    updateDraftValue,
  } = useInlineEditRuntime({
    initialValue: cell.getValue(),
    editor: resolvedEditor,
    debounceMs: inlineConfig.debounceMs,
    onCommit: runtimeCommit,
  });

  const handleDisplayKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>) => {
      if (event.key !== "Enter") {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      startEditing();
    },
    [startEditing]
  );

  const handleEditorKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        cancelEditing();
        return;
      }

      if (event.key !== "Enter") {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      commitAndClose().catch(() => undefined);
    },
    [cancelEditing, commitAndClose]
  );

  const handleEditorBlur = useCallback(() => {
    commitAndClose().catch(() => undefined);
  }, [commitAndClose]);

  const editorValue = useMemo(() => {
    return toInlineEditDraftValue(draftValue, resolvedEditor);
  }, [draftValue, resolvedEditor]);

  const selectOptions = useMemo(() => {
    return normalizeSelectOptions({
      editor: resolvedEditor,
      editorValue,
      options: resolvedOptions,
    });
  }, [editorValue, resolvedEditor, resolvedOptions]);

  const multiSelectAnchorRef = useComboboxAnchor();
  const selectedMultiValues = useMemo(() => {
    if (resolvedEditor !== "multiSelect" || !Array.isArray(editorValue)) {
      return [];
    }

    return editorValue.map((value) => String(value));
  }, [editorValue, resolvedEditor]);

  const getOptionLabel = useCallback(
    (optionValue: string): string => {
      const matchingOption = selectOptions.find(
        (option) => option.value === optionValue
      );
      return matchingOption?.label ?? optionValue;
    },
    [selectOptions]
  );

  const renderTextareaEditor = useCallback(() => {
    return (
      <Textarea
        className="min-h-20 py-1 text-sm"
        onBlur={handleEditorBlur}
        onChange={(event) => {
          updateDraftValue(event.target.value);
        }}
        onKeyDown={handleEditorKeyDown}
        rows={resolvedEditor === "json" ? 6 : 4}
        value={String(editorValue)}
      />
    );
  }, [
    editorValue,
    handleEditorBlur,
    handleEditorKeyDown,
    resolvedEditor,
    updateDraftValue,
  ]);

  const renderBooleanEditor = useCallback(() => {
    return (
      <div className="flex min-h-8 items-center gap-2 px-1">
        <Switch
          checked={Boolean(editorValue)}
          onBlur={handleEditorBlur}
          onCheckedChange={(checked) => {
            updateDraftValue(Boolean(checked));
          }}
        />
        <span className="text-muted-foreground text-xs">
          {editorValue ? t("common.true") : t("common.false")}
        </span>
      </div>
    );
  }, [editorValue, handleEditorBlur, t, updateDraftValue]);

  const renderSelectEditor = useCallback(() => {
    return (
      <Select
        onOpenChange={(open) => {
          if (!open) {
            stopEditing();
          }
        }}
        onValueChange={(value) => {
          updateDraftValue(value ?? "");
        }}
        value={String(editorValue)}
      >
        <SelectTrigger className="h-8 w-full">
          <SelectValue placeholder={t("inline.select_no_options")} />
        </SelectTrigger>
        <SelectContent>
          {selectOptions.length === 0 ? (
            <SelectItem disabled value="__no-options__">
              {t("inline.select_no_options")}
            </SelectItem>
          ) : (
            selectOptions.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))
          )}
        </SelectContent>
      </Select>
    );
  }, [editorValue, selectOptions, stopEditing, t, updateDraftValue]);

  const renderMultiSelectEditor = useCallback(() => {
    return (
      <Combobox
        multiple
        onOpenChange={(open) => {
          if (!open) {
            stopEditing();
          }
        }}
        onValueChange={(values) => {
          updateDraftValue(
            Array.isArray(values) ? values.map((value) => String(value)) : []
          );
        }}
        value={selectedMultiValues}
      >
        <ComboboxChips className="w-full" ref={multiSelectAnchorRef}>
          {selectedMultiValues.map((selectedValue) => (
            <ComboboxChip key={selectedValue}>
              {getOptionLabel(selectedValue)}
            </ComboboxChip>
          ))}
          <ComboboxChipsInput
            className="h-6 min-w-16"
            onKeyDown={(event) => {
              if (event.key !== "Escape") {
                return;
              }

              event.preventDefault();
              event.stopPropagation();
              cancelEditing();
            }}
            placeholder={
              selectedMultiValues.length === 0
                ? t("inline.select_no_options")
                : undefined
            }
          />
        </ComboboxChips>
        <ComboboxContent anchor={multiSelectAnchorRef}>
          <ComboboxList>
            <ComboboxEmpty>{t("filters.noResults")}</ComboboxEmpty>
            {selectOptions.map((option) => (
              <ComboboxItem key={option.value} value={option.value}>
                {option.label}
              </ComboboxItem>
            ))}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
    );
  }, [
    cancelEditing,
    getOptionLabel,
    multiSelectAnchorRef,
    selectOptions,
    selectedMultiValues,
    stopEditing,
    t,
    updateDraftValue,
  ]);

  const renderInputEditor = useCallback(() => {
    let inputType = "text";
    if (resolvedEditor === "number") {
      inputType = "number";
    } else if (resolvedEditor === "date") {
      inputType = "date";
    }

    return (
      <Input
        className={cn(
          "h-8 py-1 text-sm",
          resolvedEditor === "number" && "text-right"
        )}
        onBlur={handleEditorBlur}
        onChange={(event) => {
          updateDraftValue(event.target.value);
        }}
        onKeyDown={handleEditorKeyDown}
        type={inputType}
        value={String(editorValue)}
      />
    );
  }, [
    editorValue,
    handleEditorBlur,
    handleEditorKeyDown,
    resolvedEditor,
    updateDraftValue,
  ]);

  const renderEditor = () => {
    if (resolvedEditor === "textarea" || resolvedEditor === "json") {
      return renderTextareaEditor();
    }

    if (resolvedEditor === "boolean") {
      return renderBooleanEditor();
    }

    if (resolvedEditor === "select") {
      return renderSelectEditor();
    }

    if (resolvedEditor === "multiSelect") {
      return renderMultiSelectEditor();
    }

    return renderInputEditor();
  };

  return (
    <div className="relative w-full">
      {isEditing ? (
        renderEditor()
      ) : (
        <button
          className={cn(
            "relative flex min-h-8 w-full cursor-text items-center rounded-sm px-0.5 py-1 outline-none",
            resolvedEditor === "number"
              ? "justify-end text-right"
              : "justify-start text-left",
            "focus-visible:ring-2 focus-visible:ring-primary/30"
          )}
          onDoubleClick={(event) => {
            event.stopPropagation();
            startEditing();
          }}
          onKeyDown={handleDisplayKeyDown}
          title={t("inline.edit_hint")}
          type="button"
        >
          {displayValue}
        </button>
      )}

      {isSaving && (
        <span aria-live="polite" className="sr-only">
          {t("inline.saving")}
        </span>
      )}

      {!isSaving &&
        isDirty &&
        scheduledAt != null &&
        inlineConfig.showDelayIndicator && (
          <div
            className="absolute right-0 bottom-0 left-0 h-[2px] overflow-hidden rounded-full bg-muted"
            title={t("inline.save_scheduled")}
          >
            <div
              className="h-full bg-primary transition-[width] duration-75"
              style={{ width: `${delayProgress}%` }}
            />
          </div>
        )}

      {errorMessage && (
        <p className="mt-1 text-destructive text-xs">{errorMessage}</p>
      )}
    </div>
  );
}

export const InlineEditableCell = memo(
  InlineEditableCellBase
) as typeof InlineEditableCellBase;

/**
 * JSON cell component for data tables
 * Shows formatted JSON values with appropriate styling
 */
"use client";

import { useTableTranslations } from "../../hooks";

export interface JsonCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Maximum number of items to display before truncating
   * @default 3
   */
  maxItems?: number;

  /**
   * The value to display (can be an array, object, or primitive)
   */
  value: unknown;
}

// Helper function to format display value
const formatDisplayValue = (item: unknown): string => {
  if (item === null || item === undefined) {
    return "null";
  }
  if (typeof item === "object") {
    return JSON.stringify(item);
  }
  if (typeof item === "string") {
    return `&quot;${item}&quot;`;
  }
  return String(item);
};

// Helper function to process initial value
const processValue = (initialValue: unknown): unknown => {
  let processedValue = safelyParseJson(initialValue);

  // Handle Prisma JSON objects with 'set' property
  if (
    processedValue &&
    typeof processedValue === "object" &&
    "set" in processedValue
  ) {
    processedValue = (processedValue as { set: unknown }).set;
    processedValue = safelyParseJson(processedValue);
  }

  return processedValue;
};

/**
 * Cell component for displaying JSON values
 * Shows arrays and objects in a compact, readable format
 */
export function JsonCell({
  className = "",
  maxItems = 3,
  value,
}: JsonCellProps) {
  const _translations = useTableTranslations();

  const processedValue = processValue(value);

  // Handle null or undefined
  if (processedValue === null || processedValue === undefined) {
    return <span className="text-muted-foreground">-</span>;
  }

  // Handle arrays
  if (Array.isArray(processedValue)) {
    return (
      <div
        className={`flex max-w-[200px] flex-wrap gap-1 overflow-hidden text-ellipsis ${className}`}
      >
        {processedValue.slice(0, maxItems).map((item) => {
          const parsedItem = safelyParseJson(item);
          const displayValue = formatDisplayValue(parsedItem);
          const itemKey =
            typeof item === "object" ? JSON.stringify(item) : String(item);

          return (
            <span
              className="inline-flex items-center whitespace-nowrap rounded-md border px-2 py-1 text-xs"
              key={itemKey}
              title={
                typeof item === "object" ? JSON.stringify(item) : String(item)
              }
            >
              {displayValue}
            </span>
          );
        })}
        {processedValue.length > maxItems && (
          <span className="inline-flex items-center rounded-md border bg-muted px-2 py-1 text-xs">
            +{processedValue.length - maxItems}
          </span>
        )}
      </div>
    );
  }

  // Handle objects
  if (typeof processedValue === "object" && processedValue !== null) {
    const entries = Object.entries(processedValue as Record<string, unknown>);
    return (
      <div
        className={`flex max-w-[200px] flex-wrap gap-1 overflow-hidden text-ellipsis ${className}`}
      >
        {entries.slice(0, maxItems).map(([key, val], index) => {
          const parsedVal = safelyParseJson(val);
          const displayValue = formatDisplayValue(parsedVal);

          // Full JSON representation for the tooltip
          const fullValue = JSON.stringify({ [key]: val });

          return (
            <span
              className="inline-flex items-center whitespace-nowrap rounded-md border px-2 py-1 text-xs"
              key={key || index}
              title={fullValue}
            >
              <span className="font-medium">&quot;{key}&quot;:</span>{" "}
              {displayValue}
            </span>
          );
        })}
        {entries.length > maxItems && (
          <span className="inline-flex items-center rounded-md border bg-muted px-2 py-1 text-xs">
            +{entries.length - maxItems}
          </span>
        )}
      </div>
    );
  }

  // For strings that look like JSON but couldn't be parsed earlier
  if (
    typeof processedValue === "string" &&
    (processedValue.includes('\\"') ||
      processedValue.includes("\\'") ||
      (processedValue.includes("{") && processedValue.includes("}"))) &&
    processedValue.length > 2
  ) {
    try {
      // One more attempt to clean and parse the string
      const cleanValue = processedValue
        .replace(/\\"/g, '"')
        .replace(/\\'/g, "'");
      const parsedValue = JSON.parse(cleanValue);
      return (
        <span
          className={`block max-w-[200px] truncate ${className}`}
          title={JSON.stringify(parsedValue)}
        >
          {JSON.stringify(parsedValue)}
        </span>
      );
    } catch {
      // Fall through to default handling
    }
  }

  // Default fallback for primitive values
  const stringValue =
    typeof processedValue === "string"
      ? processedValue
      : JSON.stringify(processedValue);
  return (
    <span
      className={`block max-w-[200px] truncate ${className}`}
      title={stringValue}
    >
      {stringValue}
    </span>
  );
}

/**
 * Safely parses a JSON string if it's a string that looks like JSON
 * Otherwise returns the original value
 */
function safelyParseJson(value: unknown): unknown {
  if (
    typeof value === "string" &&
    (value.startsWith("{") || value.startsWith("[")) &&
    (value.endsWith("}") || value.endsWith("]"))
  ) {
    try {
      return JSON.parse(value);
    } catch {
      // If it can't be parsed as JSON, return the original
      return value;
    }
  }
  return value;
}

/**
 * Number cell component for data tables
 * Shows formatted number values with appropriate styling
 */
"use client";

import {
  formatNumber,
  type NumberFormatConfig,
} from "../../utils/number-format";

export interface NumberCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Optional formatter function to format the number (overrides numberFormat)
   */
  formatter?: (value: number) => string;

  /**
   * Display format: "space" | "dot" | "comma" | "locale" or options.
   * Used when formatter is not provided.
   */
  numberFormat?: NumberFormatConfig;

  /**
   * The numeric value to display
   */
  value: number | string;
}

/**
 * Cell component for displaying number values
 * Handles NaN and formatting options
 */
export function NumberCell({
  className = "",
  formatter,
  numberFormat,
  value,
}: NumberCellProps) {
  // Handle null or undefined
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground">-</span>;
  }

  // Convert to number if it's a string
  const numValue = typeof value === "string" ? Number(value) : value;

  // Handle NaN
  if (Number.isNaN(numValue)) {
    return <span className={`text-muted-foreground ${className}`}>-</span>;
  }

  // Custom formatter takes precedence
  if (formatter) {
    return <span className={className}>{formatter(numValue)}</span>;
  }

  // Configurable format (e.g. space/dot thousands)
  if (numberFormat !== undefined) {
    return (
      <span className={className}>{formatNumber(numValue, numberFormat)}</span>
    );
  }

  // Default display
  return <span className={className}>{String(numValue)}</span>;
}

/**
 * Selection cell component for data tables
 * Shows a checkbox for row selection
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";
import type { Row } from "../../tanstack";

const _DEBUG = false;

export interface SelectionCellProps<TData> {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Whether the row is disabled for selection
   */
  disabled?: boolean;

  /**
   * The row object from TanStack Table
   */
  row: Row<TData>;
}

/**
 * Cell component for displaying a selection checkbox
 */
export function SelectionCell<TData>({
  className = "",
  disabled = false,
  row,
}: SelectionCellProps<TData>) {
  // Track selection state locally
  const [isSelected, setIsSelected] = useState(() => row.getIsSelected());

  // Update local state when row selection changes
  useEffect(() => {
    setIsSelected(row.getIsSelected());
  }, [row]);

  // Create a stable callback for selection changes
  const handleSelectionChange = useCallback(
    (value: boolean) => {
      // Update local state first for immediate feedback
      setIsSelected(value);
      // Then update the row selection
      row.toggleSelected(value);
    },
    [row]
  );
  return (
    <div className={cn("flex items-center justify-center px-2", className)}>
      <Checkbox
        aria-label="Select row"
        checked={isSelected}
        className="hover:cursor-pointer data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
        disabled={disabled || !row.getCanSelect()}
        onCheckedChange={handleSelectionChange}
      />
    </div>
  );
}

