          </span>
        </div>
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger>
              <Button
                className="h-7 px-2 text-xs"
                disabled={disabled}
                onClick={() => setShowInlineAdd((v) => !v)}
                size="sm"
                variant="outline"
              >
                {translateWithFallback(t, "filters.add", "Add filter")}
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>
                {translateWithFallback(
                  t,
                  "filters.advanced.empty_description",
                  "Add filters to narrow down results."
                )}
              </p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
        {showInlineAdd && (
          <div className="mt-2">
