/**
 * Date range shortcuts for common date ranges
 */
export function DateRangeShortcuts({
  onSelect,
  disabled = false,
}: {
  onSelect: (range: [Date, Date]) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslations();
  const shortcuts = [
    {
      label: translateWithFallback(t, "filters.date_shortcuts.today", "Today"),
      getValue: () => {
        const today = new Date();
        return [today, today] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.yesterday",
        "Yesterday"
      ),
      getValue: () => {
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        return [yesterday, yesterday] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.last_7_days",
        "Last 7 days"
      ),
      getValue: () => {
        const end = new Date();
        const start = new Date();
        start.setDate(start.getDate() - 6);
        return [start, end] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.last_30_days",
        "Last 30 days"
      ),
      getValue: () => {
        const end = new Date();
        const start = new Date();
        start.setDate(start.getDate() - 29);
        return [start, end] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.this_month",
        "This month"
      ),
      getValue: () => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1);
        const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
        return [start, end] as [Date, Date];
      },
    },
  ];

  return (
    <div className="flex flex-wrap gap-1">
      {shortcuts.map((shortcut) => (
        <Button
          className="h-6 px-2 text-xs"
          disabled={disabled}
          key={shortcut.label}
          onClick={() => onSelect(shortcut.getValue())}
          size="sm"
          type="button"
          variant="outline"
        >
          {shortcut.label}
        </Button>
      ))}
    </div>
  );
}

/**
 * Enhanced Filter Chip Component
 * Modern, animated filter chips inspired by bazza/ui and Linear
 */
"use client";

import { ChevronDown, X, Zap } from "lucide-react";
import { useRef, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useLocale, useTranslations } from "../../providers/table-provider";
import type {
  AdvancedFilterModel,
  ColumnDataType,
  FilterOperators,
} from "../../types/filter-types";
import { getColumnTypeIcon } from "../../utils/column-icons";
import {
  formatDateForDisplay,
  formatDateRangeForDisplay,
} from "../../utils/date-display";
import { FilterValueInput } from "./filter-value-input";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

// Animation variants for different states
const animationClasses = {
  idle: "scale-100 opacity-100",
  hover: "scale-105 opacity-100",
  active: "scale-98 opacity-90",
  removing: "scale-95 opacity-0",
};

// Color schemes for different filter states
const colorSchemes = {
  active: {
    chip: "bg-primary/10 text-primary border-primary/20 hover:bg-primary/15",
    badge: "bg-primary text-primary-foreground",
    icon: "text-primary",
  },
  inactive: {
    chip: "bg-muted/50 text-muted-foreground border-border hover:bg-muted",
    badge: "bg-muted text-muted-foreground",
    icon: "text-muted-foreground",
  },
  error: {
    chip: "bg-destructive/10 text-destructive border-destructive/20 hover:bg-destructive/15",
    badge: "bg-destructive text-destructive-foreground",
    icon: "text-destructive",
  },
} as const;

/**
 * Get color scheme based on filter state
 */
function getFilterColorScheme(filter: AdvancedFilterModel) {
  if (!filter.isActive) {
    return colorSchemes.inactive;
  }

  const hasEmptyValues =
    filter.values === null ||
    filter.values === undefined ||
    filter.values === "";

  return hasEmptyValues ? colorSchemes.error : colorSchemes.active;
}

/**
 * Get icon size class based on chip size
 */
function getIconSizeClass(size: "sm" | "md" | "lg"): string {
  switch (size) {
    case "sm":
      return "h-3 w-3";
    case "lg":
      return "h-5 w-5";
    default:
      return "h-4 w-4";
  }
}

interface EnhancedFilterChipProps {
  filter: AdvancedFilterModel;
  columnLabel: string;
  onUpdate: (updates: Partial<AdvancedFilterModel>) => void;
  onRemove: () => void;
  onToggle: () => void;
  className?: string;
  size?: "sm" | "md" | "lg";
  variant?: "default" | "outline" | "minimal";
  showTypeIcon?: boolean;
  showOperator?: boolean;
  maxValueLength?: number;
  disabled?: boolean;
  isEditing?: boolean;
  onEditingChange?: (editing: boolean) => void;
}

/**
 * Format number value for display
 */
function formatNumberValue(values: unknown, operator: string): string {
  if (operator === "between" && Array.isArray(values)) {
    return `${values[0]} - ${values[1]}`;
  }
  return String(values);
}

function formatDateValue(
  values: unknown,
  operator: string,
  locale?: string
): string {
  if (operator === "between") {
    return (
      formatDateRangeForDisplay(values, {
        locale,
      }) ?? String(values ?? "")
    );
  }

  return (
    formatDateForDisplay(values, {
      locale,
    }) ?? String(values ?? "")
  );
}

/**
 * Format multi-select value for display
 */
function formatMultiSelectValue(values: unknown): string {
  if (Array.isArray(values)) {
    if (values.length === 0) {
      return "";
    }
    if (values.length === 1) {
      return String(values[0]);
    }
    return `${values[0]} +${values.length - 1}`;
  }
  return String(values);
}

/**
 * Format filter value for display
 */
function formatFilterValue(
  values: unknown,
  operator: FilterOperators[ColumnDataType],
  type: ColumnDataType,
  maxLength = 20,
  locale?: string
): string {
  if (values === null || values === undefined) {
    return "";
  }

  let displayValue = "";

  switch (type) {
    case "text":
      displayValue = String(values);
      break;

    case "number":
      displayValue = formatNumberValue(values, operator);
      break;

    case "date":
      displayValue = formatDateValue(values, operator, locale);
      break;

    case "select":
      displayValue = String(values);
      break;

    case "multiSelect":
      displayValue = formatMultiSelectValue(values);
      break;

    default:
      displayValue = String(values);
  }

  return displayValue.length > maxLength
    ? `${displayValue.slice(0, maxLength)}...`
    : displayValue;
}

/**
 * Get operator display text
 */
function getOperatorText(
  t: ReturnType<typeof useTranslations>["t"],
  operator: FilterOperators[ColumnDataType],
  _type: ColumnDataType
): string {
  const operatorLabels: Record<string, string> = {
    contains: "contains",
    equals: "is",
    startsWith: "starts with",
    endsWith: "ends with",
    isEmpty: "is empty",
    isNotEmpty: "is not empty",
    gt: ">",
    gte: "≥",
    lt: "<",
    lte: "≤",
    between: "between",
    is: "is",
    isNot: "is not",
    before: "before",
    after: "after",
    onOrBefore: "on or before",
    onOrAfter: "on or after",
  };

  return getTranslatedOperatorLabel(
    t,
    operator,
    operatorLabels[operator] || operator
  );
}

/**
 * Enhanced Filter Chip Component
 */
export function EnhancedFilterChip({
  filter,
  columnLabel,
  onUpdate,
  onRemove,
  onToggle,
  className,
  size = "md",
  variant = "default",
  showTypeIcon = true,
  showOperator = true,
  maxValueLength = 20,
  disabled = false,
  isEditing = false,
  onEditingChange,
}: EnhancedFilterChipProps) {
  const { t } = useTranslations();
  const locale = useLocale();
  const [isRemoving, setIsRemoving] = useState(false);
  const chipRef = useRef<HTMLDivElement>(null);

  // Controlled: parent owns open state via isEditing and onEditingChange
  const handlePopoverChange = (open: boolean) => {
    onEditingChange?.(open);
  };

  // Get color scheme based on filter state
  const colorScheme = getFilterColorScheme(filter);

  // Size variants
  const sizeClasses = {
    sm: "h-6 text-xs px-2 gap-1",
    md: "h-8 text-sm px-3 gap-1.5",
    lg: "h-10 text-base px-4 gap-2",
  };

  // Get type icon
  const TypeIcon = getColumnTypeIcon(filter.type, filter.columnId);

  // Format display value
  const displayValue = formatFilterValue(
    filter.values,
    filter.operator,
    filter.type,
    maxValueLength,
    locale
  );

  // Handle remove with animation
  const handleRemove = async () => {
    setIsRemoving(true);
    // Wait for animation to complete
    await new Promise((resolve) => setTimeout(resolve, 200));
    onRemove();
  };

  // Handle toggle
  const handleToggle = () => {
    if (!disabled) {
      onToggle();
    }
  };

  return (
    <div
      className={cn(
        "relative transition-all duration-200 ease-out",
        isRemoving ? animationClasses.removing : animationClasses.idle,
        className
      )}
      ref={chipRef}
    >
      <Popover onOpenChange={handlePopoverChange} open={isEditing}>
        <PopoverTrigger>
          <Button
            aria-label={`${translateWithFallback(
              t,
              "menu.filter",
              "Filter"
            )}: ${columnLabel} ${getOperatorText(
              t,
              filter.operator,
              filter.type
            )} ${displayValue}`}
            className={cn(
              "inline-flex items-center rounded-full border transition-all duration-200",
              "cursor-pointer select-none",
              sizeClasses[size],
              colorScheme.chip,
              !disabled && "hover:shadow-sm",
              disabled && "cursor-not-allowed opacity-50",
              variant === "outline" && "bg-transparent",
              variant === "minimal" && "border-none shadow-none",
              "group"
            )}
            disabled={disabled}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                handlePopoverChange(true);
              }
            }}
            type="button"
            variant="ghost"
          >
            {/* Type Icon */}
            {showTypeIcon && (
              <TypeIcon
                className={cn(
                  "shrink-0",
                  getIconSizeClass(size),
                  colorScheme.icon,
                  "transition-colors duration-200"
                )}
              />
            )}

            {/* Filter Content */}
            <div className="flex min-w-0 items-center gap-1">
              {/* Column Label */}
              <span className="truncate font-medium">{columnLabel}</span>

              {/* Operator */}
              {showOperator && displayValue && (
                <span className="text-xs opacity-70">
                  {getOperatorText(t, filter.operator, filter.type)}
                </span>
              )}

              {/* Value */}
              {displayValue && <span className="truncate">{displayValue}</span>}
            </div>

            {/* Active State Indicator */}
            {!filter.isActive && (
              <Badge
                className={cn(
                  "ml-1 px-1.5 py-0 text-xs",
                  size === "sm" && "px-1 text-xs",
                  colorScheme.badge
                )}
                variant="secondary"
              >
                {translateWithFallback(t, "filters.advanced.off", "Off")}
              </Badge>
            )}

            {/* Expand Icon */}
            <ChevronDown
              className={cn(
                "ml-1 shrink-0 transition-transform duration-200",
                size === "sm" ? "h-3 w-3" : "h-4 w-4",
                isEditing && "rotate-180",
                colorScheme.icon
              )}
            />
          </Button>
        </PopoverTrigger>

        <PopoverContent
          align="start"
          className="w-auto min-w-80 max-w-96 p-4"
          side="bottom"
          sideOffset={4}
        >
          <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <TypeIcon className="h-4 w-4 text-muted-foreground" />
                <span className="font-medium">{columnLabel}</span>
              </div>
              <div className="flex items-center gap-1">
                {/* Toggle Active State */}
                <Button
                  className={cn(
                    "h-6 px-2 text-xs",
                    filter.isActive ? "text-primary" : "text-muted-foreground"
                  )}
                  onClick={handleToggle}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  {filter.isActive ? (
                    <>
                      <Zap className="mr-1 h-3 w-3" />
                      {translateWithFallback(
                        t,
                        "filters.advanced.active",
                        "Active"
                      )}
                    </>
                  ) : (
                    translateWithFallback(
                      t,
                      "filters.advanced.activate",
                      "Activate"
                    )
                  )}
                </Button>

                {/* Remove Button */}
                <Button
                  className="h-6 w-6 p-0 text-muted-foreground hover:text-destructive"
                  onClick={handleRemove}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  <X className="h-3 w-3" />
                </Button>
              </div>
            </div>

            {/* Filter Configuration */}
            <FilterValueInput
              config={{
                type: filter.type,
                filterable: true,
              }}
              onOperatorChange={(operator) => onUpdate({ operator })}
              onValueChange={(value) => onUpdate({ values: value })}
              operator={filter.operator}
              type={filter.type}
              value={filter.values}
            />
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

/**
 * Compact Filter Chip for minimal display
 */
export function CompactFilterChip({
  filter,
  columnLabel,
  onToggle,
  onRemove,
  className,
}: Pick<
  EnhancedFilterChipProps,
  "filter" | "columnLabel" | "onToggle" | "onRemove" | "className"
>) {
  return (
    <EnhancedFilterChip
      className={className}
      columnLabel={columnLabel}
      filter={filter} // No inline editing in compact mode
      maxValueLength={15}
      onRemove={onRemove}
      onToggle={onToggle}
      onUpdate={() => {
        // No update needed for simplified filter
      }}
      showOperator={false}
      showTypeIcon={false}
      size="sm"
      variant="minimal"
    />
  );
}

