          <RefreshCw className="mr-2 h-4 w-4" />
          {translateWithFallback(t, "filters.advanced.retry", "Try again")}
        </Button>
      )}
    </div>
  );
}

/**
 * Success state when filters are working well
 */
export function FilterSuccessState({
  className,
  activeFiltersCount,
  totalResults,
  onClearAll,
}: {
  className?: string;
  activeFiltersCount: number;
  totalResults?: number;
  onClearAll?: () => void;
}) {
