            {t("filters.clear")}
          </Button>
        )}
        {onModifyFilters && (
          <Button onClick={onModifyFilters}>
            <Zap className="mr-2 h-4 w-4" />
            {translateWithFallback(
              t,
              "filters.advanced.modify_filters",
