}

/**
 * Filter performance indicator
 */
export function FilterPerformanceIndicator({
  className,
  filterTime,
  isOptimized = true,
}: {
  className?: string;
  filterTime?: number;
  isOptimized?: boolean;
}) {
  const { t } = useTranslations();
  if (!filterTime) {
    return null;
  }

  const isSlowQuery = filterTime > 1000;
  const displayTime =
    filterTime < 1000
      ? `${filterTime}ms`
      : `${(filterTime / 1000).toFixed(1)}s`;

  return (
    <div
      className={cn(
        "flex items-center gap-1 text-xs",
        isSlowQuery ? "text-amber-600" : "text-muted-foreground",
        className
      )}
    >
      <Zap
        className={cn(
          "h-3 w-3",
          isOptimized && "text-emerald-500",
          !isOptimized && isSlowQuery && "text-amber-500"
        )}
      />
      <span>
        {translateWithFallback(
          t,
          "filters.advanced.filtered_in",
          "Filtered in {time}",
          { time: displayTime }
        )}
      </span>
      {isOptimized && <span className="font-medium text-emerald-600">⚡</span>}
    </div>
  );
}

/**
 * Multi-select filter component
 * Provides filtering for multi-select columns with tags and multiple selection
 */
"use client";

import { Check, ChevronDown, X } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../providers/table-provider";
import type { ColumnOption, FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface MultiSelectFilterProps {
  /** Current filter value - array of selected values */
  value: string[];
  /** Current operator */
  operator: FilterOperators["multiSelect"];
  /** Available operators (defaults to all multiSelect operators) */
  operators?: readonly FilterOperators["multiSelect"][];
  /** Available options */
  options: ColumnOption[];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string[]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["multiSelect"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show faceted counts */
  showCounts?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Render picker inline instead of popover */
  inline?: boolean;
  /** Maximum number of tags to show before showing count */
  maxDisplayedTags?: number;
}

/**
 * Multi-select filter component with operator selection and multiple option picker
 */
export function MultiSelectFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.multiSelect,
  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder,
  maxDisplayedTags = 3,
  inline = false,
}: MultiSelectFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ??
    translateWithFallback(t, "filters.value", "Select options...");
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  const handleValueChange = useCallback(
    (newValue: string[]) => {
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle option selection toggle
  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = value.includes(optionValue)
        ? value.filter((v) => v !== optionValue)
        : [...value, optionValue];
      handleValueChange(newValue);
    },
    [value, handleValueChange]
  );

  // Handle select all
  const handleSelectAll = useCallback(() => {
    const allValues = filteredOptions.map((opt) => opt.value);
    handleValueChange(allValues);
  }, [filteredOptions, handleValueChange]);

  // Handle clear all
  const handleClearAll = useCallback(() => {
    handleValueChange([]);
  }, [handleValueChange]);

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (value.length === 0) {
      return effectivePlaceholder;
    }
    if (value.length === 1) {
      const option = getOptionByValue(value[0]);
      return option?.label || value[0];
    }
    return t("filters.selectedCount", { count: value.length });
  }, [value, effectivePlaceholder, getOptionByValue, t]);

  // Get displayed tags
  const displayedTags = useMemo(() => {
    const tags = value.slice(0, maxDisplayedTags);
    const hasMore = value.length > maxDisplayedTags;
    return {
      tags,
      hasMore,
      remainingCount: value.length - maxDisplayedTags,
    };
  }, [value, maxDisplayedTags]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["multiSelect"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.multiSelect[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.multiSelect[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = value.includes(option.value);
                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => handleOptionToggle(option.value)}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {/* Select/Clear all buttons */}
                        {filteredOptions.length > 1 && (
                          <>
                            <CommandItem
                              className="justify-center border-b"
                              onSelect={handleSelectAll}
                            >
                              {translateWithFallback(
                                t,
                                "filters.select_all",
                                "Select all"
                              )}{" "}
                              ({filteredOptions.length})
                            </CommandItem>
                            {value.length > 0 && (
                              <CommandItem
                                className="mb-1 justify-center border-b"
                                onSelect={handleClearAll}
                              >
                                {t("filters.clear")}
                              </CommandItem>
                            )}
                          </>
                        )}

                        {filteredOptions.map((option) => {
                          const isSelected = value.includes(option.value);

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => handleOptionToggle(option.value)}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected tags display */}
            {value.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {displayedTags.tags.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() => handleOptionToggle(selectedValue)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}

                {/* Show remaining count if there are more tags */}
                {displayedTags.hasMore && (
                  <Badge className="text-xs" variant="outline">
                    +{displayedTags.remainingCount}
                  </Badge>
                )}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact multi-select filter for use in filter chips
 */
export function CompactMultiSelectFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder,
  maxDisplayedTags = 2,
}: Pick<
  MultiSelectFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
  | "maxDisplayedTags"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Select...");
  const [isOpen, setIsOpen] = useState(false);

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const formatValueForDisplay = useCallback(() => {
    if (value.length === 0) {
      return effectivePlaceholder;
    }
    if (value.length === 1) {
      const option = getOptionByValue(value[0]);
      return option?.label || value[0];
    }
    return translateWithFallback(
      t,
      "filters.selectedCount",
      `${value.length} selected`,
      { count: value.length }
    );
  }, [value, effectivePlaceholder, getOptionByValue, t]);

  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = value.includes(optionValue)
        ? value.filter((v) => v !== optionValue)
        : [...value, optionValue];

      onValueChange(newValue);
    },
    [value, onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <div className="flex flex-col gap-1">
      <Popover onOpenChange={setIsOpen} open={isOpen}>
        <PopoverTrigger>
          <Button
            className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
            disabled={disabled}
            size="sm"
            variant="ghost"
          >
            <span className="truncate">{formatValueForDisplay()}</span>
            <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-48 p-0">
          <Command>
            <CommandInput
              placeholder={t("filters.search", { filter: "options" })}
            />
            <CommandList>
              <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
              <CommandGroup>
                {options.map((option) => {
                  const isSelected = value.includes(option.value);

                  return (
                    <CommandItem
                      key={option.value}
                      onSelect={() => handleOptionToggle(option.value)}
                      value={option.value}
                    >
                      <div className="flex flex-1 items-center gap-2">
                        {option.icon && (
                          <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                            {typeof option.icon === "function" ? (
                              <option.icon />
                            ) : (
                              option.icon
                            )}
                          </span>
                        )}
                        <span className="flex-1 text-xs">{option.label}</span>
                      </div>
                      <Check
                        className={cn(
                          "ml-auto h-3 w-3",
                          isSelected ? "opacity-100" : "opacity-0"
                        )}
                      />
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>

      {/* Compact tags display */}
      {value.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {value.slice(0, maxDisplayedTags).map((selectedValue) => {
            const option = getOptionByValue(selectedValue);
            return (
              <Badge
                className="h-4 px-1 text-xs"
                key={selectedValue}
                variant="secondary"
              >
                {option?.label || selectedValue}
                <Button
                  className="ml-1 h-4 w-4 p-0 hover:bg-destructive hover:text-destructive-foreground"
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    handleOptionToggle(selectedValue);
                  }}
                  size="icon"
                  type="button"
                  variant="ghost"
                >
                  <X className="h-2 w-2" />
                </Button>
              </Badge>
            );
          })}
          {value.length > maxDisplayedTags && (
            <Badge className="h-4 px-1 text-xs" variant="outline">
              +{value.length - maxDisplayedTags}
            </Badge>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Number filter component
 * Provides filtering for numeric columns with various numeric operators and range slider
 */
"use client";

import { useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface NumberFilterProps {
  /** Current filter value - single number or [min, max] for between */
  value: number | [number, number];
  /** Current operator */
  operator: FilterOperators["number"];
  /** Available operators (defaults to all number operators) */
  operators?: readonly FilterOperators["number"][];
  /** Minimum value for slider/validation */
  min?: number;
  /** Maximum value for slider/validation */
  max?: number;
  /** Step size for slider */
  step?: number;
  /** Placeholder text for inputs */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: number | [number, number]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["number"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show slider for range operations */
  showSlider?: boolean;
}

/**
 * Number filter component with operator selection and numeric input/slider
 */
export function NumberFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.number,
  min = 0,
  max = 100,
  step = 1,
  placeholder,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showSlider = true,
}: NumberFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Enter number...");

  const handleValueChange = useCallback(
    (newValue: number | [number, number]) => {
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);

      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  // Handle immediate value change
  const handleImmediateChange = useCallback(
    (newValue: number | [number, number]) => {
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";
  const currentSingleValue = Array.isArray(value) ? value[0] : value;
  const currentRangeValue = Array.isArray(value) ? value : [min, max];

  // Handle single number input change
  const handleSingleInputChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        handleValueChange(numValue);
      }
    },
    [handleValueChange]
  );

  // Handle range input changes
  const handleRangeMinChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        const [, maxVal] = currentRangeValue;
        handleValueChange([numValue, maxVal]);
      }
    },
    [currentRangeValue, handleValueChange]
  );

  const handleRangeMaxChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        const [minVal] = currentRangeValue;
        handleValueChange([minVal, numValue]);
      }
    },
    [currentRangeValue, handleValueChange]
  );

  // Handle slider change
  const handleSliderChange = useCallback(
    (values: number[]) => {
      if (isBetween) {
        handleImmediateChange([values[0], values[1]]);
      } else {
        handleImmediateChange(values[0]);
      }
    },
    [isBetween, handleImmediateChange]
  );

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["number"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.number[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.number[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Value inputs */}
        {needsValue && (
          <div className="space-y-2">
            {isBetween ? (
              <>
                {/* Range inputs */}
                <div className="flex items-center gap-2">
                  <Input
                    className="flex-1"
                    disabled={disabled}
                    max={max}
                    min={min}
                    onChange={(e) => handleRangeMinChange(e.target.value)}
                    placeholder={t("filters.value")}
                    step={step}
                    type="number"
                    value={currentRangeValue[0]}
                  />
                  <span className="text-muted-foreground text-sm">-</span>
                  <Input
                    className="flex-1"
                    disabled={disabled}
                    max={max}
                    min={min}
                    onChange={(e) => handleRangeMaxChange(e.target.value)}
                    placeholder={t("filters.value_to")}
                    step={step}
                    type="number"
                    value={currentRangeValue[1]}
                  />
                </div>

                {/* Range slider */}
                {showSlider && (
                  <div className="px-2">
                    <Slider
                      className="w-full"
                      disabled={disabled}
                      max={max}
                      min={min}
                      onValueChange={(value) =>
                        handleSliderChange(
                          Array.isArray(value) ? [...value] : [value as number]
                        )
                      }
                      step={step}
                      value={currentRangeValue}
                    />
                    <div className="mt-1 flex justify-between text-muted-foreground text-xs">
                      <span>{min}</span>
                      <span>{max}</span>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <>
                {/* Single number input */}
                <Input
                  className="w-full"
                  disabled={disabled}
                  max={max}
                  min={min}
                  onChange={(e) => handleSingleInputChange(e.target.value)}
                  placeholder={effectivePlaceholder}
                  step={step}
                  type="number"
                  value={currentSingleValue || ""}
                />

                {/* Single value slider */}
                {showSlider && (
                  <div className="px-2">
                    <Slider
                      className="w-full"
                      disabled={disabled}
                      max={max}
                      min={min}
                      onValueChange={(value) =>
                        handleSliderChange(
                          Array.isArray(value) ? [...value] : [value as number]
                        )
                      }
                      step={step}
                      value={[currentSingleValue || min]}
                    />
                    <div className="mt-1 flex justify-between text-muted-foreground text-xs">
                      <span>{min}</span>
                      <span>{max}</span>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact number filter for use in filter chips
 */
export function CompactNumberFilter({
  value,
  operator,
  onValueChange,
  placeholder,
  disabled = false,
}: Pick<
  NumberFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "0");

  const handleChange = useCallback(
    (newValue: number | [number, number]) => {
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  if (isBetween && Array.isArray(value)) {
    return (
      <div className="flex items-center gap-1">
        <Input
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onChange={(e) => {
            const val = Number.parseFloat(e.target.value);
            if (!Number.isNaN(val)) {
              handleChange([val, value[1]]);
            }
          }}
          type="number"
          value={value[0]}
        />
        <span className="text-xs">-</span>
        <Input
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onChange={(e) => {
            const val = Number.parseFloat(e.target.value);
            if (!Number.isNaN(val)) {
              handleChange([value[0], val]);
            }
          }}
          type="number"
          value={value[1]}
        />
      </div>
    );
  }

  const singleValue = Array.isArray(value) ? value[0] : value;

  return (
    <Input
      className="h-6 w-20 text-xs"
      disabled={disabled}
      onChange={(e) => {
        const val = Number.parseFloat(e.target.value);
        if (!Number.isNaN(val)) {
          handleChange(val);
        }
      }}
      placeholder={effectivePlaceholder}
      type="number"
      value={singleValue || ""}
    />
  );
}

/**
 * Select filter component
 * Provides filtering for single-option columns with search and faceted counts
 */
"use client";

import { Check, ChevronDown, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../providers/table-provider";
import type { ColumnOption, FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface SelectFilterProps {
  /** Current filter value - single value or array for isAnyOf/isNoneOf */
  value: string | string[];
  /** Current operator */
  operator: FilterOperators["select"];
  /** Available operators (defaults to all option operators) */
  operators?: readonly FilterOperators["select"][];
  /** Available options */
  options: ColumnOption[];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string | string[]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["select"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show faceted counts */
  showCounts?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Render picker inline instead of popover */
  inline?: boolean;
}

/**
 * Select filter component with operator selection and option picker
 */
export function SelectFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.select,
  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder,
  inline = false,
}: SelectFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ??
    translateWithFallback(t, "filters.value", "Select option...");
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle single option selection
  const handleSingleOptionSelect = useCallback(
    (optionValue: string) => {
      handleValueChange(optionValue);
      setIsOpen(false);
    },
    [handleValueChange]
  );

  // Handle multiple option selection
  const handleMultipleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = currentMultipleValue.includes(optionValue)
        ? currentMultipleValue.filter((v) => v !== optionValue)
        : [...currentMultipleValue, optionValue];
      handleValueChange(newValue);
    },
    [currentMultipleValue, handleValueChange]
  );

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return effectivePlaceholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return `${currentMultipleValue.length} selected`;
    }
    if (!currentSingleValue) {
      return effectivePlaceholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    effectivePlaceholder,
    getOptionByValue,
  ]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["select"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.select[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.select[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = isMultiple
                          ? currentMultipleValue.includes(option.value)
                          : currentSingleValue === option.value;

                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => {
                              if (isMultiple) {
                                handleMultipleOptionToggle(option.value);
                              } else {
                                handleSingleOptionSelect(option.value);
                              }
                            }}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {filteredOptions.map((option) => {
                          const isSelected = isMultiple
                            ? currentMultipleValue.includes(option.value)
                            : currentSingleValue === option.value;

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => {
                                if (isMultiple) {
                                  handleMultipleOptionToggle(option.value);
                                } else {
                                  handleSingleOptionSelect(option.value);
                                }
                              }}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected values display for multiple selection */}
            {isMultiple && currentMultipleValue.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {currentMultipleValue.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() =>
                          handleMultipleOptionToggle(selectedValue)
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleMultipleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact select filter for use in filter chips
 */
export function CompactSelectFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder,
}: Pick<
  SelectFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Select...");
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return effectivePlaceholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return t("filters.selectedCount", { count: currentMultipleValue.length });
    }
    if (!currentSingleValue) {
      return effectivePlaceholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    effectivePlaceholder,
    getOptionByValue,
    t,
  ]);

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <Popover onOpenChange={setIsOpen} open={isOpen}>
      <PopoverTrigger>
        <Button
          className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
          disabled={disabled}
