            <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = isMultiple
                  ? currentMultipleValue.includes(option.value)
                  : currentSingleValue === option.value;

                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      if (isMultiple) {
                        const newValue = currentMultipleValue.includes(
                          option.value
                        )
                          ? currentMultipleValue.filter(
                              (v) => v !== option.value
                            )
                          : [...currentMultipleValue, option.value];
                        handleValueChange(newValue);
                      } else {
                        handleValueChange(option.value);
                        setIsOpen(false);
                      }
                    }}
                    value={option.value}
                  >
                    <div className="flex flex-1 items-center gap-2">
                      {option.icon && (
                        <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      <span className="flex-1 text-xs">{option.label}</span>
                    </div>
                    <Check
                      className={cn(
                        "ml-auto h-3 w-3",
                        isSelected ? "opacity-100" : "opacity-0"
                      )}
                    />
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Text filter component
 * Provides filtering for text-based columns with various text operators
 */
"use client";

import { useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface TextFilterProps {
  /** Current filter value */
  value: string;
  /** Current operator */
  operator: FilterOperators["text"];
  /** Available operators (defaults to all text operators) */
  operators?: readonly FilterOperators["text"][];
  /** Placeholder text */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["text"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Debounce delay for value changes (ms). 0 = no debounce */
  debounceMs?: number;
}

/**
 * Text filter component with operator selection and text input
 */
export function TextFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.text,
  placeholder,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  debounceMs = 300,
}: TextFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Enter text...");

  const handleValueChange = useCallback(
    (newValue: string) => {
      if (debounceMs <= 0) {
        onValueChange(newValue);
        return () => {
          /* no-op cleanup */
        };
      }
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, debounceMs);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange, debounceMs]
  );

  // Handle immediate value change for certain operators
  const handleImmediateChange = useCallback(
    (newValue: string) => {
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-2">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["text"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.text[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.text[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Value input - only show if operator needs a value */}
        {needsValue && (
          <Input
            className="w-full"
            disabled={disabled}
            onBlur={(e) => handleImmediateChange(e.target.value)}
            onChange={(e) => handleValueChange(e.target.value)}
            placeholder={effectivePlaceholder}
            type="text"
            value={value}
          />
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact text filter for use in filter chips
 */
export function CompactTextFilter({
  value,
  operator,
  onValueChange,
  placeholder,
  disabled = false,
}: Pick<
  TextFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Type...");

  const handleChange = useCallback(
    (newValue: string) => {
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <Input
      className="h-6 text-xs"
      disabled={disabled}
      onChange={(e) => handleChange(e.target.value)}
      placeholder={effectivePlaceholder}
      type="text"
      value={value}
    />
  );
}

/**
 * Dropdown menu for selecting a column calculation type.
 * Mirrors Notion's column calculation picker with sub-menus:
 *   None | Count ▸ | Percent ▸ | More options ▸
 *
 * Also displays the current calculated value inline.
 */
"use client";

import { flip, offset, shift, useFloating } from "@floating-ui/react-dom";
import { useAtom } from "jotai";
import { CalculatorIcon, CheckIcon, ChevronRightIcon } from "lucide-react";
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";
import { columnCalculationsAtom } from "../../atoms/footer-atoms";
import {
  type UseTableTranslationsReturn,
  useTableTranslations,
} from "../../hooks/use-table-translations";
import type { TableAggregateResultValue } from "../../providers/table-provider";
import type { CalculationType } from "../../types/footer-types";
import { getCalculationGroups } from "../../types/footer-types";

interface CalculationMenuProps {
  columnId: string;
  columnType?: string;
  defaultCalculation?: CalculationType;
  isNumberColumn?: boolean;
  isResultLoading?: boolean;
  result?: TableAggregateResultValue;
  showEmptyLabel?: boolean;
  tableId: string;
  tableType: string;
}

const CALC_LABEL_KEYS: Record<CalculationType, string> = {
  none: "calcNone",
  count_all: "calcCountAll",
  count_values: "calcCountValues",
  count_unique: "calcCountUnique",
  count_empty: "calcCountEmpty",
  count_not_empty: "calcCountNotEmpty",
  count_true: "calcCountTrue",
  count_false: "calcCountFalse",
  percent_empty: "calcPercentEmpty",
  percent_not_empty: "calcPercentNotEmpty",
  percent_true: "calcPercentTrue",
  percent_false: "calcPercentFalse",
  sum: "calcSum",
  average: "calcAverage",
  median: "calcMedian",
  min: "calcMin",
  max: "calcMax",
  range: "calcRange",
};

const getTranslation = (
  translations: UseTableTranslationsReturn,
  key: string,
  fallback: string
): string =>
  (translations as unknown as Record<string, string>)[key] || fallback;

const floatingMiddleware = [offset(4), flip(), shift({ padding: 8 })];

const SUBMENU_CLOSE_DELAY = 150;

const SubMenu = memo(function SubMenuComponent({
  active,
  items,
  label,
  onSelect,
  translations,
}: {
  active: CalculationType;
  items: CalculationType[];
  label: string;
  onSelect: (type: CalculationType) => void;
  translations: ReturnType<typeof useTableTranslations>;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLDivElement>(null);
  const subMenuRef = useRef<HTMLDivElement>(null);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const floating = useFloating({
    middleware: [offset(2), flip(), shift({ padding: 8 })],
    placement: "right-start",
  });

  useEffect(() => {
    if (triggerRef.current) {
      floating.refs.setReference(triggerRef.current);
    }
  }, [floating.refs]);

  useEffect(() => {
    if (!isOpen) {
      return;
    }
    const el = subMenuRef.current;
    if (el) {
      floating.refs.setFloating(el);
      queueMicrotask(() => {
        floating.update();
      });
    }
  }, [isOpen, floating.refs, floating.update]);

  useEffect(
    () => () => {
      if (closeTimerRef.current) {
        clearTimeout(closeTimerRef.current);
      }
    },
    []
  );

  const cancelClose = useCallback(() => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }, []);

  const scheduleClose = useCallback(() => {
    cancelClose();
    closeTimerRef.current = setTimeout(() => {
      setIsOpen(false);
    }, SUBMENU_CLOSE_DELAY);
  }, [cancelClose]);

  const handleTriggerEnter = useCallback(() => {
    cancelClose();
    setIsOpen(true);
  }, [cancelClose]);

  const handleTriggerLeave = useCallback(() => {
    scheduleClose();
  }, [scheduleClose]);

  const handleSubmenuEnter = useCallback(() => {
    cancelClose();
  }, [cancelClose]);

  const handleSubmenuLeave = useCallback(() => {
    scheduleClose();
  }, [scheduleClose]);

  const hasActiveChild = items.includes(active);

  return (
    <div
      className={cn(
        "flex cursor-pointer select-none items-center justify-between rounded-sm px-2 py-1.5 text-sm transition-colors",
        "hover:bg-accent hover:text-accent-foreground",
        hasActiveChild && "text-accent-foreground"
      )}
      onBlur={handleTriggerLeave}
      onFocus={handleTriggerEnter}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setIsOpen((prev) => !prev);
        }
      }}
      onMouseEnter={handleTriggerEnter}
      onMouseLeave={handleTriggerLeave}
      ref={triggerRef}
      role="menuitem"
      tabIndex={0}
    >
      <span>{label}</span>
      <ChevronRightIcon className="ml-2 h-3.5 w-3.5 text-muted-foreground" />

      {isOpen &&
        createPortal(
          <div
            className="z-[60]"
            data-calculation-menu-portal="true"
            onMouseEnter={handleSubmenuEnter}
            onMouseLeave={handleSubmenuLeave}
            ref={subMenuRef}
            role="menu"
            style={floating.floatingStyles}
          >
            <div className="rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
              {items.map((item) => {
                const labelKey = CALC_LABEL_KEYS[item];
                const itemLabel = getTranslation(translations, labelKey, item);
                const isActive = active === item;
                return (
                  <div
                    className={cn(
                      "flex cursor-pointer select-none items-center justify-between gap-6 rounded-sm px-2 py-1.5 text-sm transition-colors",
                      "hover:bg-accent hover:text-accent-foreground",
                      isActive && "bg-accent/50"
                    )}
                    key={item}
                    onClick={() => {
                      onSelect(item);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        onSelect(item);
                      }
                    }}
                    role="menuitem"
                    tabIndex={0}
                  >
                    <span>{itemLabel}</span>
                    {isActive && <CheckIcon className="h-3.5 w-3.5" />}
                  </div>
                );
              })}
            </div>
          </div>,
          document.body
        )}
    </div>
  );
});

function CalculationMenuBase({
  columnId,
  columnType,
  defaultCalculation,
  isNumberColumn = false,
  isResultLoading = false,
  result,
  showEmptyLabel = false,
  tableId,
  tableType,
}: CalculationMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const translations = useTableTranslations(tableType);
  const [calculations, setCalculations] = useAtom(
    columnCalculationsAtom(tableId)
  );

  // undefined → user hasn't touched it → use defaultCalculation
  // "none"   → user explicitly chose "none"
  // other    → user explicitly chose a calculation
  const userChoice = calculations[columnId];
  const currentCalc: CalculationType =
    userChoice ?? defaultCalculation ?? "none";

  const floating = useFloating({
    middleware: floatingMiddleware,
    placement: "top-start",
  });

  const triggerRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    const handlePointerDown = (event: MouseEvent | TouchEvent) => {
      const target = event.target;
      if (!(target instanceof Node)) {
        return;
      }

      if (
        triggerRef.current?.contains(target) ||
        menuRef.current?.contains(target)
      ) {
        return;
      }

      if (
        target instanceof Element &&
        target.closest("[data-calculation-menu-portal='true']")
      ) {
        return;
      }

      setIsOpen(false);
    };

    document.addEventListener("mousedown", handlePointerDown);
    document.addEventListener("touchstart", handlePointerDown);

    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
      document.removeEventListener("touchstart", handlePointerDown);
    };
  }, [isOpen]);

  useEffect(() => {
    if (triggerRef.current) {
      floating.refs.setReference(triggerRef.current);
    }
  }, [floating.refs]);

  useEffect(() => {
    if (!isOpen) {
      return;
    }
    const el = menuRef.current;
    if (el) {
      floating.refs.setFloating(el);
      queueMicrotask(() => {
        floating.update();
      });
    }
  }, [isOpen, floating.refs, floating.update]);

  const handleSelect = useCallback(
    (type: CalculationType) => {
      setCalculations((prev) => ({
        ...prev,
        [columnId]: type,
      }));
      setIsOpen(false);
    },
    [columnId, setCalculations]
  );

  const handleToggle = useCallback(() => {
    setIsOpen((prev) => !prev);
  }, []);

  const groups = useMemo(() => getCalculationGroups(columnType), [columnType]);

  const shortLabel = useMemo(() => {
    const labelKey = CALC_LABEL_KEYS[currentCalc];
    return labelKey
      ? getTranslation(translations, labelKey, currentCalc)
      : currentCalc;
  }, [currentCalc, translations]);

  const resultLabel = useMemo(() => {
    if (currentCalc === "none") {
      return "";
    }
    if (isResultLoading) {
      return "…";
    }
    return result?.label ?? "—";
  }, [currentCalc, isResultLoading, result]);
  const shouldShowEmptyLabel = currentCalc === "none" && showEmptyLabel;

  const menuContent = useMemo(() => {
    if (!isOpen) {
      return null;
    }

    return (
      <div
        className="z-50"
        data-calculation-menu-portal="true"
        ref={menuRef}
        style={floating.floatingStyles}
      >
        <div className="min-w-[160px] rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
          {groups.map((group) => {
            const groupLabel = getTranslation(
              translations,
              group.labelKey,
              group.key
            );

            if (group.key === "none") {
              const isActive = currentCalc === "none";
              return (
                <div
                  className={cn(
                    "flex cursor-pointer select-none items-center justify-between rounded-sm px-2 py-1.5 text-sm transition-colors",
                    "hover:bg-accent hover:text-accent-foreground",
                    isActive && "bg-accent/50"
                  )}
                  key={group.key}
                  onClick={() => {
                    handleSelect("none");
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      handleSelect("none");
                    }
                  }}
                  role="menuitem"
                  tabIndex={0}
                >
                  <span>{groupLabel}</span>
                  {isActive && <CheckIcon className="h-3.5 w-3.5" />}
                </div>
              );
            }

            return (
              <SubMenu
                active={currentCalc}
                items={group.items}
                key={group.key}
                label={groupLabel}
                onSelect={handleSelect}
                translations={translations}
              />
            );
          })}
        </div>
      </div>
    );
  }, [
    isOpen,
    floating.floatingStyles,
    groups,
    translations,
    currentCalc,
    handleSelect,
  ]);

  return (
    <div
      className={cn(
        "group/footer-cell flex h-full w-full items-center",
        isNumberColumn && "justify-end"
      )}
      ref={triggerRef}
    >
      <button
        aria-expanded={isOpen}
        aria-haspopup="menu"
        aria-label={translations.calcCalculate}
        className={cn(
          "flex h-full cursor-pointer rounded-sm px-1 py-0.5 text-xs transition-colors",
          "hover:bg-accent hover:text-accent-foreground",
          currentCalc === "none" && "items-center gap-1.5",
          currentCalc !== "none" &&
            "h-auto w-full min-w-0 flex-col items-start justify-center gap-0.5",
          currentCalc !== "none" && isNumberColumn && "items-end text-right",
          currentCalc === "none" && "text-muted-foreground",
          currentCalc === "none" && !shouldShowEmptyLabel && "justify-center"
        )}
        onClick={handleToggle}
        title={currentCalc === "none" ? translations.calcCalculate : undefined}
        type="button"
      >
        {currentCalc === "none" ? (
          <>
            <CalculatorIcon
              className={cn(
                "h-3.5 w-3.5 text-muted-foreground",
                !shouldShowEmptyLabel &&
                  "opacity-0 transition-opacity group-hover/footer-cell:opacity-100"
              )}
            />
            {shouldShowEmptyLabel && (
              <span className="text-muted-foreground">
                {translations.calcCalculate}
              </span>
            )}
          </>
        ) : (
          <>
            <span className="max-w-full truncate font-medium text-[10px] text-muted-foreground leading-none">
              {shortLabel}
            </span>
            <span
              className={cn(
                "max-w-full truncate font-medium text-foreground tabular-nums leading-none",
                isNumberColumn && "font-mono"
              )}
            >
              {resultLabel}
            </span>
          </>
        )}
      </button>
      {menuContent && createPortal(menuContent, document.body)}
    </div>
  );
}

export const CalculationMenu = memo(CalculationMenuBase);

/**
 * Footer row that displays column calculations.
 * Each visible column gets a CalculationMenu cell.
 * Reads column definitions from the table config to pass
 * `defaultCalculation` and `enableCalculation` per column.
 */
"use client";

import { type CSSProperties, memo, useMemo } from "react";
import { TableCell, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";
import { useGlobalColumnCalculations } from "../../hooks/use-global-column-calculations";
import { useTableConfig } from "../../hooks/use-table-config";
import type { Table } from "../../tanstack";
import type { CalculationType } from "../../types/footer-types";
import { isCalculationValidForColumn } from "../../types/footer-types";
import { CalculationMenu } from "./calculation-menu";

interface FooterRowProps<TData> {
  densityMode: "small" | "medium" | "large";
  table: Table<TData>;
  tableId: string;
  tableType: string;
}

const isNumberColumnDef = (def: {
  type?: string;
  meta?: { columnType?: string };
}): boolean => def.type === "number" || def.meta?.columnType === "number";

const getColumnType = (def: {
  type?: string;
  meta?: { columnType?: string };
}): string | undefined =>
  (def.type as string) || (def.meta?.columnType as string) || undefined;

const getFixedColumnPaddingClass = (
  densityMode: "small" | "medium" | "large"
): string => {
  if (densityMode === "small") {
    return "!px-1.5";
  }
  if (densityMode === "large") {
    return "!px-3";
  }
  return "px-2";
};

function FooterRowBase<TData>({
  densityMode,
  table,
  tableId,
  tableType,
}: FooterRowProps<TData>) {
  const isSmallDensity = densityMode === "small";
  const isLargeDensity = densityMode === "large";
  const fixedColumnPaddingClass = getFixedColumnPaddingClass(densityMode);

  const { config: tableConfig } = useTableConfig(tableType);

  const columnDefMap = useMemo(() => {
    const map: Record<
      string,
      {
        defaultCalculation?: string;
        enableCalculation?: boolean;
        type?: string;
      }
    > = {};
    for (const def of tableConfig.columns.definitions) {
      map[def.id] = {
        defaultCalculation: def.defaultCalculation,
        enableCalculation: def.enableCalculation,
        type: def.type,
      };
    }
    return map;
  }, [tableConfig.columns.definitions]);

  const visibleColumns = table.getVisibleLeafColumns();
  const visibleColumnIds = useMemo(
    () =>
      visibleColumns
        .map((column) => column.id)
        .filter((id) => id !== "select" && id !== "actions"),
    [visibleColumns]
  );

  const {
    hasAnyCalculation,
    isLoading: isCalculationsLoading,
    resultsByColumn,
  } = useGlobalColumnCalculations({
    tableId,
    tableType,
    columnDefinitions: tableConfig.columns.definitions,
    columnIds: visibleColumnIds,
  });

  const firstCalculableColumnId = useMemo(() => {
    const firstCalculableColumn = visibleColumns.find((column) => {
      if (column.id === "select" || column.id === "actions") {
        return false;
      }

      const configDef = columnDefMap[column.id];
      return configDef?.enableCalculation !== false;
    });

    return firstCalculableColumn?.id;
  }, [columnDefMap, visibleColumns]);

  const cellSizeStyle = (
    column: (typeof visibleColumns)[number]
  ): CSSProperties | undefined => {
    const def = column.columnDef;
    const isFixed = column.id === "select" || column.id === "actions";
    const isResizable = table.options.enableColumnResizing === true;
    const hasExplicitSizing =
      typeof (def as { size?: number }).size === "number" ||
      typeof (def as { minSize?: number }).minSize === "number" ||
      typeof (def as { maxSize?: number }).maxSize === "number";

    if (!(isFixed || hasExplicitSizing || isResizable)) {
      return undefined;
    }

    const style: CSSProperties = {};
    const size = column.getSize();

    if (
      isFixed ||
      isResizable ||
      typeof (def as { size?: number }).size === "number"
    ) {
      style.width = size;
    }
    if (isFixed || isResizable) {
      style.minWidth = size;
    } else if (typeof (def as { minSize?: number }).minSize === "number") {
      style.minWidth = (def as { minSize: number }).minSize;
    }
    if (typeof (def as { maxSize?: number }).maxSize === "number") {
      style.maxWidth = (def as { maxSize: number }).maxSize;
    }
    return style;
  };

  return (
    <TableRow
      className={cn(
        "border-t border-b-0 bg-card hover:bg-card [&>td:first-child]:rounded-bl-md [&>td:last-child]:rounded-br-md",
        isSmallDensity && "[&_td]:!h-7 [&_td]:!py-0",
        isLargeDensity && "[&_td]:!h-10 [&_td]:!py-1"
      )}
    >
      {visibleColumns.map((column) => {
        const isSelect = column.id === "select";
        const isActions = column.id === "actions";
        const isFixed = isSelect || isActions;

        if (isFixed) {
          return (
            <TableCell
              className={cn(
                "text-muted-foreground",
                isSelect &&
                  cn("select-column rounded-bl-md", fixedColumnPaddingClass),
                isActions &&
                  cn(
                    "sticky right-0 z-10 rounded-br-md bg-card shadow-[-1px_0_0_0_hsl(var(--border))]",
                    fixedColumnPaddingClass
                  )
              )}
              key={column.id}
              style={cellSizeStyle(column)}
            >
              {null}
            </TableCell>
          );
        }

        const def = column.columnDef;
        const colType = getColumnType(def);
        const numCol = isNumberColumnDef(def);

        const configDef = columnDefMap[column.id];
        const enableCalc = configDef?.enableCalculation !== false;

        const rawDefault = configDef?.defaultCalculation as
          | CalculationType
          | undefined;
        const validDefault =
          rawDefault && isCalculationValidForColumn(rawDefault, colType)
            ? rawDefault
            : undefined;

        return (
          <TableCell
            className={cn(
              isSmallDensity && "!px-1.5",
              isLargeDensity && "!px-3",
              numCol && "text-right"
            )}
            key={column.id}
            style={cellSizeStyle(column)}
          >
            {enableCalc ? (
              <CalculationMenu
                columnId={column.id}
                columnType={colType}
                defaultCalculation={validDefault}
                isNumberColumn={numCol}
                isResultLoading={isCalculationsLoading}
                result={resultsByColumn[column.id]}
                showEmptyLabel={
                  !hasAnyCalculation && column.id === firstCalculableColumnId
                }
                tableId={tableId}
                tableType={tableType}
              />
            ) : null}
          </TableCell>
        );
      })}
    </TableRow>
  );
}

export const FooterRow = memo(FooterRowBase) as typeof FooterRowBase;

import { atom } from "jotai";

export interface TranslationConfig {
  keys: {
    cancel: string;
    categories: {
      current: string;
      empty: string;
      newPlaceholder: string;
    };
    create: string;
    createForm: {
      description: string;
      title: string;
    };
    error: string;
    errorDescription: string;
    submit: string;
    success: string;
    successDescription: string;
  };
  namespace: string;
}

export const translationConfigAtom = atom<TranslationConfig>({
  keys: {
    cancel: "cancel",
    categories: {
      current: "categories.current",
      empty: "categories.empty",
      newPlaceholder: "categories.new_placeholder",
    },
    create: "create",
    createForm: {
      description: "create_form.description",
      title: "create_form.title",
    },
    error: "error",
    errorDescription: "error_description",
    submit: "submit",
    success: "success",
    successDescription: "success_description",
  },
  namespace: "common",
});

/**
 * Atoms for the catalogue form
 * These atoms manage the state of the catalogue form drawer
 */
import { atom } from "jotai";

/**
 * Interface for the catalogue form state
 */
export interface CatalogueFormState<TData = Record<string, unknown>> {
  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType?: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: TData;

  /**
   * Whether the form drawer is open
   */
  isOpen: boolean;

  /**
   * Mode of the form (create or update)
   */
  mode: "create" | "update";

  /**
   * Callback when the form is submitted successfully
   */
  onSuccess?: (data: TData) => void;

  /**
   * Table ID associated with the form
   */
  tableId?: string;

  /**
   * Table type associated with the parent table configuration
   */
  tableType?: string;
}

/**
 * Default state for the catalogue form
 */
const defaultState: CatalogueFormState = {
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
  tableType: undefined,
};

/**
 * Atom for the catalogue form state
 */
export const catalogueFormAtom = atom<CatalogueFormState>(defaultState);

/**
 * Atom to track whether a form has been submitted
 * This prevents showing success notifications except after actual form submission
 */
export const formSubmittedAtom = atom<boolean>(false);

/**
 * Form renderer components
 */
export const FormRenderer = {
  CONTAINER: "container",
  NONE: "none",
  TOOLBAR: "toolbar",
} as const;

export type FormRenderer = (typeof FormRenderer)[keyof typeof FormRenderer];

/**
 * Atom to track which component is responsible for rendering the form
 * This helps prevent multiple components from rendering the same form
 */
export const formRendererAtom = atom<FormRenderer>(FormRenderer.NONE);

/**
 * Open the form in create mode
 */
export const openCreateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  onSuccess?: (data: TData) => void,
  tableType?: string
): CatalogueFormState<TData> => ({
  formType,
  initialData: undefined,
  isOpen: true,
  mode: "create",
  onSuccess,
  tableId,
  tableType,
});

/**
 * Open the form in update mode
 */
export const openUpdateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  initialData: TData,
  onSuccess?: (data: TData) => void,
  tableType?: string
): CatalogueFormState<TData> => ({
  formType,
  initialData,
  isOpen: true,
  mode: "update",
  onSuccess,
  tableId,
  tableType,
});

/**
 * Close the form
 */
export const closeForm = <
  TData = Record<string, unknown>,
>(): CatalogueFormState<TData> => ({
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
  tableType: undefined,
});

/**
 * Handle form open state changes
 * This function updates the form state based on the open state
 */
export const handleFormOpenChange = <TData = Record<string, unknown>>(
  open: boolean,
  currentState: CatalogueFormState<TData>
): CatalogueFormState<TData> => {
  // If the state is already what we want, return the current state to prevent unnecessary re-renders
  if (currentState.isOpen === open) {
    return currentState;
  }

  // If opening, just update the isOpen state and keep everything else
  if (open) {
    return {
      ...currentState,
      isOpen: true,
    };
  }

  // If closing, only reset the form if it was actually open
  // This prevents unnecessary state changes
  if (currentState.isOpen) {
    return {
      formType: undefined,
      initialData: undefined,
      isOpen: false,
      mode: "create",
      onSuccess: undefined,
      tableId: undefined,
      tableType: undefined,
    };
  }

  // Form was already closed, return current state
  return currentState;
};

import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
  formValuesEqual,
} from "./form-runtime";
import type {
  AnyFieldDefinition,
  FieldValues,
  FormConfig,
  FormConfigContext,
} from "./types";

const reservedFields = new Set([
  "id",
  "_id",
  "createdAt",
  "updatedAt",
  "created_at",
  "updated_at",
]);

/** Start with common values, never the first row's differing values. */
export const commonBulkValues = (rows: readonly FieldValues[]): FieldValues =>
  cloneFormValue(
    Object.fromEntries(
      Object.entries(rows[0] ?? {}).filter(([key, value]) =>
        rows.every((row) => formValuesEqual(row[key], value))
      )
    )
  );

/** Check conditional fields against every target, including explicitly changed dependencies. */
export const bulkFieldEditable = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): boolean => {
  if (reservedFields.has(field.name) || field.bulkEdit === false) {
    return false;
  }
  const patch = Object.fromEntries(
    (context.bulkEdit?.fields ?? []).map((name) => [
      name,
      context.values?.[name],
    ])
  );
  return (context.bulkEdit?.rows ?? []).every((row) => {
    const rowContext = { ...context, row, values: { ...row, ...patch } };
    return !(
      fieldIsHidden(field, rowContext) || fieldIsDisabled(field, rowContext)
    );
  });
};

/** Keep field validation, but not a full-row schema that requires untouched fields. */
export const bulkFormConfig = (
  config: FormConfig,
  context: FormConfigContext
): FormConfig => ({
  ...config,
  schema: undefined,
  submitMode: "full",
  fields: config.fields
    .filter(
      (field) =>
        context.bulkEdit?.fields.includes(field.name) &&
        bulkFieldEditable(field, context)
    )
    .map((field) => ({ ...field, hidden: false, disabled: false })),
});

/** Strip untouched fields before validation and transforms, including undeclared row metadata. */
export const bulkFormValues = (
  config: FormConfig,
  values: FieldValues
): FieldValues =>
  cloneFormValue(
    Object.fromEntries(
      config.fields.map((field) => [field.name, values[field.name]])
    )
  );

/** Invalid completion reports must never clear unrelated rows or cause a silent success. */
export const bulkCompletion = (
  ids: string[],
  result: { success: boolean; failedIds?: string[] }
): { completed: string[]; remaining: string[] } => {
  if (result.success) {
    return { completed: [...ids], remaining: [] };
  }
  const failed = result.failedIds;
  if (!failed?.length || failed.some((id) => !ids.includes(id))) {
    return { completed: [], remaining: [...ids] };
  }
  return {
    completed: ids.filter((id) => !failed.includes(id)),
    remaining: ids.filter((id) => failed.includes(id)),
  };
};

"use client";

import { useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog";
import { useTableConfig } from "../../hooks/use-table-config";
import {
  type TableActions,
  useFormConfig,
  useTableActions,
} from "../../providers/table-provider";
import {
  bulkCompletion,
  bulkFieldEditable,
  bulkFormConfig,
  bulkFormValues,
  commonBulkValues,
} from "./bulk-form";
import { FormBuilder } from "./form-builder";
import { formValuesEqual } from "./form-runtime";
import { generateFormConfig } from "./generated-form-config";
import { useFormBuilder } from "./hooks/use-form-builder";
import type { FieldValues, FormConfigContext } from "./types";

export interface BulkEditTarget {
  id: string;
  row: FieldValues;
}

interface BulkEditorProps {
  targets: BulkEditTarget[];
  tableId: string;
  tableType: string;
  onClose: () => void;
  onCompleted: (ids: string[]) => Promise<void>;
}
export function CatalogueBulkEditor(
  props: Omit<BulkEditorProps, "targets"> & { targets: BulkEditTarget[] | null }
) {
  return props.targets ? (
    <BulkEditorForm {...props} targets={props.targets} />
  ) : null;
}

/** A bulk draft owns its targets. Changes to the live table selection never add targets. */
function BulkEditorForm({
  targets,
  tableId,
  tableType,
  onClose,
  onCompleted,
}: {
  targets: BulkEditTarget[];
  tableId: string;
  tableType: string;
  onClose: () => void;
  onCompleted: (ids: string[]) => Promise<void>;
}) {
  const { config: tableConfig } = useTableConfig(tableType);
  const getFormConfig = useFormConfig();
  const getActions = useTableActions();
  const [remaining, setRemaining] = useState(targets);
  const [applied, setApplied] = useState<string[]>([]);
  const initial = useMemo(
    () => commonBulkValues(targets.map((target) => target.row)),
    [targets]
  );
  const [values, setValues] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();
  const formTypes = [
    ...new Set(
      remaining.map(
        (target) =>
          tableConfig.form?.resolveEditFormType?.(target.row) ??
          tableConfig.form?.editFormType ??
          tableType
      )
    ),
  ];
  const formType = formTypes[0] ?? tableType;
  const context: FormConfigContext = {
    formType,
    tableType,
    tableId,
    mode: "edit",
    initialData: initial,
    values,
    bulkEdit: {
      ids: remaining.map((target) => target.id),
      rows: remaining.map((target) => target.row),
      fields: applied,
    },
  };
  const config =
    getFormConfig?.(formType, context) ??
    generateFormConfig(formType, tableConfig.columns.definitions);
  const editable = config.fields.filter((field) =>
    bulkFieldEditable(field, context)
  );
  const validationConfig = bulkFormConfig(config, context);
  const canSave = () =>
    tableConfig.table.allowBulkEdit !== false &&
    formTypes.length === 1 &&
    remaining.every(
      (target) => tableConfig.table.canEditRow?.(target.row) !== false
    );
  const eligibility = useRef(canSave);
  eligibility.current = canSave;
  const builder = useFormBuilder({
    config: validationConfig,
    context,
    initialData: initial,
    onValuesChange: (next) =>
      setValues((previous) =>
        formValuesEqual(previous, next) ? previous : next
      ),
    formOptions: {
      onSubmit: async (validated) => {
        if (busy) {
          return;
        }
        if (!canSave()) {
          setError(
            "These rows cannot share a bulk editor or are no longer editable."
          );
          return;
        }
        if (!validationConfig.fields.length) {
          setError("Choose at least one field to apply.");
          return;
        }
        setBusy(true);
        setError(undefined);
        try {
          const patch = bulkFormValues(validationConfig, validated);
          const payload = config.transform
            ? await config.transform(patch, context)
            : patch;
          if (!eligibility.current()) {
            throw new Error("These rows are no longer editable.");
          }
          const result = await getActions?.(tableType)?.bulkUpdate?.(
            remaining.map((target) => target.id),
            payload
          );
          await completeUpdate(result);
        } catch (cause) {
          setError(cause instanceof Error ? cause.message : String(cause));
        } finally {
          setBusy(false);
        }
      },
    },
  });
  async function completeUpdate(
    result:
      | Awaited<ReturnType<NonNullable<TableActions["bulkUpdate"]>>>
      | undefined
  ) {
    if (!result) {
      throw new Error("Bulk update is not configured.");
    }
    const progress = bulkCompletion(
      remaining.map((target) => target.id),
      result
    );
    if (progress.completed.length) {
      setRemaining((previous) =>
        previous.filter((target) => progress.remaining.includes(target.id))
      );
      await onCompleted(progress.completed);
    }
    if (!result.success) {
      builder.form.setErrorMap({
        onServer: { fields: result.fieldErrors ?? {} },
      } as never);
      throw new Error(
        result.error ??
          "Some rows could not be updated. Retry the remaining rows."
      );
    }
    onClose();
  }
  return (
    <Dialog
      onOpenChange={(open) => {
        if (!(open || busy)) {
          onClose();
        }
      }}
      open
    >
      <DialogContent className="max-h-[90vh] overflow-y-auto">
        <DialogTitle>Bulk edit</DialogTitle>
        <DialogDescription>
          Only checked fields are applied to the {remaining.length} selected
          rows.
        </DialogDescription>
        {formTypes.length > 1 && (
          <p role="alert">Select rows using the same form type.</p>
        )}
        {error && <p role="alert">{error}</p>}
        <fieldset className="space-y-3" disabled={busy || !canSave()}>
          {editable.map((field) => (
            <label className="flex items-center gap-2" key={field.name}>
              <input
                checked={applied.includes(field.name)}
                onChange={(event) =>
                  setApplied((previous) =>
                    event.target.checked
                      ? [...previous, field.name]
                      : previous.filter((name) => name !== field.name)
                  )
                }
                type="checkbox"
              />
              Apply {field.label}
            </label>
          ))}
          <FormBuilder
            asFieldset
            context={context}
            fields={builder.fields}
            form={builder.form}
            sections={builder.sections}
          />
        </fieldset>
        <div className="flex justify-end gap-2">
          <Button
            disabled={busy}
            onClick={onClose}
            type="button"
            variant="outline"
          >
            Cancel
          </Button>
          <Button
            disabled={busy || !canSave() || !validationConfig.fields.length}
            onClick={async () => {
              await builder.form.handleSubmit();
            }}
            type="button"
          >
            {busy ? "Saving…" : "Save"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * CatalogueFormContainer component
 * This component renders the CatalogueForm and listens to the catalogueFormAtom
 * It will automatically show/hide the form based on the atom state
 */
"use client";

import { useAtomValue } from "jotai";
import { lazy, Suspense } from "react";

import { catalogueFormAtom } from "./atoms/catalogue-form-atoms";

// Dynamically import the CatalogueForm component using React.lazy
const CatalogueForm = lazy(() =>
  import("./catalogue-form").then((mod) => ({ default: mod.CatalogueForm }))
);

/**
 * CatalogueFormContainer component
 * This component is responsible for rendering the CatalogueForm
 * and listening to the catalogueFormAtom
 */
export function CatalogueFormContainer() {
  // Get the form state from the atom (read-only to prevent conflicts)
  const formState = useAtomValue(catalogueFormAtom);

  // Extract the necessary values from the form state
  const { formType, initialData, mode, onSuccess, tableId, tableType } =
    formState;

  // If no form type is provided, don't render anything
  if (!formType) {
    return null;
  }

  // Render the CatalogueForm with the values from the atom
  // Let CatalogueForm handle all state management internally
  return (
    <Suspense fallback={null}>
      <CatalogueForm
        formType={formType}
        initialData={initialData}
        mode={mode}
        onSuccess={onSuccess as ((data: unknown) => void) | undefined}
        tableId={tableId}
        tableType={tableType}
      />
    </Suspense>
  );
}

import type { CatalogueFormLayoutConfig } from "../../config/form-config";

const DEFAULT_DRAWER_WIDTH = "28rem";
const DEFAULT_MODAL_WIDTH = "80vw";

export interface ResolvedCatalogueFormLayout {
  mode: "drawer" | "modal";
  width: string;
}

export function resolveCatalogueFormLayout(
  layout?: CatalogueFormLayoutConfig
): ResolvedCatalogueFormLayout {
  const mode = layout?.mode === "modal" ? "modal" : "drawer";

  return {
    mode,
    width:
      layout?.width ??
      (mode === "modal" ? DEFAULT_MODAL_WIDTH : DEFAULT_DRAWER_WIDTH),
  };
}

