export type CollectionItem = CollectionFieldItem;

export interface CollectionValidationResult {
  globalErrors: string[];
  itemErrors: string[][];
  messages: string[];
}

function isRecord(value: unknown): value is CollectionItem {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toCollectionItem(value: unknown): CollectionItem {
  if (isRecord(value)) {
    return value;
  }
  return { value };
}

export function cloneCollectionItem(item: CollectionItem): CollectionItem {
  return { ...item };
}

export function normalizeCollectionItems(value: unknown): CollectionItem[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.map((item) => cloneCollectionItem(toCollectionItem(item)));
}

export function insertCollectionItem(
  items: readonly CollectionItem[],
  item: CollectionItem,
  index = items.length
): CollectionItem[] {
  const safeIndex = Math.min(Math.max(index, 0), items.length);
  return [
    ...items.slice(0, safeIndex).map(cloneCollectionItem),
    cloneCollectionItem(item),
    ...items.slice(safeIndex).map(cloneCollectionItem),
  ];
}

export function replaceCollectionItem(
  items: readonly CollectionItem[],
  index: number,
  item: CollectionItem
): CollectionItem[] {
  if (index < 0 || index >= items.length) {
    return items.map(cloneCollectionItem);
  }
  return items.map((currentItem, currentIndex) =>
    currentIndex === index
      ? cloneCollectionItem(item)
      : cloneCollectionItem(currentItem)
  );
}

export function removeCollectionItem(
  items: readonly CollectionItem[],
  index: number
): CollectionItem[] {
  return items
    .filter((_, currentIndex) => currentIndex !== index)
    .map(cloneCollectionItem);
}

export function moveCollectionItem(
  items: readonly CollectionItem[],
  fromIndex: number,
  toIndex: number
): CollectionItem[] {
  if (
    fromIndex < 0 ||
    fromIndex >= items.length ||
    toIndex < 0 ||
    toIndex >= items.length ||
    fromIndex === toIndex
  ) {
    return items.map(cloneCollectionItem);
  }

  const nextItems = items.map(cloneCollectionItem);
  const [item] = nextItems.splice(fromIndex, 1);
  if (!item) {
    return nextItems;
  }
  nextItems.splice(toIndex, 0, item);
  return nextItems;
}

export function getCollectionItemErrors<
  TFieldValues extends FieldValues = FieldValues,
>(
  field: Pick<CollectionFieldDefinition<TFieldValues>, "validateItem">,
  item: CollectionItem,
  index: number | null
): string[] {
  return field.validateItem?.(item, index) ?? [];
}

export function getCollectionValidationResult<
  TFieldValues extends FieldValues = FieldValues,
>(
  field: Pick<
    CollectionFieldDefinition<TFieldValues>,
    "itemLabel" | "validateItem" | "validateItems"
  >,
  value: unknown
): CollectionValidationResult {
  const items = normalizeCollectionItems(value);
  const itemErrors = items.map((item, index) =>
    getCollectionItemErrors(field, item, index)
  );
  const globalErrors = field.validateItems?.(items) ?? [];
  const itemMessages = itemErrors.flatMap((errors, index) =>
    errors.map((message) => `${field.itemLabel} ${index + 1}: ${message}`)
  );

  return {
    globalErrors,
    itemErrors,
    messages: [...globalErrors, ...itemMessages],
  };
}

export function getCollectionValidationMessages<
  TFieldValues extends FieldValues = FieldValues,
>(
  field: Pick<
    CollectionFieldDefinition<TFieldValues>,
    "itemLabel" | "validateItem" | "validateItems"
  >,
  value: unknown
): string[] {
  return getCollectionValidationResult(field, value).messages;
}

export function createCollectionFieldValidators<
  TFieldValues extends FieldValues = FieldValues,
>(
  field: Pick<
    CollectionFieldDefinition<TFieldValues>,
    "itemLabel" | "validateItem" | "validateItems"
  >
) {
  const validate = ({ value }: { value: unknown }) => {
    const errors = getCollectionValidationMessages(field, value);
    return errors.length > 0 ? errors : undefined;
  };

  return {
    onChange: validate,
    onSubmit: validate,
  };
}

/**
 * Collection field component for array-like form values.
 */
"use client";

import {
  ArrowDownIcon,
  ArrowUpIcon,
  PencilIcon,
  PlusIcon,
  Trash2Icon,
} from "lucide-react";
import type { ReactNode } from "react";
import { Fragment, useEffect, useId, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../../providers/table-provider";
import { FormBuilder } from "../form-builder";
import {
  defaultFieldValue,
  formValuesEqual,
  validateFormFields,
} from "../form-runtime";
import { useFormBuilder } from "../hooks/use-form-builder";
import type {
  AnyFieldDefinition,
  CollectionFieldActionLabels,
  CollectionFieldColumnDefinition,
  CollectionFieldCreateAction,
  CollectionFieldDefinition,
  FieldValues,
  FormConfigContext,
  FormFieldApi,
} from "../types";
import {
  type CollectionItem,
  cloneCollectionItem,
  getCollectionItemErrors,
  getCollectionValidationResult,
  insertCollectionItem,
  moveCollectionItem,
  normalizeCollectionItems,
  removeCollectionItem,
  replaceCollectionItem,
} from "./collection-field-utils";

function DeclarativeCollectionItem({
  fields,
  item,
  onChange,
  disabled,
  context,
}: {
  context?: FormConfigContext;
  fields: AnyFieldDefinition[];
  item: FieldValues;
  onChange: (item: FieldValues) => void;
  disabled?: boolean;
}) {
  const { form } = useFormBuilder({
    config: { id: "collection-item", fields },
    initialData: item,
    context: context ? { ...context, values: item } : undefined,
    onValuesChange: (values) => {
      if (!formValuesEqual(values, item)) {
        onChange(values);
      }
    },
  });
  return (
    <fieldset disabled={disabled}>
      <FormBuilder asFieldset context={context} fields={fields} form={form} />
    </fieldset>
  );
}

interface CollectionEditorState {
  draft: CollectionItem;
  index: number | null;
  mode: "create" | "edit";
}

export interface CollectionEditorProps {
  addLabel: string;
  columns: CollectionFieldColumnDefinition[];
  createActions?: CollectionFieldCreateAction[];
  createItem: (items: readonly CollectionItem[]) => CollectionItem;
  description?: ReactNode;
  disabled?: boolean;
  emptyLabel?: string;
  errors?: string[];
  getItemKey?: (item: CollectionItem, index: number) => string;
  id?: string;
  itemLabel: string;
  label?: ReactNode;
  labelKeys?: Partial<Record<keyof CollectionFieldActionLabels, string>>;
  labels?: Partial<CollectionFieldActionLabels>;
  onChange: (items: CollectionItem[]) => void;
  renderItemForm: (props: {
    disabled?: boolean;
    index: number | null;
    item: CollectionItem;
    onChange: (item: CollectionItem) => void;
  }) => ReactNode;
  validateDraft?: (
    item: CollectionItem
  ) => Promise<{ values: CollectionItem; errors: Record<string, string> }>;
  validateItem?: (item: CollectionItem, index: number | null) => string[];
  validateItems?: (items: readonly CollectionItem[]) => string[];
  value: unknown;
}

interface ResolvedCollectionLabels extends CollectionFieldActionLabels {
  addTitle: string;
  editTitle: string;
}

function uniqueMessages(messages: readonly string[]): string[] {
  return [...new Set(messages.filter(Boolean))];
}

function translateWithFallback(
  t: (key: string) => string,
  key: string,
  fallback: string
): string {
  const translated = t(key);
  return translated === key ? fallback : translated;
}

function resolveCollectionLabels({
  itemLabel,
  labelKeys,
  labels,
  t,
}: {
  itemLabel: string;
  labelKeys?: Partial<Record<keyof CollectionFieldActionLabels, string>>;
  labels?: Partial<CollectionFieldActionLabels>;
  t: (key: string) => string;
}): ResolvedCollectionLabels {
  const fallbackLabels: CollectionFieldActionLabels = {
    actions: translateWithFallback(t, "collection.actions", "Actions"),
    addTitle: `Add ${itemLabel}`,
    cancel: translateWithFallback(t, "collection.cancel", "Cancel"),
    deleteItem: translateWithFallback(t, "collection.deleteItem", "Delete"),
    editItem: translateWithFallback(t, "collection.editItem", "Edit"),
    editTitle: `Edit ${itemLabel}`,
    moveDown: translateWithFallback(t, "collection.moveDown", "Move down"),
    moveUp: translateWithFallback(t, "collection.moveUp", "Move up"),
    save: translateWithFallback(t, "collection.save", "Save"),
  };

  const resolvedEntries = Object.entries(fallbackLabels).map(
    ([name, fallback]) => {
      const typedName = name as keyof CollectionFieldActionLabels;
      const key = labelKeys?.[typedName];
      if (key) {
        return [typedName, t(key)];
      }
      return [typedName, labels?.[typedName] ?? fallback];
    }
  );

  return Object.fromEntries(resolvedEntries) as ResolvedCollectionLabels;
}

function formatCollectionValue(value: unknown): ReactNode {
  if (value == null || value === "") {
    return <span className="text-muted-foreground">-</span>;
  }
  if (typeof value === "boolean") {
    return value ? "Yes" : "No";
  }
  if (typeof value === "number" || typeof value === "string") {
    return String(value);
  }
  return (
    <code className="rounded bg-muted px-1 py-0.5 text-xs">
      {JSON.stringify(value)}
    </code>
  );
}

function renderCollectionCell(
  column: CollectionFieldColumnDefinition,
  item: CollectionItem,
  index: number
): ReactNode {
  if (column.render) {
    return column.render(item, index);
  }
  return formatCollectionValue(item[column.id]);
}

function getEditorTitle(
  state: CollectionEditorState,
  labels: ResolvedCollectionLabels
): string {
  if (state.mode === "create") {
    return labels.addTitle;
  }
  return `${labels.editTitle} ${state.index == null ? "" : state.index + 1}`.trim();
}

export function CollectionEditor({
  addLabel,
  columns,
  createActions,
  createItem,
  description,
  disabled,
  emptyLabel,
  errors = [],
  getItemKey,
  id,
  itemLabel,
  label,
  labelKeys,
  labels,
  onChange,
  renderItemForm,
  validateDraft,
  validateItem,
  validateItems,
  value,
}: CollectionEditorProps) {
  const [saving, setSaving] = useState(false);
  const [draftIssues, setDraftIssues] = useState<string[]>([]);
  const generatedId = useId();
  const fieldId = id ?? generatedId;
  const { t } = useTranslations();
  const items = useMemo(() => normalizeCollectionItems(value), [value]);
  const [editorState, setEditorState] = useState<CollectionEditorState | null>(
    null
  );
  const resolvedLabels = useMemo(
    () => resolveCollectionLabels({ itemLabel, labelKeys, labels, t }),
    [itemLabel, labelKeys, labels, t]
  );
  const validation = useMemo(
    () =>
      getCollectionValidationResult(
        { itemLabel, validateItem, validateItems },
        items
      ),
    [itemLabel, items, validateItem, validateItems]
  );
  const visibleErrors = uniqueMessages([...validation.globalErrors, ...errors]);
  const isInvalid = validation.messages.length > 0 || visibleErrors.length > 0;
  const visibleColumns =
    columns.length > 0
      ? columns
      : [
          {
            header: itemLabel,
            id: "value",
          } satisfies CollectionFieldColumnDefinition,
        ];
  const addActions =
    createActions && createActions.length > 0
      ? createActions
      : [{ createItem, label: addLabel }];

  const openCreateEditor = (
    actionCreateItem: (items: readonly CollectionItem[]) => CollectionItem
  ) => {
    setDraftIssues([]);
    setEditorState({
      draft: cloneCollectionItem(actionCreateItem(items)),
      index: null,
      mode: "create",
    });
  };

  const openEditEditor = (item: CollectionItem, index: number) => {
    setDraftIssues([]);
    setEditorState({
      draft: cloneCollectionItem(item),
      index,
      mode: "edit",
    });
  };

  const closeEditor = () => {
    setEditorState(null);
  };

  const saveEditor = async () => {
    if (!editorState || saving || disabled) {
      return;
    }
    setSaving(true);
    try {
      const validated = await validateDraft?.(editorState.draft);
      if (validated && Object.keys(validated.errors).length) {
        setDraftIssues(Object.values(validated.errors));
        return;
      }
      const item = validated?.values ?? editorState.draft;
      onChange(
        editorState.index == null
          ? insertCollectionItem(items, item)
          : replaceCollectionItem(items, editorState.index, item)
      );
      closeEditor();
    } catch (cause) {
      setDraftIssues([cause instanceof Error ? cause.message : String(cause)]);
    } finally {
      setSaving(false);
    }
  };

  const draftErrors = editorState
    ? getCollectionItemErrors(
        { validateItem },
        editorState.draft,
        editorState.index
      )
    : [];

  return (
    <Field
      aria-describedby={description ? `${fieldId}-description` : undefined}
      aria-invalid={isInvalid}
      className="gap-3"
      data-invalid={isInvalid}
    >
      {label && <FieldLabel>{label}</FieldLabel>}
      {description && (
        <FieldDescription id={`${fieldId}-description`}>
          {description}
        </FieldDescription>
      )}

      <div className="rounded-md border bg-background">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b p-3">
          <div className="text-muted-foreground text-sm">
            {items.length} {itemLabel}
          </div>
          <div className="flex flex-wrap gap-2">
            {addActions.map((action) => (
              <Button
                disabled={disabled}
                key={action.id ?? action.label}
                onClick={() => openCreateEditor(action.createItem)}
                size="sm"
                type="button"
                variant="outline"
              >
                <PlusIcon />
                <span>{action.label}</span>
              </Button>
            ))}
          </div>
        </div>

        {items.length === 0 ? (
          <div className="p-4 text-muted-foreground text-sm">
            {emptyLabel ?? `No ${itemLabel.toLowerCase()} yet.`}
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {visibleColumns.map((column) => (
                  <TableHead key={column.id}>{column.header}</TableHead>
                ))}
                <TableHead className="w-36 text-right">
                  {resolvedLabels.actions}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {items.map((item, index) => {
                const rowErrors = validation.itemErrors[index] ?? [];
                const rowInvalid = rowErrors.length > 0;
                const itemKey =
                  getItemKey?.(item, index) ?? `${index}-${itemLabel}`;
                return (
                  <Fragment key={itemKey}>
                    <TableRow
                      aria-invalid={rowInvalid}
                      className={cn(rowInvalid && "bg-destructive/5")}
                      data-invalid={rowInvalid}
                    >
                      {visibleColumns.map((column) => (
                        <TableCell key={column.id}>
                          {renderCollectionCell(column, item, index)}
                        </TableCell>
                      ))}
                      <TableCell>
                        <div className="flex justify-end gap-1">
                          <Button
                            aria-label={`${resolvedLabels.moveUp} ${itemLabel} ${index + 1}`}
                            disabled={disabled || index === 0}
                            onClick={() =>
                              onChange(
                                moveCollectionItem(items, index, index - 1)
                              )
                            }
                            size="icon-sm"
                            type="button"
                            variant="ghost"
                          >
                            <ArrowUpIcon />
                          </Button>
                          <Button
                            aria-label={`${resolvedLabels.moveDown} ${itemLabel} ${index + 1}`}
                            disabled={disabled || index === items.length - 1}
                            onClick={() =>
                              onChange(
                                moveCollectionItem(items, index, index + 1)
                              )
                            }
                            size="icon-sm"
                            type="button"
                            variant="ghost"
                          >
                            <ArrowDownIcon />
                          </Button>
                          <Button
                            aria-label={`${resolvedLabels.editItem} ${itemLabel} ${index + 1}`}
                            disabled={disabled}
                            onClick={() => openEditEditor(item, index)}
                            size="icon-sm"
                            type="button"
                            variant="ghost"
                          >
                            <PencilIcon />
                          </Button>
                          <Button
                            aria-label={`${resolvedLabels.deleteItem} ${itemLabel} ${index + 1}`}
                            disabled={disabled}
                            onClick={() =>
                              onChange(removeCollectionItem(items, index))
                            }
                            size="icon-sm"
                            type="button"
                            variant="ghost"
                          >
                            <Trash2Icon />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                    {rowInvalid && (
                      <TableRow key={`${itemKey}-errors`}>
                        <TableCell colSpan={visibleColumns.length + 1}>
                          <FieldError
                            errors={rowErrors.map((message) => ({ message }))}
                          />
                        </TableCell>
                      </TableRow>
                    )}
                  </Fragment>
                );
              })}
            </TableBody>
          </Table>
        )}
      </div>

      <FieldError errors={visibleErrors.map((message) => ({ message }))} />

      {editorState && (
        <Dialog
          onOpenChange={(open) => {
            if (!(open || saving)) {
              closeEditor();
            }
          }}
          open
        >
          <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {getEditorTitle(editorState, resolvedLabels)}
              </DialogTitle>
              {draftErrors.length > 0 && (
                <DialogDescription>
                  {draftErrors.length === 1
                    ? draftErrors[0]
                    : `${draftErrors.length} validation errors`}
                </DialogDescription>
              )}
            </DialogHeader>
            <div className="space-y-4">
              {renderItemForm({
                disabled: disabled || saving,
                index: editorState.index,
                item: editorState.draft,
                onChange: (item) =>
                  setEditorState((current) =>
                    current
                      ? { ...current, draft: cloneCollectionItem(item) }
                      : current
                  ),
              })}
              <FieldError
                errors={[...draftErrors, ...draftIssues].map((message) => ({
                  message,
                }))}
              />
            </div>
            <DialogFooter>
              <Button
                disabled={saving}
                onClick={closeEditor}
                type="button"
                variant="outline"
              >
                {resolvedLabels.cancel}
              </Button>
              <Button
                disabled={disabled || saving}
                onClick={async () => {
                  await saveEditor();
                }}
                type="button"
              >
                {resolvedLabels.save}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </Field>
  );
}

interface CollectionFieldProps<TFieldValues extends FieldValues> {
  field: CollectionFieldDefinition<TFieldValues>;
  fieldApi: FormFieldApi<unknown>;
  context?: FormConfigContext;
}

export function CollectionField<TFieldValues extends FieldValues>({
  field,
  fieldApi,
  context,
}: CollectionFieldProps<TFieldValues>) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((error) => (typeof error === "string" ? error : String(error)))
    : [];

  useEffect(() => {
    if (!Array.isArray(fieldApi.state.value)) {
      fieldApi.handleChange([]);
    }
  }, [fieldApi.handleChange, fieldApi.state.value]);

  const itemContext: FormConfigContext = context ?? {
    formType: "collection",
    tableId: "collection",
    tableType: "collection",
    mode: "create",
  };
  const createItem =
    field.createItem ??
    (() =>
      Object.fromEntries(
        (field.itemFields ?? []).map((item) => [
          item.name,
          defaultFieldValue(item),
        ])
      ));
  const renderItem =
    field.renderItemForm ??
    ((props) => (
      <DeclarativeCollectionItem
        {...props}
        context={itemContext}
        fields={field.itemFields ?? []}
      />
    ));
  const items = normalizeCollectionItems(fieldApi.state.value);
  if (field.collectionMode === "inline") {
    return (
      <fieldset className="space-y-3" disabled={field.disabled === true}>
        <legend>{field.label}</legend>
        {items.map((item, index) => (
          <div
            className="space-y-2 rounded-md border p-3"
            key={field.getItemKey?.(item, index) ?? String(item.id ?? index)}
          >
            {renderItem({
              item,
              index,
              disabled: field.disabled === true,
              onChange: (next) =>
                fieldApi.handleChange(
                  replaceCollectionItem(items, index, next)
                ),
            })}
            <div className="flex gap-2">
              <Button
                aria-label={`Move item ${index + 1} up`}
                disabled={index === 0}
                onClick={() =>
                  fieldApi.handleChange(
                    moveCollectionItem(items, index, index - 1)
                  )
                }
                type="button"
                variant="outline"
              >
                ↑
              </Button>
              <Button
                aria-label={`Move item ${index + 1} down`}
                disabled={index === items.length - 1}
                onClick={() =>
                  fieldApi.handleChange(
                    moveCollectionItem(items, index, index + 1)
                  )
                }
                type="button"
                variant="outline"
              >
                ↓
              </Button>
              <Button
                onClick={() =>
                  fieldApi.handleChange(removeCollectionItem(items, index))
                }
                type="button"
                variant="outline"
              >
                {field.labels?.deleteItem ?? "Delete"}
              </Button>
            </div>
          </div>
        ))}
        <Button
          onClick={() =>
            fieldApi.handleChange(
              insertCollectionItem(items, createItem(items))
            )
          }
          type="button"
        >
          {field.addLabel ?? "Add item"}
        </Button>
        <FieldError errors={errorMessages.map((message) => ({ message }))} />
      </fieldset>
    );
  }

  return (
    <CollectionEditor
      addLabel={field.addLabel ?? "Add item"}
      columns={
        field.columns ??
        (field.itemFields ?? []).map((item) => ({
          id: item.name,
          header: item.label,
        }))
      }
      createActions={field.createActions}
      createItem={createItem}
      description={
        field.descriptionKey ? t(field.descriptionKey) : field.description
      }
      disabled={field.disabled === true}
      emptyLabel={field.emptyLabel}
      errors={errorMessages}
      getItemKey={field.getItemKey}
      itemLabel={field.itemLabel ?? "item"}
      label={field.labelKey ? t(field.labelKey) : field.label}
      labelKeys={field.labelKeys}
      labels={field.labels}
      onChange={fieldApi.handleChange}
      renderItemForm={renderItem}
      validateDraft={
        field.itemFields
          ? (item) =>
              validateFormFields(field.itemFields ?? [], item, {
                ...itemContext,
                values: item,
              })
          : undefined
      }
      validateItem={field.validateItem}
      validateItems={field.validateItems}
      value={fieldApi.state.value}
    />
  );
}

"use client";

import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { useTranslations } from "../../../providers/table-provider";
import type { DateFieldDefinition, FormFieldApi } from "../types";

const DATE_INPUT_VALUE_PATTERN = /^\d{4}-\d{2}-\d{2}/;

interface DateFieldProps<TFieldValues extends Record<string, unknown>> {
  field: DateFieldDefinition<TFieldValues>;
  fieldApi: FormFieldApi<Date | string | null>;
}

function toDateInputValue(value: Date | string | null | undefined): string {
  if (value == null || value === "") {
    return "";
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? ""
      : value.toISOString().slice(0, 10);
  }

  const dateMatch = value.match(DATE_INPUT_VALUE_PATTERN);
  if (dateMatch) {
    return dateMatch[0];
  }

  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime())
    ? ""
    : parsed.toISOString().slice(0, 10);
}

export function DateField<TFieldValues extends Record<string, unknown>>({
  field,
  fieldApi,
}: DateFieldProps<TFieldValues>) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <FieldLabel>
        {field.labelKey ? t(field.labelKey) : field.label}
      </FieldLabel>
      <Input
        aria-invalid={!fieldApi.state.meta.isValid}
        disabled={field.disabled === true}
        max={toDateInputValue(field.maxDate)}
        min={toDateInputValue(field.minDate)}
        name={fieldApi.name}
        onBlur={fieldApi.handleBlur}
        onChange={(event) => fieldApi.handleChange(event.target.value)}
        placeholder={
          field.placeholderKey ? t(field.placeholderKey) : field.placeholder
        }
        type="date"
        value={toDateInputValue(fieldApi.state.value)}
      />
      {field.description != null && (
        <FieldDescription>
          {field.descriptionKey ? t(field.descriptionKey) : field.description}
        </FieldDescription>
      )}
      <FieldError errors={errorMessages.map((message) => ({ message }))} />
    </Field>
  );
}

/**
 * Dynamic value field – renders different inputs based on type (TanStack Form + Field)
 */
"use client";

import type {
  AnyFieldDefinition,
  CheckboxFieldDefinition,
  FormFieldApi,
  NumberFieldDefinition,
  TextareaFieldDefinition,
  TextFieldDefinition,
} from "../types";

import { NumberField } from "./number-field";
import { SwitchField } from "./switch-field";
import { TextField } from "./text-field";
import { TextareaField } from "./textarea-field";
import { ValueTypeField } from "./value-type-field";

interface DynamicValueFieldProps {
  field: AnyFieldDefinition;
  fieldApi: FormFieldApi<unknown>;
  type: "boolean" | "json" | "number" | "string";
}

export function DynamicValueField({
  field,
  fieldApi,
  type,
}: DynamicValueFieldProps) {
  switch (type) {
    case "boolean":
      return (
        <SwitchField
          field={
            {
              ...field,
              type: "checkbox",
              variant: "switch",
            } as CheckboxFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<boolean>}
        />
      );
    case "json":
      return (
        <TextareaField
          field={
            {
              ...field,
              type: "textarea",
            } as TextareaFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<string>}
        />
      );
    case "number":
      return (
        <NumberField
          field={
            {
              ...field,
              type: "number",
            } as NumberFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<number | string>}
        />
      );
    case "string":
      return (
        <TextField
          field={
            {
              ...field,
              type: "text",
            } as TextFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<string>}
        />
      );
    default:
      return (
        <ValueTypeField
          fieldApi={fieldApi}
          label={field.label}
          valueType={type}
        />
      );
  }
}

