    }
    const advancedActive = t("filters.advanced.active");
    if (advancedActive !== "filters.advanced.active") {
      return advancedActive;
    }
    return "Enabled";
  })();
  const disabledStateLabel = (() => {
    const valueDisabled = t("value.disabled");
    if (valueDisabled !== "value.disabled") {
