"use client";

import { ExternalLink, Globe, Loader2 } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../../providers/table-provider";
import type { FormFieldApi, UrlFieldDefinition } from "../types";

interface UrlMeta {
  title?: string;
  description?: string;
  image?: string;
  favicon?: string;
  siteName?: string;
  url: string;
}

const isValidUrl = (value: string): boolean => {
  try {
    const parsed = new URL(value);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
};

const DEBOUNCE_MS = 600;

function useUrlMeta(url: string | undefined) {
  const [meta, setMeta] = useState<UrlMeta | undefined>();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | undefined>();
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!(url && isValidUrl(url))) {
      setMeta(undefined);
      setIsLoading(false);
      setError(undefined);
      return;
    }

    const timeoutId = setTimeout(() => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setIsLoading(true);
      setError(undefined);

      fetch(`/api/url-meta?url=${encodeURIComponent(url)}`, {
        signal: controller.signal,
      })
        .then((res) => {
          if (!res.ok) {
            throw new Error("Failed to fetch metadata");
          }
          return res.json() as Promise<UrlMeta>;
        })
        .then((data) => {
          if (!controller.signal.aborted) {
            setMeta(data);
            setIsLoading(false);
          }
        })
        .catch((err: unknown) => {
          if (err instanceof DOMException && err.name === "AbortError") {
            return;
          }
          if (!controller.signal.aborted) {
            setError("Could not fetch preview");
            setIsLoading(false);
          }
        });
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timeoutId);
      abortRef.current?.abort();
    };
  }, [url]);

  return { meta, isLoading, error };
}

interface UrlFieldProps<TFieldValues extends Record<string, unknown>> {
  field: UrlFieldDefinition<TFieldValues>;
  fieldApi: FormFieldApi<string>;
}

export function UrlField<TFieldValues extends Record<string, unknown>>({
  field,
  fieldApi,
}: UrlFieldProps<TFieldValues>) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];

  const currentValue = fieldApi.state.value ?? "";
  const showPreview = field.showMetaPreview !== false;
  const {
    meta,
    isLoading,
    error: _metaError,
  } = useUrlMeta(
    showPreview && isValidUrl(currentValue) ? currentValue : undefined
  );

  const handleOpenUrl = useCallback(() => {
    if (currentValue && isValidUrl(currentValue)) {
      window.open(currentValue, "_blank", "noopener");
    }
  }, [currentValue]);

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <FieldLabel>
        {field.labelKey ? t(field.labelKey) : field.label}
      </FieldLabel>
      <div className="relative">
        <Input
          aria-invalid={!fieldApi.state.meta.isValid}
          className="pr-9"
          disabled={field.disabled === true}
          name={fieldApi.name}
          onBlur={fieldApi.handleBlur}
          onChange={(e) => fieldApi.handleChange(e.target.value)}
          placeholder={
            field.placeholderKey
              ? t(field.placeholderKey)
              : (field.placeholder ?? "https://...")
          }
          type="url"
          value={currentValue}
        />
        {currentValue && isValidUrl(currentValue) && (
          <button
            className={cn(
              "absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5",
              "text-muted-foreground transition-colors hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30"
            )}
            onClick={handleOpenUrl}
            tabIndex={0}
            title="Open URL"
            type="button"
          >
            <ExternalLink aria-hidden className="size-4" />
          </button>
        )}
      </div>

      {field.description != null && (
        <FieldDescription>
          {field.descriptionKey ? t(field.descriptionKey) : field.description}
        </FieldDescription>
      )}

      <FieldError errors={errorMessages.map((message) => ({ message }))} />

      {showPreview && currentValue && isValidUrl(currentValue) && (
        <UrlMetaPreview isLoading={isLoading} meta={meta} url={currentValue} />
      )}
    </Field>
  );
}

function MetaImage({ alt, src }: { alt: string; src: string }) {
  const [hasError, setHasError] = useState(false);

  if (hasError) {
    return null;
  }

  return (
    <div className="relative w-28 shrink-0 bg-muted">
      {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: og:image preview inside link */}
      {/* biome-ignore lint/performance/noImgElement: library component, no Next.js dependency */}
      {/* biome-ignore lint/correctness/useImageSize: dynamic og:image, size unknown */}
      <img
        alt={alt}
        className="size-full object-cover"
        loading="lazy"
        onError={() => setHasError(true)}
        src={src}
      />
    </div>
  );
}

function MetaFavicon({ src }: { src: string }) {
  const [hasError, setHasError] = useState(false);

  if (hasError) {
    return <Globe aria-hidden className="size-3.5 text-muted-foreground" />;
  }

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: favicon preview inside link
    // biome-ignore lint/performance/noImgElement: library component, no Next.js dependency
    <img
      alt=""
      className="size-3.5"
      height={14}
      loading="lazy"
      onError={() => setHasError(true)}
      src={src}
      width={14}
    />
  );
}

function UrlMetaPreview({
  isLoading,
  meta,
  url,
}: {
  isLoading: boolean;
  meta: UrlMeta | undefined;
  url: string;
}) {
  if (isLoading) {
    return (
      <div className="mt-2 flex items-center gap-2 rounded-lg border border-border p-3">
        <Loader2
          aria-hidden
          className="size-4 animate-spin text-muted-foreground"
        />
        <span className="text-muted-foreground text-sm">Loading preview…</span>
      </div>
    );
  }

  if (!meta) {
    return null;
  }

  const hasMeaningfulData = meta.title || meta.description || meta.image;
  if (!hasMeaningfulData) {
    return null;
  }

  return (
    <a
      className={cn(
        "mt-2 flex gap-3 overflow-hidden rounded-lg border border-border",
        "bg-muted/30 transition-colors hover:bg-muted/50",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30"
      )}
      href={url}
      rel="noopener"
      target="_blank"
    >
      {meta.image && <MetaImage alt={meta.title ?? ""} src={meta.image} />}
      <div className="flex min-w-0 flex-col justify-center gap-0.5 py-2.5 pr-3">
        {meta.siteName && (
          <div className="flex items-center gap-1.5">
            {meta.favicon ? (
              <MetaFavicon src={meta.favicon} />
            ) : (
              <Globe aria-hidden className="size-3.5 text-muted-foreground" />
            )}
            <span className="truncate text-muted-foreground text-xs">
              {meta.siteName}
            </span>
          </div>
        )}
        {meta.title && (
          <p className="truncate font-medium text-foreground text-sm">
            {meta.title}
          </p>
        )}
        {meta.description && (
          <p className="line-clamp-2 text-muted-foreground text-xs">
            {meta.description}
          </p>
        )}
      </div>
    </a>
  );
}

"use client";

import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { useTranslations } from "../../../providers/table-provider";
import type { TranslationConfig } from "../atoms";
import type { FormFieldApi } from "../types";

export type ValueType = "boolean" | "json" | "number" | "string";

export interface ValueTypeFieldProps {
  description?: string;
  fieldApi: FormFieldApi<unknown>;
  label: string;
  placeholder?: string;
  translationConfig?: TranslationConfig;
  valueType: ValueType;
}

function coerceToBooleanType(value: unknown): boolean {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    return value === "true";
  }
  return Boolean(value);
}

function coerceToJsonType(value: unknown): unknown {
  if (typeof value === "object" && value !== null) {
    return value;
  }
  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch {
      return {};
    }
  }
  return {};
}

function coerceToNumberType(value: unknown): number {
  if (typeof value === "number") {
    return value;
  }
  if (value === "") {
    return 0;
  }
  return Number(value);
}

export function coerceToType(value: unknown, type: ValueType): unknown {
  switch (type) {
    case "boolean":
      return coerceToBooleanType(value);
    case "json":
      return coerceToJsonType(value);
    case "number":
      return coerceToNumberType(value);
    case "string":
      return String(value || "");
    default:
      return value;
  }
}

function ValueTypeFieldInput({
  fieldApi,
  placeholder,
  t,
  valueType,
}: {
  fieldApi: FormFieldApi<unknown>;
  placeholder?: string;
  t: (key: string) => string;
  valueType: ValueType;
}) {
  switch (valueType) {
    case "boolean":
      return (
        <div className="flex items-center space-x-2">
          <Switch
            checked={fieldApi.state.value === true}
            onCheckedChange={(val) => fieldApi.handleChange(Boolean(val))}
          />
          <span className="text-muted-foreground text-sm">
            {fieldApi.state.value ? t("value.enabled") : t("value.disabled")}
          </span>
        </div>
      );
    case "json":
      return (
        <Textarea
          className="font-mono text-sm"
          onChange={(e) => {
            try {
              const value =
                e.target.value.trim() === "" ? {} : JSON.parse(e.target.value);
              fieldApi.handleChange(value);
            } catch {
              // Keep invalid JSON in textarea
            }
          }}
          placeholder={placeholder ?? t("value.json_placeholder")}
          rows={5}
          value={(() => {
            const v = fieldApi.state.value;
            if (v === undefined) {
              return "";
            }
            if (typeof v === "object") {
              return JSON.stringify(v, null, 2);
            }
            return String(v);
          })()}
        />
      );
    case "number":
      return (
        <Input
          onChange={(e) => {
            const v = e.target.value === "" ? "" : Number(e.target.value);
            fieldApi.handleChange(v);
          }}
          placeholder={placeholder ?? t("value.number_placeholder")}
          type="number"
          value={
            fieldApi.state.value === undefined
              ? ""
              : String(fieldApi.state.value)
          }
        />
      );
    default:
      return (
        <Input
          onChange={(e) => fieldApi.handleChange(e.target.value)}
          placeholder={placeholder ?? t("value.string_placeholder")}
          type="text"
          value={String(fieldApi.state.value ?? "")}
        />
      );
  }
}

export function ValueTypeField({
  description,
  fieldApi,
  label,
  placeholder,
  valueType,
}: ValueTypeFieldProps) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <FieldLabel>{label}</FieldLabel>
      {description != null && (
        <FieldDescription>{description}</FieldDescription>
      )}
      <ValueTypeFieldInput
        fieldApi={fieldApi}
        placeholder={placeholder}
        t={t}
        valueType={valueType}
      />
      <FieldError errors={errorMessages.map((message) => ({ message }))} />
    </Field>
  );
}

"use client";

import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../../providers/table-provider";

import type { FormFieldApi } from "../types";
import type { ValueType } from "./value-type-field";

export interface ValueTypeSelectorProps {
  description?: string;
  fieldApi: FormFieldApi<string>;
  label: string;
  onValueTypeChange?: (valueType: ValueType) => void;
  placeholder?: string;
}

export function ValueTypeSelector({
  description,
  fieldApi,
  label,
  onValueTypeChange,
  placeholder,
}: ValueTypeSelectorProps) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];

  const valueTypes: { label: string; value: ValueType }[] = [
    { label: t("value_types.boolean"), value: "boolean" },
    { label: t("value_types.number"), value: "number" },
    { label: t("value_types.string"), value: "string" },
    { label: t("value_types.json"), value: "json" },
  ];

  const handleValueTypeChange = (value: string) => {
    fieldApi.handleChange(value);
    onValueTypeChange?.(value as ValueType);
  };

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <FieldLabel>{label}</FieldLabel>
      {description != null && (
        <FieldDescription>{description}</FieldDescription>
      )}
      <Select
        onValueChange={(v) =>
          v != null ? handleValueTypeChange(v) : undefined
        }
        value={String(fieldApi.state.value ?? "string")}
      >
        <SelectTrigger>
          <SelectValue
            placeholder={placeholder ?? t("value_types.select_placeholder")}
          />
        </SelectTrigger>
        <SelectContent>
          {valueTypes.map((type) => (
            <SelectItem key={type.value} value={type.value}>
              {type.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <FieldError errors={errorMessages.map((message) => ({ message }))} />
    </Field>
  );
}

/**
 * Form builder component (TanStack Form + Field)
 * Renders a form based on field definitions using form.Field for each field.
 */
"use client";

import { useStore } from "@tanstack/react-form";
import type { ReactNode } from "react";
import { useEffect } from "react";
import { Button } from "@/components/ui/button";
import { useTranslations } from "../../providers/table-provider";
import { RuntimeField } from "./field-runtime";
import {
  CheckboxField,
  CollectionField,
  DateField,
  DynamicValueField,
  MultiSelectField,
  NumberField,
  RadioField,
  SelectField,
  SelectWithAddNewField,
  SwitchField,
  TablePickerField,
  TextareaField,
  TextField,
  UrlField,
  ValueTypeField,
} from "./fields";
import { createCollectionFieldValidators } from "./fields/collection-field-utils";
import type { FormBuilderFormInstance } from "./hooks/use-form-builder";
import type {
  AnyFieldDefinition,
  CollectionFieldDefinition,
  DynamicValueFieldDefinition,
  FieldValues,
  FormConfigContext,
  FormFieldApi,
  FormSectionDefinition,
  Path,
  TablePickerFieldDefinition,
} from "./types";

const DEFAULT_FORM_SECTION_ID = "__default";
const UNGROUPED_FORM_SECTION_ID = "__ungrouped";

interface FormBuilderProps<TFieldValues extends FieldValues> {
  actions?: ReactNode;
  context?: FormConfigContext;
  asFieldset?: boolean;
  className?: string;
  disabled?: boolean;
  fields: AnyFieldDefinition<TFieldValues>[];
  form: FormBuilderFormInstance<TFieldValues>;
  isSubmitting?: boolean;
  sections?: FormSectionDefinition<TFieldValues>[];
  submitText?: null | string;
}

export interface ResolvedFormBuilderSection<
  TFieldValues extends FieldValues = FieldValues,
> {
  description?: string;
  descriptionKey?: string;
  columns?: 1 | 2 | 3;
  fields: AnyFieldDefinition<TFieldValues>[];
  id: string;
  isDefault?: boolean;
  isUngrouped?: boolean;
  title?: string;
  titleKey?: string;
}

interface WindowWithDynamicUpdates extends Window {
  __dynamicFieldUpdates?: Map<string, { name: string; value: unknown }>;
}

export function resolveFormBuilderSections<
  TFieldValues extends FieldValues = FieldValues,
>(input: {
  fields: AnyFieldDefinition<TFieldValues>[];
  sections?: FormSectionDefinition<TFieldValues>[];
}): ResolvedFormBuilderSection<TFieldValues>[] {
  if (!input.sections?.length) {
    return [
      {
        fields: input.fields,
        id: DEFAULT_FORM_SECTION_ID,
        isDefault: true,
      },
    ];
  }

  const fieldsByName = new Map(
    input.fields.map((field) => [String(field.name), field] as const)
  );
  const groupedFieldNames = new Set<string>();
  const resolvedSections: ResolvedFormBuilderSection<TFieldValues>[] = [];

  for (const section of input.sections) {
    const sectionFields = section.fields
      .map((fieldName) => fieldsByName.get(String(fieldName)))
      .filter((field): field is AnyFieldDefinition<TFieldValues> =>
        Boolean(field)
      );
    if (sectionFields.length === 0) {
      continue;
    }

    for (const field of sectionFields) {
      groupedFieldNames.add(String(field.name));
    }

    resolvedSections.push({
      columns: section.columns,
      description: section.description,
      descriptionKey: section.descriptionKey,
      fields: sectionFields,
      id: section.id,
      title: section.title,
      titleKey: section.titleKey,
    });
  }

  const ungroupedFields = input.fields.filter(
    (field) => !groupedFieldNames.has(String(field.name))
  );
  if (ungroupedFields.length > 0) {
    resolvedSections.push({
      fields: ungroupedFields,
      id: UNGROUPED_FORM_SECTION_ID,
      isUngrouped: true,
    });
  }

  if (resolvedSections.length === 0) {
    return [
      {
        fields: input.fields,
        id: DEFAULT_FORM_SECTION_ID,
        isDefault: true,
      },
    ];
  }

  return resolvedSections;
}

function normalizeFieldApi<T>(field: {
  state: { value: T; meta: { errors: unknown[]; isValid: boolean } };
  handleChange: (value: T) => void;
  handleBlur: () => void;
  name: string;
}): FormFieldApi<T> {
  const errors = field.state.meta.errors;
  const errorStrings = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];
  return {
    handleBlur: field.handleBlur,
    handleChange: field.handleChange,
    name: field.name,
    state: {
      meta: { errors: errorStrings, isValid: field.state.meta.isValid },
      value: field.state.value,
    },
  };
}

function FormBuilderField<TFieldValues extends FieldValues>({
  context,
  field,
  form,
}: {
  context?: FormConfigContext;
  field: AnyFieldDefinition<TFieldValues>;
  form: FormBuilderFormInstance<TFieldValues>;
}) {
  switch (field.type) {
    case "checkbox":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => {
            const normalizedFieldApi = normalizeFieldApi(
              f
            ) as unknown as FormFieldApi<boolean>;
            if (field.variant === "checkbox") {
              return (
                <CheckboxField field={field} fieldApi={normalizedFieldApi} />
              );
            }
            return (
              <SwitchField
                field={{ ...field, variant: "switch" }}
                fieldApi={normalizedFieldApi}
              />
            );
          }}
        </form.Field>
      );
    case "collection": {
      const collectionValidators = createCollectionFieldValidators(field);

      return (
        <form.Field
          key={field.name}
          name={field.name as Path<TFieldValues>}
          validators={collectionValidators as never}
        >
          {(f) => (
            <CollectionField
              context={context}
              field={field as CollectionFieldDefinition<TFieldValues>}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<unknown>
              }
            />
          )}
        </form.Field>
      );
    }
    case "custom":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) =>
            field.renderField({
              field: normalizeFieldApi(f) as unknown as FormFieldApi<unknown>,
              form: {
                getFieldValue: (name) =>
                  form.getFieldValue(name as Path<TFieldValues>),
                setFieldValue: (name, value) =>
                  form.setFieldValue(
                    name as Path<TFieldValues>,
                    value as Parameters<
                      FormBuilderFormInstance<TFieldValues>["setFieldValue"]
                    >[1]
                  ),
              },
            })
          }
        </form.Field>
      );
    case "date":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <DateField
              field={field}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<
                  Date | string | null
                >
              }
            />
          )}
        </form.Field>
      );
    case "dynamic-value": {
      if (!("dependsOn" in field)) {
        return null;
      }
      const depField = field.dependsOn.field as Path<TFieldValues>;
      return (
        <form.Subscribe
          key={field.name}
          selector={(state) => state.values[depField]}
        >
          {(depValue: unknown) => {
            const transformed = field.dependsOn.transform(depValue);
            const type = transformed;
            if (
              typeof type !== "string" ||
              !["boolean", "json", "number", "string"].includes(type)
            ) {
              return null;
            }
            return (
              <form.Field name={field.name as Path<TFieldValues>}>
                {(f) => (
                  <DynamicValueField
                    field={field}
                    fieldApi={
                      normalizeFieldApi(f) as unknown as FormFieldApi<unknown>
                    }
                    type={type as "boolean" | "json" | "number" | "string"}
                  />
                )}
              </form.Field>
            );
          }}
        </form.Subscribe>
      );
    }
    case "number":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <NumberField
              field={
                field as AnyFieldDefinition<TFieldValues> & { type: "number" }
              }
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<number | string>
              }
            />
          )}
        </form.Field>
      );
    case "multiSelect":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <MultiSelectField
              field={field}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<
                  Array<number | string>
                >
              }
            />
          )}
        </form.Field>
      );
    case "radio":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <RadioField
              field={field}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<
                  string | number | boolean | null
                >
              }
            />
          )}
        </form.Field>
      );
    case "select":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <SelectField
              field={field}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<
                  string | number | boolean | null
                >
              }
            />
          )}
        </form.Field>
      );
    case "select-with-add-new":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <SelectWithAddNewField
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<string | null>
              }
              items={
                (Array.isArray(field.options) ? field.options : []).map((o) =>
                  String(o.value)
                ) ?? []
              }
              label={field.label}
              name={field.name as string}
              optionsLoader={field.optionsLoader}
              placeholder={field.placeholder}
            />
          )}
        </form.Field>
      );
    case "switch":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <SwitchField
              field={{ ...field, type: "checkbox", variant: "switch" }}
              fieldApi={
                normalizeFieldApi(f) as unknown as FormFieldApi<boolean>
              }
            />
          )}
        </form.Field>
      );
    case "tablePicker":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <TablePickerField
              context={
                (context ?? {
                  formType: "form",
                  mode: "create",
                  tableId: "form",
                  tableType: "form",
                }) as FormConfigContext<TFieldValues>
              }
              field={field as TablePickerFieldDefinition<TFieldValues>}
              fieldApi={normalizeFieldApi(f)}
            />
          )}
        </form.Field>
      );
    case "text":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <TextField
              field={field}
              fieldApi={normalizeFieldApi(f) as unknown as FormFieldApi<string>}
            />
          )}
        </form.Field>
      );
    case "textarea":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <TextareaField
              field={
                field as AnyFieldDefinition<TFieldValues> & {
                  type: "textarea";
                }
              }
              fieldApi={normalizeFieldApi(f) as unknown as FormFieldApi<string>}
            />
          )}
        </form.Field>
      );
    case "url":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <UrlField
              field={field}
              fieldApi={normalizeFieldApi(f) as unknown as FormFieldApi<string>}
            />
          )}
        </form.Field>
      );
    case "value-type":
      return (
        <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
          {(f) => (
            <form.Subscribe
              selector={(state) =>
                state.values[field.valueTypeField as Path<TFieldValues>]
              }
            >
              {(valueType: unknown) => (
                <ValueTypeField
                  description={field.description}
                  fieldApi={
                    normalizeFieldApi(f) as unknown as FormFieldApi<unknown>
                  }
                  label={field.label}
                  placeholder={field.placeholder}
                  valueType={
                    ((valueType as string) || "string") as
                      | "boolean"
                      | "json"
                      | "number"
                      | "string"
                  }
                />
              )}
            </form.Subscribe>
          )}
        </form.Field>
      );
    default:
      return null;
  }
}

export function FormBuilder<TFieldValues extends FieldValues>({
  actions,
  context,
  asFieldset = false,
  className,
  disabled = false,
  fields,
  form,
  isSubmitting = false,
  sections,
  submitText,
}: FormBuilderProps<TFieldValues>) {
  const { locale, t, translations } = useTranslations();
  const values = useStore(form.store, (state) => state.values);
  const runtimeContext: FormConfigContext = {
    formType: "form",
    tableId: "form",
    tableType: "form",
    mode: "create",
    locale,
    translations,
    ...context,
    values,
    setFieldValue: (name, value) =>
      form.setFieldValue(name as Path<TFieldValues>, value as never),
  };
  const Root = asFieldset ? "fieldset" : "form";
  const resolvedSections = resolveFormBuilderSections({ fields, sections });

  useEffect(() => {
    const fieldsWithDeps = fields.filter(
      (f): f is DynamicValueFieldDefinition<TFieldValues> =>
        f.type === "dynamic-value" && "dependsOn" in f
    );
    if (fieldsWithDeps.length === 0) {
      return;
    }

    const shouldTransform = (fieldName: string, fieldType: string) => {
      const isValueField = fieldName === "value";
      const isDynamic = fieldType === "dynamic-value";
      return !(isDynamic || isValueField);
    };

    for (const field of fieldsWithDeps) {
      const depField = field.dependsOn.field as Path<TFieldValues>;
      const currentVal = form.getFieldValue(depField);
      if (
        currentVal != null &&
        shouldTransform(field.name as string, field.type)
      ) {
        const transformed = field.dependsOn.transform(currentVal);
        if (typeof transformed === "string") {
          form.setFieldValue(
            field.name as Path<TFieldValues>,
            transformed as Parameters<
              FormBuilderFormInstance<TFieldValues>["setFieldValue"]
            >[1]
          );
        }
      }
    }
  }, [form, fields]);

  useEffect(() => {
    const win = window as WindowWithDynamicUpdates;
    const updates = win.__dynamicFieldUpdates;
    if (updates?.size) {
      for (const update of updates.values()) {
        try {
          form.setFieldValue(
            update.name as Path<TFieldValues>,
            update.value as Parameters<
              FormBuilderFormInstance<TFieldValues>["setFieldValue"]
            >[1]
          );
        } catch {
          // ignore
        }
      }
      updates.clear();
    }
  });

  return (
    <Root
      className={className}
      onSubmit={(e) => {
        e.preventDefault();
        e.stopPropagation();
        form.handleSubmit();
      }}
    >
      <div className="space-y-5">
        {resolvedSections.map((section) => {
          const title = section.titleKey ? t(section.titleKey) : section.title;
          const description = section.descriptionKey
            ? t(section.descriptionKey)
            : section.description;
          const hasHeader = Boolean(title || description);
          const sectionClassName =
            section.isDefault || section.isUngrouped
              ? "space-y-4"
              : "space-y-4 rounded-md border p-4";

          return (
            <section className={sectionClassName} key={section.id}>
              {hasHeader && (
                <div className="space-y-1">
                  {title && <h3 className="font-medium text-sm">{title}</h3>}
                  {description && (
                    <p className="text-muted-foreground text-sm">
                      {description}
                    </p>
                  )}
                </div>
              )}
              <div
                className="grid gap-4"
                style={{
                  gridTemplateColumns: `repeat(${section.columns ?? 1}, minmax(0, 1fr))`,
                }}
              >
                {section.fields.map((field) => (
                  <div key={String(field.name)}>
                    <RuntimeField
                      context={runtimeContext}
                      field={field as AnyFieldDefinition}
                      value={values[field.name]}
                    >
                      {(resolved) => (
                        <FormBuilderField
                          context={runtimeContext}
                          field={resolved as AnyFieldDefinition<TFieldValues>}
                          form={form}
                        />
                      )}
                    </RuntimeField>
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>
      <form.Subscribe selector={(state) => state.errors}>
        {(errors) =>
          errors.length > 0 && (
            <div className="mt-3 text-destructive text-sm" role="alert">
              {errors
                .filter((error): error is string => typeof error === "string")
                .join("; ")}
            </div>
          )
        }
      </form.Subscribe>
      {submitText != null && (
        <div className="mt-6 flex items-center justify-between">
          <div className="flex items-center gap-4">{actions}</div>
          {submitText && (
            <Button disabled={disabled || isSubmitting} type="submit">
              {t(submitText)}
            </Button>
          )}
        </div>
      )}
    </Root>
  );
}

import type {
  AnyFieldDefinition,
  FieldValues,
  FormConfig,
  FormConfigContext,
  FormSectionDefinition,
} from "./types";

/** Clone editable data without sharing nested values with a row or configuration. */
export const cloneFormValue = <T>(value: T): T => {
  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }
  if (Array.isArray(value)) {
    return value.map(cloneFormValue) as T;
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, cloneFormValue(item)])
    ) as T;
  }
  return value;
};

export const formValuesEqual = (left: unknown, right: unknown): boolean => {
  if (Object.is(left, right)) {
    return true;
  }
  if (left instanceof Date || right instanceof Date) {
    return (
      left instanceof Date &&
      right instanceof Date &&
      left.getTime() === right.getTime()
    );
  }
  if (
    !(left && right) ||
    typeof left !== "object" ||
    typeof right !== "object"
  ) {
    return false;
  }
  if (Array.isArray(left) !== Array.isArray(right)) {
    return false;
  }
  const a = Object.entries(left);
  const b = Object.entries(right);
  return (
    a.length === b.length &&
    a.every(
      ([key, value]) =>
        Object.hasOwn(right, key) &&
        formValuesEqual(value, (right as FieldValues)[key])
    )
  );
};

export const fieldIsHidden = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): boolean =>
  Boolean(
    typeof field.hidden === "function" ? field.hidden(context) : field.hidden
  );

export const fieldIsDisabled = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): boolean =>
  Boolean(
    typeof field.disabled === "function"
      ? field.disabled(context)
      : field.disabled
  );

export const defaultFieldValue = (field: AnyFieldDefinition): unknown => {
  if (field.defaultValue !== undefined) {
    return cloneFormValue(field.defaultValue);
  }
  if (field.type === "collection" || field.type === "multiSelect") {
    return [];
  }
  if (field.type === "switch" || field.type === "checkbox") {
    return false;
  }
  return "";
};

export const initialFormValues = (
  config: FormConfig,
  row?: FieldValues
): FieldValues =>
  cloneFormValue({
    ...Object.fromEntries(
      config.fields.map((field) => [field.name, defaultFieldValue(field)])
    ),
    ...config.defaultValues,
    ...row,
  });

export const resolveFormSections = (
  config: FormConfig
): FormSectionDefinition[] => {
  const remaining = new Set(config.fields.map((field) => field.name));
  const sections: FormSectionDefinition[] = [];
  for (const section of config.sections ?? []) {
    const fields = section.fields.filter((name) => remaining.delete(name));
    if (fields.length) {
      sections.push({ ...section, fields });
    }
  }
  if (remaining.size) {
    let id = "__ungrouped";
    while (sections.some((section) => section.id === id)) {
      id += "_";
    }
    sections.push({ id, fields: [...remaining] });
  }
  return sections;
};

export const translateFormConfig = (config: FormConfig): FormConfig => {
  const keys = config.translations?.keys ?? {};
  const translate = (key: string | undefined, fallback: string | undefined) =>
    key ? (keys[key] ?? fallback) : fallback;
  const field = (value: AnyFieldDefinition): AnyFieldDefinition => ({
    ...value,
    label: translate(value.labelKey, value.label) ?? value.name,
    labelKey:
      value.labelKey && keys[value.labelKey] !== undefined
        ? undefined
        : value.labelKey,
    placeholderKey:
      value.placeholderKey && keys[value.placeholderKey] !== undefined
        ? undefined
        : value.placeholderKey,
    descriptionKey:
      value.descriptionKey && keys[value.descriptionKey] !== undefined
        ? undefined
        : value.descriptionKey,
    description: translate(value.descriptionKey, value.description),
    placeholder: translate(value.placeholderKey, value.placeholder),
    itemFields: value.itemFields?.map(field),
    options: Array.isArray(value.options)
      ? value.options.map((option, index) => ({
          ...option,
          label:
            translate(
              "optionKeys" in value ? value.optionKeys?.[index] : undefined,
              option.label
            ) ?? option.label,
        }))
      : value.options,
  });
  return {
    ...config,
    fields: config.fields.map(field),
    sections: config.sections?.map((section) => ({
      ...section,
      title: translate(section.titleKey, section.title),
      titleKey:
        section.titleKey && keys[section.titleKey] !== undefined
          ? undefined
          : section.titleKey,
      descriptionKey:
        section.descriptionKey && keys[section.descriptionKey] !== undefined
          ? undefined
          : section.descriptionKey,
      description: translate(section.descriptionKey, section.description),
    })),
  };
};

export interface FormValidationResult {
  values: FieldValues;
  errors: Record<string, string>;
}

const missing = (value: unknown): boolean =>
  value === "" ||
  value === null ||
  value === undefined ||
  (Array.isArray(value) && value.length === 0);

export const dynamicFieldType = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): "boolean" | "json" | "number" | "string" => {
  if (!["dynamic-value", "value-type"].includes(field.type)) {
    return "string";
  }
  const raw =
    field.type === "value-type"
      ? context.values?.[field.valueTypeField ?? ""]
      : field.dependsOn?.transform(context.values?.[field.dependsOn.field]);
  const candidate = String(raw ?? "string") as
    | "boolean"
    | "json"
    | "number"
    | "string";
  return (
    field.supportedTypes ?? ["boolean", "json", "number", "string"]
  ).includes(candidate)
    ? candidate
    : "string";
};

const validateScalar = (
  field: AnyFieldDefinition,
  value: unknown,
  context: FormConfigContext
): string | undefined => {
  if (field.required && missing(value)) {
    return `${field.label} is required`;
  }
  const numeric =
    field.type === "number" || dynamicFieldType(field, context) === "number";
  if (
    numeric &&
    !missing(value) &&
    (typeof value !== "number" || !Number.isFinite(value))
  ) {
    return `Invalid ${field.label}`;
  }
  if (numeric && typeof value === "number") {
    if (field.min !== undefined && value < field.min) {
      return `${field.label} must be at least ${field.min}`;
    }
    if (field.max !== undefined && value > field.max) {
      return `${field.label} must be at most ${field.max}`;
    }
  }
  return undefined;
};

const validateCollection = async (
  field: AnyFieldDefinition,
  value: unknown[],
  context: FormConfigContext
): Promise<FormValidationResult> => {
  const items: FieldValues[] = [];
  const errors: Record<string, string> = {};
  for (const [index, item] of value.entries()) {
    const path = `${field.name}.${index}`;
    if (!item || typeof item !== "object" || Array.isArray(item)) {
      errors[path] = "Invalid item";
      continue;
    }
    const child = await validateFormFields(
      field.itemFields ?? [],
      item as FieldValues,
      { ...context, values: item as FieldValues }
    );
    items.push(child.values);
    for (const [name, message] of Object.entries(child.errors)) {
      errors[`${path}.${name}`] = message;
    }
    const issues = field.validateItem?.(child.values, index) ?? [];
    if (issues.length) {
      errors[path] = issues.join("; ");
    }
  }
  const issues = field.validateItems?.(items) ?? [];
  if (issues.length) {
    errors[field.name] = issues.join("; ");
  }
  return { values: { [field.name]: items }, errors };
};

const validateField = async (
  field: AnyFieldDefinition,
  value: unknown,
  context: FormConfigContext
): Promise<FormValidationResult> => {
  const values = { [field.name]: value };
  const errors: Record<string, string> = {};
  const scalarError = validateScalar(field, value, context);
  if (scalarError) {
    return { values, errors: { [field.name]: scalarError } };
  }
  if (field.type === "collection" && Array.isArray(value)) {
    const result = await validateCollection(field, value, context);
    Object.assign(values, result.values);
    Object.assign(errors, result.errors);
  }
  if (field.schema) {
    const result = await field.schema.safeParseAsync(values[field.name]);
    if (result.success) {
      values[field.name] = result.data;
    } else {
      for (const issue of result.error.issues) {
        errors[[field.name, ...issue.path].join(".")] = issue.message;
      }
    }
  }
  return { values, errors };
};

export const validateFormFields = async (
  fields: AnyFieldDefinition[],
  values: FieldValues,
  context: FormConfigContext
): Promise<FormValidationResult> => {
  const output = cloneFormValue(values);
  const errors: Record<string, string> = {};
  for (const field of fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      continue;
    }
    const result = await validateField(field, output[field.name], context);
    Object.assign(output, result.values);
    Object.assign(errors, result.errors);
  }
  return { values: output, errors };
};

export const validateForm = async (
  config: FormConfig,
  values: FieldValues,
  context: FormConfigContext
): Promise<FormValidationResult> => {
  const result = await validateFormFields(config.fields, values, context);
  if (!Object.keys(result.errors).length && config.schema) {
    const parsed = await config.schema.safeParseAsync(result.values);
    if (parsed.success) {
      if (
        parsed.data &&
        typeof parsed.data === "object" &&
        !Array.isArray(parsed.data)
      ) {
        result.values = parsed.data as FieldValues;
      } else {
        result.errors.form = "The form schema must return an object";
      }
    } else {
      for (const issue of parsed.error.issues) {
        result.errors[issue.path.join(".") || "form"] = issue.message;
      }
    }
  }
  return result;
};

export const formSubmissionValues = (
  config: FormConfig,
  values: FieldValues,
  initial: FieldValues,
  context: FormConfigContext
): FieldValues => {
  const output =
    config.submitMode === "patch" && context.mode === "edit"
      ? Object.fromEntries(
          config.fields
            .filter(
              (field) =>
                !formValuesEqual(values[field.name], initial[field.name])
            )
            .map((field) => [field.name, values[field.name]])
        )
      : cloneFormValue(values);
  for (const field of config.fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      delete output[field.name];
    }
  }
  return output;
};

import type { AnyFieldDefinition, FormConfig, FormSelectOption } from "./types";

/** A catalogue may override any generated field with validation or a custom renderer. */
export function generateFormConfig(
  id: string,
  columns: Array<{
    id: string;
    header: string;
    type?: string;
    accessorKey?: unknown;
    options?: unknown;
  }>
): FormConfig {
  const fields: AnyFieldDefinition[] = columns
    .filter(
      (column) =>
        !["select", "actions"].includes(column.id) && column.type !== "actions"
    )
    .map((column) => {
      const name =
        typeof column.accessorKey === "string" ? column.accessorKey : column.id;
      const base = { name, label: column.header };
      switch (column.type) {
        case "boolean":
          return { ...base, type: "switch" };
        case "date":
          return { ...base, type: "date" };
        case "number":
          return { ...base, type: "number" };
        case "url":
          return { ...base, type: "url" };
        case "select":
        case "multiSelect":
          return {
            ...base,
            type: column.type,
            options: Array.isArray(column.options)
              ? (column.options as FormSelectOption[])
              : [],
          };
        default:
          return { ...base, type: "text" };
      }
    });
  return { id, fields, defaultValues: {} };
}

