export function LazyCatalogueFormContainer(props: Record<string, unknown>) {
  return (
    <Suspense fallback={<ContainerSkeleton />}>
      <CatalogueFormContainer {...props} />
    </Suspense>
  );
}

/**
 * Form field types and interfaces
 * This file defines the types used for the form builder system
 */
import type { ReactNode } from "react";
import type { z } from "zod";
import type { TableConfig } from "../../config/helpers";
import type { TableActions } from "../../providers/table-provider";
import type { DataTableTranslations } from "../../types/translations";
import type { TableView } from "../../types/view-types";

/** Form values type (generic record) */
export type FieldValues = Record<string, unknown>;

/** Field path (dot-notation string for nested fields) */
export type Path<T extends FieldValues> = keyof T extends string
  ? keyof T
  : string;

export type FormConfigMode = "create" | "edit";

export interface FormConfigContext<
  TFieldValues extends FieldValues = FieldValues,
  TRowData extends Record<string, unknown> = Record<string, unknown>,
> {
  bulkEdit?: {
    ids: readonly string[];
    rows: readonly Record<string, unknown>[];
    fields: readonly string[];
  };
  setFieldValue?: (name: string, value: unknown) => void;
  touchField?: (name: string) => void;
  formType: string;
  initialData?: Partial<TFieldValues>;
  mode: FormConfigMode;
  row?: TRowData;
  tableId: string;
  tableType: string;
  values?: Partial<TFieldValues>;
  locale?: string;
  translations?: DataTableTranslations;
}

/**
 * Minimal field API shape passed from TanStack Form's form.Field children.
 * Used by field components to avoid depending on @tanstack/react-form in types.
 */
export interface FormFieldApi<TValue = unknown> {
  handleBlur: () => void;
  handleChange(value: TValue): void;
  name: string;
  state: {
    meta: { errors: string[]; isValid: boolean };
    value: TValue;
  };
}

/**
 * Declarative form section that groups existing fields for clearer admin forms.
 */
export interface FormSectionDefinition<
  TFieldValues extends FieldValues = FieldValues,
> {
  description?: string;
  descriptionKey?: string;
  columns?: 1 | 2 | 3;
  fields: Path<TFieldValues>[];
  id: string;
  title?: string;
  titleKey?: string;
}

/**
 * Union type of all possible field definitions
 */
export type AnyFieldDefinition<TFieldValues extends FieldValues = FieldValues> =
  | CheckboxFieldDefinition<TFieldValues>
  | CollectionFieldDefinition<TFieldValues>
  | CustomFieldDefinition<TFieldValues>
  | DateFieldDefinition<TFieldValues>
  | DynamicValueFieldDefinition<TFieldValues>
  | MultiSelectFieldDefinition<TFieldValues>
  | NumberFieldDefinition<TFieldValues>
  | RadioFieldDefinition<TFieldValues>
  | SelectFieldDefinition<TFieldValues>
  | SelectWithAddNewFieldDefinition<TFieldValues>
  | SwitchFieldDefinition<TFieldValues>
  | TablePickerFieldDefinition<TFieldValues>
  | TextareaFieldDefinition<TFieldValues>
  | TextFieldDefinition<TFieldValues>
  | UrlFieldDefinition<TFieldValues>
  | ValueTypeFieldDefinition<TFieldValues>;

export interface FormSelectOption {
  label: string;
  value: boolean | number | string;
  disabled?: boolean;
  color?: string;
}
export type FormOptions =
  | FormSelectOption[]
  | ((
      context: FormConfigContext
    ) => FormSelectOption[] | Promise<FormSelectOption[]>);

/**
 * Base field definition that all fields extend
 */
export interface BaseFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> {
  description?: string;
  descriptionKey?: string;
  disabled?: boolean | ((context: FormConfigContext) => boolean);
  hidden?: boolean | ((context: FormConfigContext) => boolean);
  bulkEdit?: boolean;
  defaultValue?: unknown;
  schema?: z.ZodType;
  options?: FormOptions;
  optionDependencies?: string[];
  optionsScope?: string | number;
  searchOptions?: (
    query: string,
    context: FormConfigContext,
    signal: AbortSignal
  ) => FormSelectOption[] | Promise<FormSelectOption[]>;
  resolveOptions?: (
    values: unknown[],
    context: FormConfigContext,
    signal: AbortSignal
  ) => FormSelectOption[] | Promise<FormSelectOption[]>;
  createOption?: (
    label: string,
    context: FormConfigContext,
    signal: AbortSignal
  ) => FormSelectOption | Promise<FormSelectOption>;
  searchMinLength?: number;
  searchDebounceMs?: number;
  itemFields?: AnyFieldDefinition[];
  validateItem?: (item: FieldValues, index: number | null) => string[];
  validateItems?: (items: readonly FieldValues[]) => string[];
  min?: number;
  max?: number;
  valueTypeField?: string;
  supportedTypes?: Array<"boolean" | "json" | "number" | "string">;
  dependsOn?: { field: string; transform: (value: unknown) => unknown };
  label: string;
  labelKey?: string;
  name: Path<TFieldValues>;
  placeholder?: string;
  placeholderKey?: string;
  required?: boolean;
  translationConfig?: {
    namespace: string;
  };
}

/**
 * Props that custom/render field components receive (TanStack Form field API)
 */
export interface BaseFieldProps<
  _TFieldValues extends FieldValues = FieldValues,
> {
  field: FormFieldApi<unknown>;
  form: {
    getFieldValue: (name: string) => unknown;
    setFieldValue: (name: string, value: unknown) => void;
  };
}

/**
 * Checkbox field
 */
export interface CheckboxFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  type: "checkbox";
  variant?: "checkbox" | "switch";
}

export type CollectionFieldItem = Record<string, unknown>;

export interface CollectionFieldColumnDefinition {
  header: string;
  id: string;
  render?: (item: CollectionFieldItem, index: number) => ReactNode;
}

export interface CollectionFieldCreateAction {
  createItem: (items: readonly CollectionFieldItem[]) => CollectionFieldItem;
  id?: string;
  label: string;
}

export interface CollectionFieldActionLabels {
  actions: string;
  addTitle: string;
  cancel: string;
  deleteItem: string;
  editItem: string;
  editTitle: string;
  moveDown: string;
  moveUp: string;
  save: string;
}

/**
 * Collection field for editing array-like values with add/edit/delete/reorder
 * controls. The form value remains the source of truth.
 */
export interface CollectionFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  addLabel?: string;
  columns?: CollectionFieldColumnDefinition[];
  collectionMode?: "inline" | "dialog";
  createActions?: CollectionFieldCreateAction[];
  createItem?: (items: readonly CollectionFieldItem[]) => CollectionFieldItem;
  emptyLabel?: string;
  getItemKey?: (item: CollectionFieldItem, index: number) => string;
  itemLabel?: string;
  labelKeys?: Partial<Record<keyof CollectionFieldActionLabels, string>>;
  labels?: Partial<CollectionFieldActionLabels>;
  renderItemForm?: (props: {
    disabled?: boolean;
    index: number | null;
    item: CollectionFieldItem;
    onChange: (item: CollectionFieldItem) => void;
  }) => ReactNode;
  type: "collection";
  validateItem?: (item: CollectionFieldItem, index: number | null) => string[];
  validateItems?: (items: readonly CollectionFieldItem[]) => string[];
}

/**
 * Custom field for special cases
 */
export interface CustomFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  renderField: (props: BaseFieldProps<TFieldValues>) => ReactNode;
  type: "custom";
}

/**
 * Date field using a native date input for predictable serialized values.
 */
export interface DateFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  format?: string;
  maxDate?: Date | string;
  minDate?: Date | string;
  type: "date";
}

/**
 * Dynamic value field that changes based on another field
 */
export interface DynamicValueFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  dependsOn: {
    field: Path<TFieldValues>;
    transform: (value: unknown) => unknown;
  };
  type: "dynamic-value";
}

export type FieldDefinition =
  | CheckboxFieldDefinition
  | CollectionFieldDefinition
  | DateFieldDefinition
  | DynamicValueFieldDefinition
  | MultiSelectFieldDefinition
  | NumberFieldDefinition
  | RadioFieldDefinition
  | SelectFieldDefinition
  | SelectWithAddNewFieldDefinition
  | TextFieldDefinition
  | ValueTypeFieldDefinition;

/**
 * All possible field types
 */
export type FieldType = AnyFieldDefinition["type"];

/**
 * Form configuration
 */
export interface FormConfig<TFieldValues extends FieldValues = FieldValues> {
  defaultValues?: Partial<TFieldValues>;
  title?: string | ((mode: FormConfigMode, row?: FieldValues) => string);
  description?: string;
  presentation?: "drawer" | "modal";
  width?: string;
  submitLabel?: string;
  cancelLabel?: string;
  submitMode?: "full" | "patch";
  loadInitialValues?: (
    row: FieldValues | undefined,
    context: FormConfigContext,
    signal: AbortSignal
  ) => FieldValues | Promise<FieldValues>;
  transform?: (
    values: FieldValues,
    context: FormConfigContext
  ) => FieldValues | Promise<FieldValues>;
  fields: AnyFieldDefinition<TFieldValues>[];
  id: string;
  schema?: z.ZodType<TFieldValues>;
  sections?: FormSectionDefinition<TFieldValues>[];
  translations?: {
    keys: {
      [key: string]: string;
    };
    namespace: string;
  };
}

/**
 * Number field with min/max constraints
 */
export interface NumberFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  max?: number;
  min?: number;
  step?: number;
  type: "number";
}

/**
 * Radio group field for single-choice enum values.
 */
export interface RadioFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  optionKeys?: string[];
  options?: FormOptions;
  type: "radio";
}

/**
 * Basic select field
 */
export interface SelectFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  optionKeys?: string[];
  options?: FormOptions;
  type: "select";
}

/**
 * Multi-select field for editing array values from a finite option set.
 */
export interface MultiSelectFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  optionKeys?: string[];
  options?: FormOptions;
  type: "multiSelect";
}

/**
 * Select field with ability to add new options
 */
export interface SelectWithAddNewFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  onAddNew?: () => void;
  optionKeys?: string[];
  options?: FormOptions;
  optionsLoader?: () => Promise<string[]>;
  type: "select-with-add-new";
}

/**
 * Switch field (special case of checkbox)
 */
export interface SwitchFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  type: "switch";
}

export interface TablePickerFieldConfig<
  TRow extends Record<string, unknown> = Record<string, unknown>,
  TFieldValues extends FieldValues = FieldValues,
> {
  /** Optional server and saved-view contracts for the nested table. */
  actions?:
    | TableActions
    | ((context: FormConfigContext<TFieldValues>) => TableActions | undefined);
  /** A complete table catalogue, optionally derived from the current form. */
  config:
    | TableConfig
    | ((context: FormConfigContext<TFieldValues>) => TableConfig);
  /** Optional local rows, optionally derived from the current form. */
  data?: TRow[] | ((context: FormConfigContext<TFieldValues>) => TRow[]);
  /** Convert a table row to the stable string ID used by table selection. */
  getRowId?: (row: TRow) => string;
  initialActiveViewId?: string;
  initialViews?: TableView[];
  locale?: string;
  /** Limit the scrolling table body height. */
  maxHeight?: string;
  /** Allow several selected values. Defaults to true. */
  multiple?: boolean;
  /** Convert a selected row ID to the value stored in the form. */
  parseValue?: (id: string) => unknown;
  /** Toggle a row when its non-interactive area is clicked. Defaults to true. */
  selectOnRowClick?: boolean;
  /** Keep nested table state in the URL. Defaults to false for form fields. */
  syncUrl?: boolean;
  /** The nested table catalogue identifier. */
  tableType: string;
  translations?: DataTableTranslations;
}

export interface TablePickerFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  tablePicker: TablePickerFieldConfig<Record<string, unknown>, TFieldValues>;
  type: "tablePicker";
}

/**
 * Textarea field for multiline input
 */
export interface TextareaFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  rows?: number;
  type: "textarea";
}

/**
 * Text field for single line input
 */
export interface TextFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  inputType?: "email" | "password" | "tel" | "text" | "url";
  type: "text";
}

/**
 * URL field with optional Open Graph meta preview
 */
export interface UrlFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  showMetaPreview?: boolean;
  type: "url";
}

/**
 * Value type field that renders different inputs based on value type
 */
export interface ValueTypeFieldDefinition<
  TFieldValues extends FieldValues = FieldValues,
> extends BaseFieldDefinition<TFieldValues> {
  supportedTypes?: Array<"boolean" | "json" | "number" | "string">;
  type: "value-type";
  valueTypeField: Path<TFieldValues>;
}

"use client";

import { ExternalLink, ImageIcon, Pencil } from "lucide-react";
import { type MouseEvent, type ReactNode, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { TableCatalogueColumnConfig } from "../hooks/use-table-config";
import type { Row, Table as TanStackTable } from "../tanstack";
import { flexRender } from "../tanstack";
import type { TableGalleryConfig } from "../types/display-types";
import { shouldActivateCardFromKeyboard } from "../utils/card-interaction";
import {
  getCompactCardPropertiesClassName,
  getCompactCardPropertyClassName,
} from "../utils/card-properties";
import {
  getImageFallbackInitial,
  resolveImageSource,
} from "../utils/image-source";

const SYSTEM_COLUMN_IDS = new Set(["actions", "select"]);
const EMPTY_GROUP_VALUE = "";
const EMPTY_GROUP_LABEL = "No value";

const GALLERY_ASPECT_RATIO_CLASS = {
  portrait: "aspect-[3/4]",
  square: "aspect-square",
  video: "aspect-video",
  wide: "aspect-[16/10]",
} as const;

const GALLERY_CARD_SIZE_CLASS = {
  large: "grid-cols-[repeat(auto-fill,minmax(22rem,1fr))]",
  medium: "grid-cols-[repeat(auto-fill,minmax(16rem,1fr))]",
  small: "grid-cols-[repeat(auto-fill,minmax(12rem,1fr))]",
} as const;

const GALLERY_IMAGE_FIT_CLASS = {
  contain: "object-contain",
  cover: "object-cover",
} as const;

interface DataTableGalleryViewProps<TData extends Record<string, unknown>> {
  canEditRow?: (row: Row<TData>) => boolean;
  className?: string;
  columnDefinitions: TableCatalogueColumnConfig[];
  config?: TableGalleryConfig;
  editRowLabel?: string;
  emptyState: ReactNode;
  getRowLinkUrl?: (row: Row<TData>) => string | undefined;
  groupBy?: string;
  groupLabel?: string;
  isRowActive?: (row: Row<TData>) => boolean;
  isRowClickable?: (row: Row<TData>) => boolean;
  linkRowLabel?: string;
  onEditRow?: (row: Row<TData>, event: MouseEvent<HTMLButtonElement>) => void;
  onOpenRowLink?: (
    row: Row<TData>,
    event: MouseEvent<HTMLButtonElement>
  ) => void;
  onRowClick?: (row: Row<TData>, event: MouseEvent<HTMLElement>) => void;
  table: TanStackTable<TData>;
}

interface GalleryCardProps<TData extends Record<string, unknown>> {
  actionsCell?: ReturnType<Row<TData>["getVisibleCells"]>[number];
  aspectRatio: NonNullable<TableGalleryConfig["aspectRatio"]>;
  canEditRow: boolean;
  editRowLabel: string;
  imageColumnId?: string;
  imageFit: NonNullable<TableGalleryConfig["imageFit"]>;
  isActive: boolean;
  isClickable: boolean;
  linkRowLabel: string;
  linkUrl?: string;
  onEditRow?: (row: Row<TData>, event: MouseEvent<HTMLButtonElement>) => void;
  onOpenRowLink?: (
    row: Row<TData>,
    event: MouseEvent<HTMLButtonElement>
  ) => void;
  onRowClick?: (row: Row<TData>, event: MouseEvent<HTMLElement>) => void;
  propertyCells: ReturnType<Row<TData>["getVisibleCells"]>;
  propertyLabels: Map<string, string>;
  row: Row<TData>;
  selectionCell?: ReturnType<Row<TData>["getVisibleCells"]>[number];
  showCardLabels: boolean;
  titleCell?: ReturnType<Row<TData>["getVisibleCells"]>[number];
  titleColumnId?: string;
}

interface GalleryCardPropertiesProps<TData extends Record<string, unknown>> {
  propertyCells: ReturnType<Row<TData>["getVisibleCells"]>;
  propertyLabels: Map<string, string>;
  showCardLabels: boolean;
}

export interface GalleryGroup<TData extends Record<string, unknown>> {
  id: string;
  label: string;
  rows: Row<TData>[];
  value: string;
}

export function resolveGalleryDisplayConfig(
  config: TableGalleryConfig | undefined
): Required<
  Pick<
    TableGalleryConfig,
    "aspectRatio" | "cardSize" | "imageFit" | "showCardLabels"
  >
> &
  Omit<
    TableGalleryConfig,
    "aspectRatio" | "cardSize" | "imageFit" | "showCardLabels"
  > {
  return {
    ...config,
    aspectRatio: config?.aspectRatio ?? "wide",
    cardSize: config?.cardSize ?? "medium",
    imageFit: config?.imageFit ?? "cover",
    showCardLabels: config?.showCardLabels === true,
  };
}

export function shouldShowGalleryCardLabels(
  config: TableGalleryConfig | undefined
): boolean {
  return config?.showCardLabels === true;
}

export function resolveGalleryImageColumnId({
  columnDefinitions,
  config,
}: {
  columnDefinitions: TableCatalogueColumnConfig[];
  config: TableGalleryConfig | undefined;
}): string | undefined {
  if (config?.imageColumn) {
    return config.imageColumn;
  }

  return columnDefinitions.find((column) => column.type === "image")?.id;
}

export function resolveGalleryTitleColumnId({
  columnDefinitions,
  config,
}: {
  columnDefinitions: TableCatalogueColumnConfig[];
  config: TableGalleryConfig | undefined;
}): string | undefined {
  if (config?.titleColumn) {
    return config.titleColumn;
  }

  return columnDefinitions.find((column) => {
    return column.type !== "image" && !SYSTEM_COLUMN_IDS.has(column.id);
  })?.id;
}

export function resolveGalleryLinkColumnId({
  columnDefinitions,
}: {
  columnDefinitions: TableCatalogueColumnConfig[];
}): string | undefined {
  const rowLinkColumn = columnDefinitions.find(
    (column) => column.type === "url" && column.urlDisplayMode === "row-link"
  );

  return (
    rowLinkColumn?.id ??
    columnDefinitions.find((column) => column.type === "url")?.id
  );
}

export function resolveGalleryLinkUrl(value: unknown): string | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }

  const url = String(value);

  try {
    const parsed = new URL(url);
    if (parsed.protocol === "http:" || parsed.protocol === "https:") {
      return url;
    }
  } catch {
    return;
  }
}

export function resolveGalleryPropertyColumnIds({
  columnDefinitions,
  config,
  imageColumnId,
  titleColumnId,
}: {
  columnDefinitions: TableCatalogueColumnConfig[];
  config: TableGalleryConfig | undefined;
  imageColumnId?: string;
  titleColumnId?: string;
}): string[] {
  const availableColumnIds = columnDefinitions
    .filter((column) => {
      return (
        !SYSTEM_COLUMN_IDS.has(column.id) &&
        column.id !== titleColumnId &&
        column.id !== imageColumnId
      );
    })
    .map((column) => column.id);

  if (config?.cardColumnIds === undefined) {
    return availableColumnIds;
  }

  const availableColumnIdSet = new Set(availableColumnIds);
  return config.cardColumnIds.filter((columnId) =>
    availableColumnIdSet.has(columnId)
  );
}

function getStringValue(value: unknown): string {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

function getGalleryGroupValue(value: unknown): string {
  if (value === null || value === undefined) {
    return EMPTY_GROUP_VALUE;
  }

  return String(value);
}

export function createGalleryGroups<TData extends Record<string, unknown>>({
  groupBy,
  rows,
}: {
  groupBy: string;
  rows: Row<TData>[];
}): GalleryGroup<TData>[] {
  if (!groupBy) {
    return [
      {
        id: "gallery-group-all",
        label: "",
        rows,
        value: "",
      },
    ];
  }

  const groups: GalleryGroup<TData>[] = [];
  const groupByValue = new Map<string, GalleryGroup<TData>>();

  for (const row of rows) {
    const value = getGalleryGroupValue(row.original[groupBy]);
    const existingGroup = groupByValue.get(value);
    if (existingGroup) {
      existingGroup.rows.push(row);
      continue;
    }

    const group = {
      id: `gallery-group-${value || "empty"}`,
      label: value || EMPTY_GROUP_LABEL,
      rows: [row],
      value,
    };
    groupByValue.set(value, group);
    groups.push(group);
  }

  return groups;
}

function getColumnLabel(
  columnDefinitions: TableCatalogueColumnConfig[],
  columnId: string
): string {
  return (
    columnDefinitions.find((definition) => definition.id === columnId)
      ?.header ?? columnId
  );
}

function getCellByColumnId<TData extends Record<string, unknown>>(
  row: Row<TData>,
  columnId: string | undefined
): ReturnType<Row<TData>["getVisibleCells"]>[number] | undefined {
  if (!columnId) {
    return;
  }

  return row.getVisibleCells().find((cell) => cell.column.id === columnId);
}

function getGalleryPropertyCells<TData extends Record<string, unknown>>({
  cardColumnIds,
  groupBy,
  imageColumnId,
  row,
  titleColumnId,
}: {
  cardColumnIds?: string[];
  groupBy?: string;
  imageColumnId?: string;
  row: Row<TData>;
  titleColumnId?: string;
}): ReturnType<Row<TData>["getVisibleCells"]> {
  const cells = row.getVisibleCells().filter((cell) => {
    return (
      !SYSTEM_COLUMN_IDS.has(cell.column.id) &&
      cell.column.id !== titleColumnId &&
      cell.column.id !== imageColumnId &&
      cell.column.id !== groupBy
    );
  });

  if (cardColumnIds === undefined) {
    return cells;
  }

  const cellByColumnId = new Map(cells.map((cell) => [cell.column.id, cell]));
  return cardColumnIds
    .map((columnId) => cellByColumnId.get(columnId))
    .filter(Boolean) as ReturnType<Row<TData>["getVisibleCells"]>;
}

function getGalleryPropertyValueClassName(showCardLabels: boolean): string {
  if (showCardLabels) {
    return "min-w-0 truncate text-xs";
  }

  return "min-w-0 max-w-full truncate text-muted-foreground text-xs";
}

function GalleryCardProperties<TData extends Record<string, unknown>>({
  propertyCells,
  propertyLabels,
  showCardLabels,
}: GalleryCardPropertiesProps<TData>) {
  if (propertyCells.length === 0) {
    return null;
  }

  if (showCardLabels) {
    return (
      <dl className="mt-3 space-y-2">
        {propertyCells.map((cell) => (
          <div
            className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-2"
            key={cell.id}
          >
            <dt className="truncate text-muted-foreground text-xs">
              {propertyLabels.get(cell.column.id) ?? cell.column.id}
            </dt>
            <dd className={getGalleryPropertyValueClassName(showCardLabels)}>
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </dd>
          </div>
        ))}
      </dl>
    );
  }

  return (
    <div className={getCompactCardPropertiesClassName()}>
      {propertyCells.map((cell) => {
        const label = propertyLabels.get(cell.column.id) ?? cell.column.id;
        return (
          <div className={getCompactCardPropertyClassName()} key={cell.id}>
            <span className="sr-only">{label}: </span>
            <div className={getGalleryPropertyValueClassName(showCardLabels)}>
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function GalleryCardMedia({
  aspectRatio,
  imageFit,
  source,
  title,
}: {
  aspectRatio: NonNullable<TableGalleryConfig["aspectRatio"]>;
  imageFit: NonNullable<TableGalleryConfig["imageFit"]>;
  source?: string;
  title: string;
}) {
  const [hasError, setHasError] = useState(false);
  const resolvedSource = hasError ? undefined : source;
  const fallbackInitial = getImageFallbackInitial(title);

  return (
    <div
      className={cn(
        "relative overflow-hidden rounded-t-md bg-muted",
        GALLERY_ASPECT_RATIO_CLASS[aspectRatio]
      )}
    >
      {resolvedSource ? (
        // biome-ignore lint/performance/noImgElement: registry consumers should not need Next.js image domain configuration.
        // biome-ignore lint/a11y/noNoninteractiveElementInteractions: onError swaps broken media to the non-interactive fallback.
        <img
          alt={title}
          className={cn("h-full w-full", GALLERY_IMAGE_FIT_CLASS[imageFit])}
          height={400}
          loading="lazy"
          onError={() => setHasError(true)}
          src={resolvedSource}
          width={640}
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center bg-muted text-muted-foreground">
          <div className="flex flex-col items-center gap-2">
            <ImageIcon aria-hidden className="h-6 w-6" />
            <span className="font-medium text-lg">{fallbackInitial}</span>
          </div>
        </div>
      )}
    </div>
  );
}

function GalleryCardActions<TData extends Record<string, unknown>>({
  canEditRow,
  editRowLabel,
  linkRowLabel,
  linkUrl,
  onEditRow,
  onOpenRowLink,
  row,
}: {
  canEditRow: boolean;
  editRowLabel: string;
  linkRowLabel: string;
  linkUrl?: string;
  onEditRow?: (row: Row<TData>, event: MouseEvent<HTMLButtonElement>) => void;
  onOpenRowLink?: (
    row: Row<TData>,
    event: MouseEvent<HTMLButtonElement>
  ) => void;
  row: Row<TData>;
}) {
  const canOpenLink = Boolean(linkUrl && onOpenRowLink);
  const canEdit = canEditRow && Boolean(onEditRow);

  if (!(canOpenLink || canEdit)) {
    return null;
  }

  return (
    <div className="flex shrink-0 items-center gap-1">
      {canOpenLink ? (
        <Button
          aria-label={linkRowLabel}
          className="size-7 text-muted-foreground hover:text-foreground"
          onClick={(event) => {
            event.stopPropagation();
            onOpenRowLink?.(row, event);
          }}
          size="icon"
          title={linkRowLabel}
          type="button"
          variant="ghost"
        >
          <ExternalLink aria-hidden className="size-4" />
        </Button>
      ) : null}
      {canEdit ? (
        <Button
          aria-label={editRowLabel}
          className="size-7 text-muted-foreground hover:text-foreground"
          onClick={(event) => {
            event.stopPropagation();
            onEditRow?.(row, event);
          }}
          size="icon"
          title={editRowLabel}
          type="button"
          variant="ghost"
        >
          <Pencil aria-hidden className="size-4" />
        </Button>
      ) : null}
    </div>
  );
}

function DataTableGalleryCard<TData extends Record<string, unknown>>({
  actionsCell,
  aspectRatio,
  canEditRow,
  editRowLabel,
  imageColumnId,
  imageFit,
  isActive,
  isClickable,
  linkRowLabel,
  linkUrl,
  onEditRow,
  onOpenRowLink,
  onRowClick,
  propertyCells,
  propertyLabels,
  row,
  selectionCell,
  showCardLabels,
  titleCell,
  titleColumnId,
}: GalleryCardProps<TData>) {
  const titleContent = titleCell
    ? flexRender(titleCell.column.columnDef.cell, titleCell.getContext())
    : getStringValue(titleColumnId ? row.original[titleColumnId] : row.id) ||
      row.id;
  const title =
    getStringValue(titleColumnId ? row.original[titleColumnId] : row.id) ||
    row.id;
  const imageSource = resolveImageSource(
    imageColumnId ? row.original[imageColumnId] : undefined
  );

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: clickable cards keep nested selection/actions valid and provide keyboard activation.
    <article
      className={cn(
        "group overflow-hidden rounded-md border bg-background shadow-xs transition",
        isClickable &&
          "cursor-pointer hover:border-primary/40 hover:bg-muted/20",
        isActive &&
          "border-primary/50 shadow-[inset_2px_0_0_hsl(var(--primary))]"
      )}
      data-active={isActive ? "true" : undefined}
      onClick={
        isClickable
          ? (event) => {
              onRowClick?.(row, event);
            }
          : undefined
      }
      onKeyDown={
        isClickable
          ? (event) => {
              if (shouldActivateCardFromKeyboard(event)) {
                event.preventDefault();
                event.currentTarget.click();
              }
            }
          : undefined
      }
      role={isClickable ? "button" : undefined}
      tabIndex={isClickable ? 0 : undefined}
    >
      <GalleryCardMedia
        aspectRatio={aspectRatio}
        imageFit={imageFit}
        source={imageSource}
        title={title}
      />
      <div className="p-3">
        <div className="flex items-start gap-2">
          {selectionCell ? (
            <div className="mt-0.5 shrink-0" data-column-id="select">
              {flexRender(
                selectionCell.column.columnDef.cell,
                selectionCell.getContext()
              )}
            </div>
          ) : null}
          <div className="min-w-0 flex-1">
            <div className="line-clamp-2 font-medium text-sm">
              {titleContent}
            </div>
          </div>
          <GalleryCardActions
            canEditRow={canEditRow}
            editRowLabel={editRowLabel}
            linkRowLabel={linkRowLabel}
            linkUrl={linkUrl}
            onEditRow={onEditRow}
            onOpenRowLink={onOpenRowLink}
            row={row}
          />
          {actionsCell ? (
            <div className="shrink-0" data-column-id="actions">
              {flexRender(
                actionsCell.column.columnDef.cell,
                actionsCell.getContext()
              )}
            </div>
          ) : null}
        </div>

        <GalleryCardProperties
          propertyCells={propertyCells}
          propertyLabels={propertyLabels}
          showCardLabels={showCardLabels}
        />
      </div>
    </article>
  );
}

export function DataTableGalleryView<TData extends Record<string, unknown>>({
  canEditRow,
  className,
  columnDefinitions,
  config,
  editRowLabel = "Edit",
  emptyState,
  getRowLinkUrl,
  groupBy = "",
  groupLabel,
  isRowActive,
  isRowClickable,
  linkRowLabel = "View",
  onEditRow,
  onOpenRowLink,
  onRowClick,
  table,
}: DataTableGalleryViewProps<TData>) {
  const hasTableGrouping = table.store.state.grouping.length > 0;
  const rows = (
    hasTableGrouping
      ? table.getPreGroupedRowModel().rows
      : table.getRowModel().rows
  ) as Row<TData>[];
  const resolvedConfig = resolveGalleryDisplayConfig(config);
  const imageColumnId = resolveGalleryImageColumnId({
    columnDefinitions,
    config: resolvedConfig,
  });
  const titleColumnId = resolveGalleryTitleColumnId({
    columnDefinitions,
    config: resolvedConfig,
  });
  const propertyLabels = useMemo(() => {
    return new Map(
      columnDefinitions.map((definition) => [
        definition.id,
        getColumnLabel(columnDefinitions, definition.id),
      ])
    );
  }, [columnDefinitions]);
  const galleryGroups = useMemo(
    () => createGalleryGroups({ groupBy, rows }),
    [groupBy, rows]
  );

  if (rows.length === 0) {
    return <div className="rounded-md border">{emptyState}</div>;
  }

  const renderCard = (row: Row<TData>) => {
    const visibleCells = row.getVisibleCells();
    return (
      <DataTableGalleryCard
        actionsCell={visibleCells.find((cell) => cell.column.id === "actions")}
        aspectRatio={resolvedConfig.aspectRatio}
        canEditRow={canEditRow?.(row) ?? false}
        editRowLabel={editRowLabel}
        imageColumnId={imageColumnId}
        imageFit={resolvedConfig.imageFit}
        isActive={isRowActive?.(row) ?? false}
        isClickable={isRowClickable?.(row) ?? false}
        key={row.id}
        linkRowLabel={linkRowLabel}
        linkUrl={getRowLinkUrl?.(row)}
        onEditRow={onEditRow}
        onOpenRowLink={onOpenRowLink}
        onRowClick={onRowClick}
        propertyCells={getGalleryPropertyCells({
          cardColumnIds: resolvedConfig.cardColumnIds,
          groupBy,
          imageColumnId,
          row,
          titleColumnId,
        })}
        propertyLabels={propertyLabels}
        row={row}
        selectionCell={visibleCells.find((cell) => cell.column.id === "select")}
        showCardLabels={shouldShowGalleryCardLabels(resolvedConfig)}
        titleCell={getCellByColumnId(row, titleColumnId)}
        titleColumnId={titleColumnId}
      />
    );
  };

  return (
    <div className={cn("rounded-md border bg-background p-3", className)}>
      {groupBy ? (
        <div className="space-y-5">
          {galleryGroups.map((group) => (
            <section key={group.id}>
              <div className="mb-2 flex items-center justify-between gap-3 px-1">
                <h3 className="min-w-0 truncate font-medium text-sm">
                  {groupLabel ? (
                    <span className="text-muted-foreground">
                      {groupLabel}:{" "}
                    </span>
                  ) : null}
                  {group.label}
                </h3>
                <span className="rounded-full bg-muted px-2 py-0.5 text-muted-foreground text-xs">
                  {group.rows.length}
                </span>
              </div>
              <div
                className={cn(
                  "grid gap-3",
                  GALLERY_CARD_SIZE_CLASS[resolvedConfig.cardSize]
                )}
              >
                {group.rows.map((row) => renderCard(row))}
              </div>
            </section>
          ))}
        </div>
      ) : (
        <div
          className={cn(
            "grid gap-3",
            GALLERY_CARD_SIZE_CLASS[resolvedConfig.cardSize]
          )}
        >
          {rows.map((row) => renderCard(row))}
        </div>
      )}
    </div>
  );
}

