    : row.id;
  const cardInteractionProps = isClickable
    ? {
        onClick: (event: MouseEvent<HTMLDivElement>) => {
          onRowClick?.(row, event);
        },
        onKeyDown: (event: KeyboardEvent<HTMLDivElement>) => {
          if (shouldActivateCardFromKeyboard(event)) {
