  );
}

export function DataTableKanbanView<TData extends Record<string, unknown>>({
  canDragUpdate,
  cardColumnIds,
  className,
  columnDefinitions,
  config,
  emptyState,
  groupBy,
  isRowActive,
  isRowClickable,
  onMoveRow,
  onRowClick,
  table,
  titleColumnId,
}: DataTableKanbanViewProps<TData>) {
  const hasTableGrouping = table.store.state.grouping.length > 0;
  const rows = (
    hasTableGrouping
      ? table.getPreGroupedRowModel().rows
      : table.getRowModel().rows
  ) as Row<TData>[];
  const shouldUseConfiguredGroups = shouldUseConfiguredKanbanGroups({
    configuredGroupBy: config?.groupBy,
    groupBy,
  });
  const configuredGroups = useMemo(
    () =>
      createConfiguredGroups(
        shouldUseConfiguredGroups ? config?.groups : undefined
      ),
    [config?.groups, shouldUseConfiguredGroups]
  );
  const groups = useMemo(
    () => createKanbanGroups({ configuredGroups, groupBy, rows }),
    [configuredGroups, groupBy, rows]
  );
  const kanbanColumns = useMemo(() => createKanbanColumns(groups), [groups]);
  const resolvedTitleColumnId =
    titleColumnId ?? config?.titleColumn ?? getDefaultTitleColumnId(table);
  const initialKanbanItems = useMemo(
    () =>
      createKanbanItems({
        columns: kanbanColumns,
        groupBy,
        rows,
        titleColumnId: resolvedTitleColumnId,
      }),
    [groupBy, kanbanColumns, resolvedTitleColumnId, rows]
  );
  const [kanbanItems, setKanbanItems] = useState(initialKanbanItems);

  useEffect(() => {
    setKanbanItems(initialKanbanItems);
  }, [initialKanbanItems]);

  const propertyLabels = useMemo(() => {
    return new Map(
      columnDefinitions.map((definition) => [
        definition.id,
        getColumnLabel(columnDefinitions, definition.id),
      ])
    );
  }, [columnDefinitions]);
  const columnDefinitionsById = useMemo(() => {
    return new Map(
      columnDefinitions.map((definition) => [definition.id, definition])
    );
  }, [columnDefinitions]);
  const showCardLabels = shouldShowKanbanCardLabels(config);
  const rowCountByColumnId = useMemo(() => {
    const next = new Map<string, number>();
    for (const column of kanbanColumns) {
      next.set(column.id, 0);
    }
    for (const item of kanbanItems) {
      next.set(item.column, (next.get(item.column) ?? 0) + 1);
    }
    return next;
  }, [kanbanColumns, kanbanItems]);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      if (!canDragUpdate) {
        return;
      }

      const rowId = String(event.active.id);
      const overId = event.over ? String(event.over.id) : "";
      const activeItem = kanbanItems.find((item) => item.id === rowId);
      const overItem = kanbanItems.find((item) => item.id === overId);
      const nextColumnId =
        overItem?.column ??
        kanbanColumns.find((column) => column.id === overId)?.id;
      const nextColumn = kanbanColumns.find(
        (column) => column.id === nextColumnId
      );

      if (
        !(activeItem && nextColumn) ||
        activeItem.groupValue === nextColumn.value
      ) {
        return;
      }

      onMoveRow?.(activeItem.row, nextColumn.value);
    },
    [canDragUpdate, kanbanColumns, kanbanItems, onMoveRow]
  );

  if (rows.length === 0) {
    return <div className="rounded-md border">{emptyState}</div>;
  }

  return (
    <div
      className={cn(
        "overflow-x-auto rounded-md border bg-background",
        className
      )}
    >
      <KanbanProvider<DataTableKanbanItem<TData>, DataTableKanbanColumn>
        className="min-h-[30rem] w-max auto-cols-[18rem] gap-3 p-3"
        columns={kanbanColumns}
        data={kanbanItems}
        onDataChange={canDragUpdate ? setKanbanItems : undefined}
        onDragEnd={handleDragEnd}
      >
        {(column) => (
          <KanbanBoard
            className="min-h-[28rem] w-[18rem] bg-muted/20"
            id={column.id}
            key={column.id}
          >
            <KanbanHeader className="flex h-11 items-center justify-between px-3 py-0">
              <div className="min-w-0">
                <h3 className="truncate font-medium text-sm">{column.label}</h3>
              </div>
              <span className="rounded-full bg-background px-2 py-0.5 text-muted-foreground text-xs">
                {rowCountByColumnId.get(column.id) ?? 0}
              </span>
            </KanbanHeader>
            <KanbanCards<DataTableKanbanItem<TData>> id={column.id}>
              {(item) => {
                const row = item.row;
                const cells = row.getVisibleCells();
                const titleCell = cells.find(
                  (cell) => cell.column.id === resolvedTitleColumnId
                );
                const selectionCell = cells.find(
                  (cell) => cell.column.id === "select"
                );
                const actionsCell = cells.find(
                  (cell) => cell.column.id === "actions"
                );

                return (
                  <DataTableKanbanCard
                    actionsCell={actionsCell}
                    canDragUpdate={canDragUpdate}
                    columnDefinitionsById={columnDefinitionsById}
                    columnId={item.column}
                    isActive={isRowActive?.(row) ?? false}
                    isClickable={isRowClickable?.(row) ?? false}
                    key={row.id}
                    onRowClick={onRowClick}
                    propertyCells={getCardPropertyCells({
                      cardColumnIds,
                      groupBy,
                      row,
                      titleColumnId: resolvedTitleColumnId,
                    })}
                    propertyLabels={propertyLabels}
                    row={row}
                    selectionCell={selectionCell}
                    showCardLabels={showCardLabels}
                    titleCell={titleCell}
                  />
                );
              }}
            </KanbanCards>
          </KanbanBoard>
        )}
      </KanbanProvider>
    </div>
  );
}

/**
 * Pagination with native select to avoid Radix feedback loops
 */
"use client";

import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { type ReactNode, type Ref, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useTableTranslations } from "../hooks";
import type { Table } from "../tanstack";

interface SafePaginationProps<TData> {
  containerRef?: Ref<HTMLDivElement>;
  controlsRef?: Ref<HTMLDivElement>;
  table: Table<TData>;
  rowCount?: number;
  className?: string;
  footerSlot?: ReactNode;
  pageSizeOptions?: number[];
  showControls?: boolean;
}

export function SafePagination<TData>({
  containerRef,
  controlsRef,
  table,
  rowCount,
  className,
  footerSlot,
  pageSizeOptions = [10, 20, 50, 100, 200, 500],
  showControls = true,
}: SafePaginationProps<TData>) {
  const translations = useTableTranslations();

  // Get pagination state
  const { pageIndex, pageSize } = table.store.state.pagination;
  const pageCount = table.getPageCount();

  // Calculate display info
  const startRow = pageIndex * pageSize + 1;
  const endRow = Math.min(
    (pageIndex + 1) * pageSize,
    rowCount || table.getRowModel().rows.length
  );

  const normalizedPageSizeOptions = [...new Set(pageSizeOptions)]
    .filter((size) => Number.isFinite(size) && size > 0)
    .sort((a, b) => a - b);
  const availablePageSizes = normalizedPageSizeOptions.includes(pageSize)
    ? normalizedPageSizeOptions
    : [...normalizedPageSizeOptions, pageSize].sort((a, b) => a - b);

  // Handle page size change
  const handlePageSizeChange = useCallback(
    (newSize: string) => {
      const parsedSize = Number.parseInt(newSize, 10);
      if (Number.isNaN(parsedSize)) {
        return;
      }

      const current = table.store.state.pagination.pageSize;
      if (parsedSize === current) {
        return;
      }

      table.setPageSize(parsedSize);
    },
    [table]
  );

  const hasFooterSlot = footerSlot != null;
  if (!(showControls || hasFooterSlot)) {
    return null;
  }

  return (
    <div
      className={cn("flex flex-col gap-4 py-4", className)}
      ref={containerRef}
    >
      {hasFooterSlot ? (
        <div className="flex w-full justify-center">{footerSlot}</div>
      ) : null}

      {showControls ? (
        <div
          className="flex flex-col items-center justify-between gap-4 sm:flex-row"
          ref={controlsRef}
        >
          {/* Row range display */}
          <div className="flex-1 text-muted-foreground text-sm">
            {startRow}-{endRow} {translations.of}{" "}
            {rowCount ?? table.getRowModel().rows.length}
          </div>

          {/* Page size selector */}
          <div className="flex items-center gap-2">
            <p className="font-medium text-sm">{translations.rowsPerPage}</p>
            <div className="relative">
              <select
                aria-label={translations.rowsPerPage}
                className="h-8 min-w-20 appearance-none rounded-md border bg-background py-1.5 pr-8 pl-3 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                onChange={(event) => handlePageSizeChange(event.target.value)}
                value={pageSize.toString()}
              >
                {availablePageSizes.map((size) => (
                  <option key={size} value={size.toString()}>
                    {size}
                  </option>
                ))}
              </select>
              <ChevronDown className="pointer-events-none absolute top-1/2 right-2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            </div>
          </div>

          {/* Page navigation */}
          <div className="flex items-center gap-2">
            <Button
              aria-label={translations.firstPage}
              className="h-8 w-8"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.setPageIndex(0)}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronsLeft className="h-4 w-4" />
            </Button>
            <Button
              aria-label={translations.previousPage}
              className="h-8 w-8"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.previousPage()}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>

            <span className="text-sm">
              {translations.format("pageXofY", {
                page: pageIndex + 1,
                total: pageCount || 1,
              })}
            </span>

            <Button
              aria-label={translations.nextPage}
              className="h-8 w-8"
              disabled={!table.getCanNextPage()}
              onClick={() => table.nextPage()}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button
              aria-label={translations.lastPage}
              className="h-8 w-8"
              disabled={!table.getCanNextPage()}
              onClick={() => table.setPageIndex(pageCount - 1)}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronsRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      ) : null}
    </div>
  );
}

/**
 * Sortable row component for DataTable
 * Uses dnd-kit for drag and drop functionality
 */
"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useAtomValue } from "jotai";
import type * as React from "react";
import { cn } from "@/lib/utils";

import { activeRowDragAtom, rowDragEnabledAtom } from "../atoms/table-atoms";

interface SortableRowProps {
  children: React.ReactNode;
  className?: string;
  id: string;
  tableId: string;
}

/**
 * A sortable row component that can be dragged to reorder rows
 */
export function SortableRow({
  children,
  className,
  id,
  tableId,
}: SortableRowProps) {
  // Get state from atoms
  const isDragEnabled = useAtomValue(rowDragEnabledAtom(tableId));
  const activeDragId = useAtomValue(activeRowDragAtom(tableId));

  // Get sortable props from dnd-kit - always call hooks at the top level
  const {
    attributes,
    isDragging,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({
    // Use the provided ID directly for the DnD context
    data: {
      stableId: `row-${id}`,
    },
    disabled: !isDragEnabled, // Disable sortable functionality instead of conditionally rendering
    id,
  });

  // Create style for the draggable element
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  // Determine if this row is being dragged over
  const isOver = activeDragId !== null && activeDragId !== id;

  // If drag is disabled, just return the children as-is
  if (!isDragEnabled) {
    return <>{children}</>;
  }

  // Use a simpler approach to avoid hydration issues
  // Instead of trying to clone elements, we'll simply wrap the children in a div
  // with the drag-and-drop properties

  // Create an object with the drag-and-drop properties
  const dragProps = {
    ref: setNodeRef,
    style,
    ...attributes,
    ...listeners,
    "aria-label": `Drag to reorder row ${id}`,
    className: cn(
      className,
      "relative cursor-grab select-none",
      isDragging && "z-10 cursor-grabbing opacity-50 shadow-lg",
      isOver && "border-2 border-primary/50"
    ),
  };

  // Return the children wrapped in a div with the drag-and-drop properties
  return <div {...dragProps}>{children}</div>;
}

