    AdvancedTableFiltersMenuProps,
    | "advancedFilters"
    | "advancedActions"
    | "advancedColumnsConfig"
    | "useAdvancedFilters"
    | "onConvertToAdvanced"
  >
) {
  return <AdvancedTableFiltersMenu {...props} useAdvancedFilters={false} />;
