 * Default bulk action handlers.
 */
export const defaultBulkActions = {
  onBulkEdit: <TData>(_rows: Row<TData>[]) => {
    toast.info(
      "Bulk edit requires configuration. Provide onBulkEdit or actions.bulkUpdate(ids, data)."
    );
