/**
 * Pure calculation functions for column footer aggregations.
 * Operates on an array of raw cell values extracted from visible rows.
 */

import type { CalculationType } from "../types/footer-types";

/**
 * Extract a typed value from a cell.
 * Returns `undefined` for null/undefined/empty-string.
 */
const normalize = (value: unknown): unknown => {
  if (value === null || value === undefined || value === "") {
    return undefined;
  }
  return value;
};

const toNumber = (v: unknown): number | undefined => {
  if (typeof v === "number" && Number.isFinite(v)) {
    return v;
  }
  if (typeof v === "string") {
    const parsed = Number(v);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }
  return undefined;
};

const toDate = (v: unknown): Date | undefined => {
  if (v instanceof Date && !Number.isNaN(v.getTime())) {
    return v;
  }
  if (typeof v === "string" || typeof v === "number") {
    const d = new Date(v);
    if (!Number.isNaN(d.getTime())) {
      return d;
    }
  }
  return undefined;
};

const toBoolean = (v: unknown): boolean | undefined => {
  if (typeof v === "boolean") {
    return v;
  }
  if (typeof v === "number") {
    if (v === 1) {
      return true;
    }
    if (v === 0) {
      return false;
    }
    return undefined;
  }
  if (typeof v === "string") {
    const normalized = v.trim().toLowerCase();
    if (normalized === "true" || normalized === "1") {
      return true;
    }
    if (normalized === "false" || normalized === "0") {
      return false;
    }
  }
  return undefined;
};

/**
 * Compute a column calculation over a set of raw values.
 *
 * @param values - raw cell values for a single column across all visible rows
 * @param type - the calculation to perform
 * @param columnType - the column data type (number, date, etc.) for formatting hints
 * @returns the calculated result as a display-ready value, or null if not applicable
 */
export const calculateColumn = (
  values: unknown[],
  type: CalculationType,
  columnType?: string,
  locale?: string
): { raw: number | string | null; label: string } => {
  const total = values.length;
  const normalized = values.map(normalize);
  const nonEmpty = normalized.filter((v) => v !== undefined);
  const emptyCount = total - nonEmpty.length;
  const booleanValues = nonEmpty
    .map(toBoolean)
    .filter((value): value is boolean => value !== undefined);
  const trueCount = booleanValues.filter(Boolean).length;
  const falseCount = booleanValues.length - trueCount;

  switch (type) {
    case "none":
      return { raw: null, label: "" };

    case "count_all":
      return { raw: total, label: String(total) };

    case "count_values":
      return { raw: nonEmpty.length, label: String(nonEmpty.length) };

    case "count_unique": {
      const unique = new Set(nonEmpty.map(String));
      return { raw: unique.size, label: String(unique.size) };
    }

    case "count_empty":
      return { raw: emptyCount, label: String(emptyCount) };

    case "count_not_empty":
      return { raw: nonEmpty.length, label: String(nonEmpty.length) };

    case "count_true":
      return { raw: trueCount, label: String(trueCount) };

    case "count_false":
      return { raw: falseCount, label: String(falseCount) };

    case "percent_empty": {
      if (total === 0) {
        return { raw: 0, label: "0%" };
      }
      const pct = Math.round((emptyCount / total) * 100);
      return { raw: pct, label: `${pct}%` };
    }

    case "percent_not_empty": {
      if (total === 0) {
        return { raw: 0, label: "0%" };
      }
      const pct = Math.round((nonEmpty.length / total) * 100);
      return { raw: pct, label: `${pct}%` };
    }

    case "percent_true": {
      if (total === 0) {
        return { raw: 0, label: "0%" };
      }
      const pct = Math.round((trueCount / total) * 100);
      return { raw: pct, label: `${pct}%` };
    }

    case "percent_false": {
      if (total === 0) {
        return { raw: 0, label: "0%" };
      }
      const pct = Math.round((falseCount / total) * 100);
      return { raw: pct, label: `${pct}%` };
    }

    case "sum":
      return computeNumericOrDate(nonEmpty, columnType, "sum", locale);

    case "average":
      return computeNumericOrDate(nonEmpty, columnType, "average", locale);

    case "median":
      return computeNumericOrDate(nonEmpty, columnType, "median", locale);

    case "min":
      return computeNumericOrDate(nonEmpty, columnType, "min", locale);

    case "max":
      return computeNumericOrDate(nonEmpty, columnType, "max", locale);

    case "range":
      return computeNumericOrDate(nonEmpty, columnType, "range", locale);

    default:
      return { raw: null, label: "" };
  }
};

type NumericOp = "sum" | "average" | "median" | "min" | "max" | "range";

const computeNumericOrDate = (
  nonEmpty: unknown[],
  columnType: string | undefined,
  op: NumericOp,
  locale?: string
): { raw: number | string | null; label: string } => {
  if (columnType === "date") {
    return computeDate(nonEmpty, op, locale);
  }
  return computeNumeric(nonEmpty, op, locale);
};

const computeNumeric = (
  nonEmpty: unknown[],
  op: NumericOp,
  locale?: string
): { raw: number | string | null; label: string } => {
  const numbers = nonEmpty
    .map(toNumber)
    .filter((n): n is number => n !== undefined);
  if (numbers.length === 0) {
    return { raw: null, label: "—" };
  }

  switch (op) {
    case "sum": {
      const s = numbers.reduce((a, b) => a + b, 0);
      return { raw: s, label: s.toLocaleString(locale) };
    }
    case "average": {
      const avg = numbers.reduce((a, b) => a + b, 0) / numbers.length;
      return {
        raw: avg,
        label: avg.toLocaleString(locale, { maximumFractionDigits: 2 }),
      };
    }
    case "median": {
      const sorted = [...numbers].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      const med =
        sorted.length % 2 === 0
          ? (sorted[mid - 1] + sorted[mid]) / 2
          : sorted[mid];
      return {
        raw: med,
        label: med.toLocaleString(locale, { maximumFractionDigits: 2 }),
      };
    }
    case "min": {
      const m = Math.min(...numbers);
      return { raw: m, label: m.toLocaleString(locale) };
    }
    case "max": {
      const m = Math.max(...numbers);
      return { raw: m, label: m.toLocaleString(locale) };
    }
    case "range": {
      const min = Math.min(...numbers);
      const max = Math.max(...numbers);
      const r = max - min;
      return { raw: r, label: r.toLocaleString(locale) };
    }
    default:
      return { raw: null, label: "—" };
  }
};

const computeDate = (
  nonEmpty: unknown[],
  op: NumericOp,
  locale?: string
): { raw: number | string | null; label: string } => {
  const dates = nonEmpty.map(toDate).filter((d): d is Date => d !== undefined);
  if (dates.length === 0) {
    return { raw: null, label: "—" };
  }

  const timestamps = dates.map((d) => d.getTime());
  const formatter = new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });

  switch (op) {
    case "min": {
      const minTs = Math.min(...timestamps);
      return { raw: minTs, label: formatter.format(new Date(minTs)) };
    }
    case "max": {
      const maxTs = Math.max(...timestamps);
      return { raw: maxTs, label: formatter.format(new Date(maxTs)) };
    }
    case "range": {
      const minTs = Math.min(...timestamps);
      const maxTs = Math.max(...timestamps);
      const diffDays = Math.round((maxTs - minTs) / (1000 * 60 * 60 * 24));
      return { raw: diffDays, label: `${diffDays}d` };
    }
    case "sum":
    case "average":
    case "median":
      return { raw: null, label: "—" };
    default:
      return { raw: null, label: "—" };
  }
};

/**
 * Utility for getting column type icons
 * Provides consistent icons across the data table components
 */
import {
  Asterisk,
  CalendarDays,
  CheckSquare,
  CircleDot,
  Hash,
  ImageIcon,
  List,
  type LucideIcon,
  SquareCode,
  Tag,
  Text,
  ToggleRight,
} from "lucide-react";

export const COLUMN_TYPE_ICONS: Record<string, LucideIcon> = {
  text: Text,
  string: Asterisk,
  number: Hash,
  boolean: ToggleRight,
  date: CalendarDays,
  image: ImageIcon,
  code: SquareCode,
  select: CheckSquare,
  multiselect: List,
};

const STATUS_COLUMN_PATTERN = /(status|state)/;
const CATEGORY_COLUMN_PATTERN = /(categor|type|tag)/;
const BOOLEAN_SELECT_COLUMN_PATTERN =
  /(^is[a-z0-9])|(active|enabled|disabled|visible|verified|published|archived)/;

/**
 * Resolve a semantic icon for select-like columns based on the column id.
 */
const getSemanticSelectIcon = (
  normalizedType: string,
  normalizedColumnId: string
): LucideIcon | undefined => {
  const isSelectLikeType =
    normalizedType === "select" || normalizedType === "multiselect";
  if (!(isSelectLikeType && normalizedColumnId)) {
    return;
  }

  if (STATUS_COLUMN_PATTERN.test(normalizedColumnId)) {
    return CircleDot;
  }
  if (CATEGORY_COLUMN_PATTERN.test(normalizedColumnId)) {
    return Tag;
  }
  if (BOOLEAN_SELECT_COLUMN_PATTERN.test(normalizedColumnId)) {
    return ToggleRight;
  }

  return normalizedType === "multiselect" ? List : CheckSquare;
};

/**
 * Get the icon component for a column type
 */
export const getColumnTypeIcon = (
  columnType: string,
  columnId?: string,
  displayVariant?: "default" | "tag"
): LucideIcon => {
  if (displayVariant === "tag") {
    return Tag;
  }

  const normalizedType = columnType.toLowerCase();
  const normalizedColumnId = columnId?.toLowerCase() ?? "";

  const semanticSelectIcon = getSemanticSelectIcon(
    normalizedType,
    normalizedColumnId
  );
  if (semanticSelectIcon) {
    return semanticSelectIcon;
  }

  return COLUMN_TYPE_ICONS[normalizedType] || Text;
};

/**
 * Render a column icon with consistent styling
 */
export const ColumnIcon = ({
  columnType,
  columnId,
  displayVariant,
  className = "h-4 w-4",
}: {
  columnType: string;
  columnId?: string;
  displayVariant?: "default" | "tag";
  className?: string;
}) => {
  const IconComponent = getColumnTypeIcon(columnType, columnId, displayVariant);
  return <IconComponent className={className} />;
};

/**
 * Utility functions for column pinning styles
 * Based on TanStack Table column pinning example
 */
"use client";

import type { CSSProperties } from "react";
import type { Column } from "../tanstack";

/**
 * Get common styles for pinned columns
 * @param column - The column to get styles for
 * @returns CSS properties for the column
 */
export function getColumnPinningStyles<TData>(
  column: Column<TData>
): CSSProperties {
  const isPinned = column.getIsPinned();
  const _isLastStartPinnedColumn =
    isPinned === "start" && column.getIsLastColumn("start");
  const _isFirstEndPinnedColumn =
    isPinned === "end" && column.getIsFirstColumn("end");

  return {
    // Position the column based on its pinning
    insetInlineStart:
      isPinned === "start" ? `${column.getStart("start")}px` : undefined,
    // Slight opacity difference for pinned columns
    opacity: isPinned ? 0.95 : 1,
    // Make pinned columns sticky
    position: isPinned ? "sticky" : "relative",
    insetInlineEnd:
      isPinned === "end" ? `${column.getAfter("end")}px` : undefined,
    // Set width based on column size
    width: column.getSize(),
    // Ensure pinned columns appear above other content
    zIndex: isPinned ? 1 : 0,
  };
}

/**
 * CSV export utilities shared by toolbar export and bulk export.
 */

const DEFAULT_SEPARATOR = ",";
const UTF8_BOM = "\uFEFF";

interface ExportColumnDefinition {
  header?: string;
  id: string;
}

export interface CsvExportColumn {
  id: string;
  label: string;
}

interface BuildCsvExportColumnsOptions {
  columnDefinitions: ExportColumnDefinition[];
  columnOrder?: string[];
  defaultVisibleColumns?: string[];
  excludedColumnIds?: string[];
  visibility?: Record<string, boolean>;
}

interface CreateCsvContentOptions {
  columns: CsvExportColumn[];
  rows: Record<string, unknown>[];
  separator?: string;
}

interface ExportRowsAsCsvOptions {
  columns: CsvExportColumn[];
  fileName?: string;
  rows: Record<string, unknown>[];
  separator?: string;
  tableId: string;
}

const DEFAULT_EXCLUDED_COLUMN_IDS = ["select", "actions"] as const;

const normalizeValueForCsv = (value: unknown): string => {
  if (value === null || value === undefined) {
    return "";
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  if (typeof value === "object") {
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  }

  return String(value);
};

const escapeCsvCell = (value: string, separator: string): string => {
  const needsQuotes =
    value.includes(separator) ||
    value.includes('"') ||
    value.includes("\n") ||
    value.includes("\r");

  const escaped = value.replaceAll('"', '""');
  return needsQuotes ? `"${escaped}"` : escaped;
};

const padTwoDigits = (value: number): string => {
  return String(value).padStart(2, "0");
};

export const getDefaultCsvFileName = (tableId: string): string => {
  const now = new Date();
  const formattedDate = `${now.getFullYear()}-${padTwoDigits(
    now.getMonth() + 1
  )}-${padTwoDigits(now.getDate())}`;
  return `${tableId}-${formattedDate}.csv`;
};

/**
 * Build export columns from config order + visibility, while excluding system columns.
 */
export const buildCsvExportColumns = ({
  columnDefinitions,
  columnOrder = [],
  defaultVisibleColumns = [],
  excludedColumnIds = [...DEFAULT_EXCLUDED_COLUMN_IDS],
  visibility = {},
}: BuildCsvExportColumnsOptions): CsvExportColumn[] => {
  const definitionsById = new Map<string, ExportColumnDefinition>();
  for (const definition of columnDefinitions) {
    definitionsById.set(definition.id, definition);
  }

  const orderedIds: string[] = [];
  for (const id of columnOrder) {
    if (definitionsById.has(id) && !orderedIds.includes(id)) {
      orderedIds.push(id);
    }
  }

  for (const definition of columnDefinitions) {
    if (!orderedIds.includes(definition.id)) {
      orderedIds.push(definition.id);
    }
  }

  const hasExplicitVisibility = Object.keys(visibility).length > 0;
  const defaultVisibleSet = new Set(defaultVisibleColumns);
  const excludedSet = new Set(excludedColumnIds);

  const columns: CsvExportColumn[] = [];
  for (const id of orderedIds) {
    if (excludedSet.has(id)) {
      continue;
    }

    let isVisible = true;
    if (hasExplicitVisibility) {
      isVisible = visibility[id] !== false;
    } else if (defaultVisibleSet.size > 0) {
      isVisible = defaultVisibleSet.has(id);
    }

    if (!isVisible) {
      continue;
    }

    const definition = definitionsById.get(id);
    columns.push({
      id,
      label: definition?.header ?? id,
    });
  }

  return columns;
};

export const createCsvContent = ({
  columns,
  rows,
  separator = DEFAULT_SEPARATOR,
}: CreateCsvContentOptions): string => {
  const headerLine = columns
    .map((column) => escapeCsvCell(column.label, separator))
    .join(separator);

  const dataLines = rows.map((row) => {
    return columns
      .map((column) => {
        const rawValue = row[column.id];
        const normalizedValue = normalizeValueForCsv(rawValue);
        return escapeCsvCell(normalizedValue, separator);
      })
      .join(separator);
  });

  const csvBody = [headerLine, ...dataLines].join("\n");
  return `${UTF8_BOM}${csvBody}`;
};

export const downloadCsvFile = (content: string, fileName: string): void => {
  if (typeof document === "undefined") {
    return;
  }

  const blob = new Blob([content], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.style.display = "none";
  document.body.append(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const exportRowsAsCsv = ({
  columns,
  fileName,
  rows,
  separator = DEFAULT_SEPARATOR,
  tableId,
}: ExportRowsAsCsvOptions): void => {
  const csvContent = createCsvContent({
    columns,
    rows,
    separator,
  });

  downloadCsvFile(csvContent, fileName ?? getDefaultCsvFileName(tableId));
};

import { format as formatDateFns } from "date-fns";
import {
  type DateDisplayPreset,
  DEFAULT_DATE_DISPLAY_PRESET,
} from "../types/date-types";

interface DateDisplayConfig {
  dateDisplayPreset?: DateDisplayPreset;
  fallbackDateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  locale?: string;
  showTime?: boolean;
}

const pad2 = (value: number): string => value.toString().padStart(2, "0");
const YEAR_MONTH_GROUP_KEY_REGEX = /^(\d{4})-(\d{2})$/;

const resolveLocale = (locale?: string): string => {
  if (!locale) {
    return "en-US";
  }

  try {
    // Validate locale to avoid runtime crashes with malformed values.
    new Intl.DateTimeFormat(locale);
    return locale;
  } catch {
    return "en-US";
  }
};

const formatLocalTime = (date: Date, locale?: string): string => {
  return new Intl.DateTimeFormat(resolveLocale(locale), {
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
};

const resolvePreset = ({
  dateDisplayPreset,
  fallbackDateDisplayPreset,
}: DateDisplayConfig): DateDisplayPreset | undefined => {
  return dateDisplayPreset ?? fallbackDateDisplayPreset;
};

const formatWithPreset = (
  date: Date,
  preset: DateDisplayPreset,
  locale?: string
): string => {
  const safeLocale = resolveLocale(locale);

  switch (preset) {
    case "localized-short":
      return new Intl.DateTimeFormat(safeLocale, {
        dateStyle: "short",
      }).format(date);
    case "localized-medium":
      return new Intl.DateTimeFormat(safeLocale, {
        dateStyle: "medium",
      }).format(date);
    case "localized-long":
      return new Intl.DateTimeFormat(safeLocale, {
        dateStyle: "long",
      }).format(date);
    case "month-name-long":
      return new Intl.DateTimeFormat(safeLocale, {
        day: "2-digit",
        month: "long",
        year: "numeric",
      }).format(date);
    case "month-year":
      return new Intl.DateTimeFormat(safeLocale, {
        month: "long",
        year: "numeric",
      }).format(date);
    case "dmy-numeric":
      return `${pad2(date.getDate())}/${pad2(date.getMonth() + 1)}/${date.getFullYear()}`;
    case "dmy-short":
      return `${pad2(date.getDate())}/${pad2(date.getMonth() + 1)}/${String(date.getFullYear()).slice(-2)}`;
    case "mdy-numeric":
      return `${pad2(date.getMonth() + 1)}/${pad2(date.getDate())}/${date.getFullYear()}`;
    case "mdy-short":
      return `${pad2(date.getMonth() + 1)}/${pad2(date.getDate())}/${String(date.getFullYear()).slice(-2)}`;
    case "iso-date":
      return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
    default:
      return new Intl.DateTimeFormat(safeLocale, {
        dateStyle: "short",
      }).format(date);
  }
};

const appendTimeIfNeeded = (
  label: string,
  date: Date,
  showTime: boolean,
  locale?: string
): string => {
  if (!showTime) {
    return label;
  }

  return `${label} ${formatLocalTime(date, locale)}`;
};

const formatWithLegacyPattern = (
  date: Date,
  dateFormat: string,
  showTime: boolean
): string => {
  const formatString = showTime ? `${dateFormat} HH:mm` : dateFormat;
  return formatDateFns(date, formatString);
};

const isDateWithSet = (value: unknown): value is { set: unknown } => {
  return Boolean(
    value &&
      typeof value === "object" &&
      "set" in value &&
      Object.hasOwn(value, "set")
  );
};

export const toValidDate = (value: unknown): Date | undefined => {
  if (isDateWithSet(value)) {
    return toValidDate(value.set);
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  if (typeof value === "string" || typeof value === "number") {
    const parsedDate = new Date(value);
    return Number.isNaN(parsedDate.getTime()) ? undefined : parsedDate;
  }

  return;
};

export const toValidDateRange = (value: unknown): [Date, Date] | undefined => {
  if (!Array.isArray(value)) {
    const singleDate = toValidDate(value);
    return singleDate ? [singleDate, singleDate] : undefined;
  }

  const startDate = toValidDate(value[0]);
  const endDate = toValidDate(value[1] ?? value[0]);
  if (!(startDate && endDate)) {
    if (startDate) {
      return [startDate, startDate];
    }
    if (endDate) {
      return [endDate, endDate];
    }
    return;
  }

  return startDate.getTime() <= endDate.getTime()
    ? [startDate, endDate]
    : [endDate, startDate];
};

export const formatDateForDisplay = (
  value: unknown,
  config: DateDisplayConfig = {}
): string | undefined => {
  const parsedDate = toValidDate(value);
  if (!parsedDate) {
    return;
  }

  const preset = resolvePreset(config);
  if (preset) {
    return appendTimeIfNeeded(
      formatWithPreset(parsedDate, preset, config.locale),
      parsedDate,
      Boolean(config.showTime),
      config.locale
    );
  }

  if (config.dateFormat) {
    try {
      return formatWithLegacyPattern(
        parsedDate,
        config.dateFormat,
        Boolean(config.showTime)
      );
    } catch {
      return appendTimeIfNeeded(
        formatWithPreset(
          parsedDate,
          DEFAULT_DATE_DISPLAY_PRESET,
          config.locale
        ),
        parsedDate,
        Boolean(config.showTime),
        config.locale
      );
    }
  }

  return appendTimeIfNeeded(
    formatWithPreset(parsedDate, DEFAULT_DATE_DISPLAY_PRESET, config.locale),
    parsedDate,
    Boolean(config.showTime),
    config.locale
  );
};

export const formatDateRangeForDisplay = (
  value: unknown,
  config: DateDisplayConfig = {}
): string | undefined => {
  const range = toValidDateRange(value);
  if (!range) {
    return;
  }

  const startLabel = formatDateForDisplay(range[0], config);
  const endLabel = formatDateForDisplay(range[1], config);
  if (!(startLabel && endLabel)) {
    return;
  }

  return `${startLabel} - ${endLabel}`;
};

export const toYearMonthGroupKey = (value: unknown): string | undefined => {
  const parsedDate = toValidDate(value);
  if (!parsedDate) {
    return;
  }

  return `${parsedDate.getFullYear()}-${pad2(parsedDate.getMonth() + 1)}`;
};

export const formatYearMonthGroupLabel = (
  valueOrKey: unknown,
  locale?: string
): string => {
  if (typeof valueOrKey === "string") {
    const match = YEAR_MONTH_GROUP_KEY_REGEX.exec(valueOrKey);
    if (match) {
      const year = Number.parseInt(match[1], 10);
      const monthIndex = Number.parseInt(match[2], 10) - 1;
      if (!Number.isNaN(year) && monthIndex >= 0 && monthIndex <= 11) {
        return formatWithPreset(
          new Date(year, monthIndex, 1),
          "month-year",
          locale
        );
      }
    }
  }

  const parsedDate = toValidDate(valueOrKey);
  if (!parsedDate) {
    return "";
  }

  return formatWithPreset(parsedDate, "month-year", locale);
};

import type { TableActions } from "../providers/table-provider";
import {
  fetchAllContractRows,
  normalizeFilterEnvelope,
} from "./table-contracts";

export type FilteredRowsOrderBy = Record<string, "asc" | "desc">;

export type TableListAction = NonNullable<TableActions["list"]>;

export const DEFAULT_FETCH_PAGE_SIZE = 100;
export const MAX_FETCH_PAGES = 1000;

export const toOrderByParam = (
  sortParam: unknown
): FilteredRowsOrderBy | undefined => {
  if (!Array.isArray(sortParam) || sortParam.length === 0) {
    return;
  }

  return Object.fromEntries(
    sortParam
      .filter((sort): sort is { id: string; desc?: boolean } =>
        Boolean(sort && typeof sort === "object" && typeof sort.id === "string")
      )
      .map((sort) => [sort.id, sort.desc ? "desc" : "asc"])
  );
};

export const toFiltersParam = (
  filtersParam: unknown
): Record<string, unknown> => {
  if (!Array.isArray(filtersParam)) {
    return {};
  }

  const parsedFilters = filtersParam as Array<{ id: string; value: unknown }>;
  return Object.fromEntries(
    parsedFilters
      .filter((filter) => !["global", "id", "key"].includes(filter.id))
      .map((filter) => [filter.id, filter.value])
  );
};

export const toAdvancedFiltersParam = (
  advancedFiltersParam: unknown
): unknown[] => {
  return normalizeFilterEnvelope(advancedFiltersParam).filters.filter(
    (filter) => filter.isActive !== false
  );
};

export const toPageSize = (
  pageSizeParam: string | undefined,
  fallback = DEFAULT_FETCH_PAGE_SIZE
): number => {
  const parsedPageSize = Number.parseInt(pageSizeParam || String(fallback), 10);
  if (Number.isNaN(parsedPageSize) || parsedPageSize < 1) {
    return fallback;
  }
  return parsedPageSize;
};

const toRecordRows = (data: unknown[]): Record<string, unknown>[] => {
  return data.filter(
    (row): row is Record<string, unknown> =>
      typeof row === "object" && row !== null
  );
};

export const fetchAllFilteredRows = async ({
  listAction,
  advancedFilters,
  filters,
  orderBy,
  pageSize,
  search,
}: {
  listAction: TableListAction;
  advancedFilters: unknown[];
  filters: Record<string, unknown>;
  orderBy?: FilteredRowsOrderBy;
  pageSize: number;
  search: string;
}): Promise<Record<string, unknown>[]> => {
  return toRecordRows(
    await fetchAllContractRows({
      list: listAction,
      params: { advancedFilters, filters, orderBy, pageSize, search },
      maxPages: MAX_FETCH_PAGES,
    })
  );
};

const IMAGE_SOURCE_PATTERN =
  /^(?:https?:\/\/|\/(?!\/)|data:image\/[a-z0-9.+-]+;base64,|blob:)/i;

export function resolveImageSource(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return;
  }

  const source = value.trim();
  if (!(source && IMAGE_SOURCE_PATTERN.test(source))) {
    return;
  }

  return source;
}

export function getImageFallbackInitial(value: unknown): string {
  if (typeof value !== "string") {
    return "?";
  }

  const trimmed = value.trim();
  return trimmed ? trimmed.charAt(0).toUpperCase() : "?";
}

/**
 * Number format configuration for numeric columns.
 * Supports presets (space/dot/comma thousands) or explicit separators.
 */

/** Preset: " " = 1 234 567.89, "." = 1.234.567,89, "locale" = Intl */
export type NumberFormatPreset = "space" | "dot" | "comma" | "locale";

export interface NumberFormatOptions {
  /** Thousands separator (e.g. " ", ".", ",") */
  thousandsSeparator?: string;
  /** Decimal separator (e.g. ".", ",") */
  decimalSeparator?: string;
  /** Fixed number of decimal places; omit for automatic */
  decimals?: number;
  /** Prefix for monetary display (e.g. "€ " or "$") */
  prefix?: string;
  /** Suffix for monetary display (e.g. " €" or " $") */
  suffix?: string;
}

/** Config: preset name or explicit options */
export type NumberFormatConfig = NumberFormatPreset | NumberFormatOptions;

const PRESETS: Record<
  NumberFormatPreset,
  { thousandsSeparator: string; decimalSeparator: string }
> = {
  space: { thousandsSeparator: " ", decimalSeparator: "." },
  dot: { thousandsSeparator: ".", decimalSeparator: "," },
  comma: { thousandsSeparator: ",", decimalSeparator: "." },
  locale: { thousandsSeparator: "", decimalSeparator: "" }, // use Intl
};

function isPreset(config: NumberFormatConfig): config is NumberFormatPreset {
  return typeof config === "string";
}

/**
 * Resolve config to options (with defaults for locale)
 */
export function resolveNumberFormat(
  config: NumberFormatConfig
): NumberFormatOptions {
  if (isPreset(config)) {
    if (config === "locale") {
      return { thousandsSeparator: "", decimalSeparator: "" };
    }
    return PRESETS[config];
  }
  return config;
}

/**
 * Format a number with the given config.
 * - "locale": uses Intl.NumberFormat with undefined locale (browser default).
 * - Otherwise: splits integer/fraction, inserts thousands separator, joins with decimal separator.
 */
export function formatNumber(
  value: number,
  config: NumberFormatConfig,
  decimals?: number
): string {
  if (!Number.isFinite(value)) {
    return "—";
  }

  const opts = resolveNumberFormat(config);
  const useLocale = isPreset(config) && config === "locale";

  if (useLocale) {
    const dec = decimals ?? opts.decimals;
    return new Intl.NumberFormat(undefined, {
      maximumFractionDigits: dec ?? 2,
      minimumFractionDigits: dec,
    }).format(value);
  }

  const dec = decimals ?? opts.decimals ?? 2;
  const decimalSep = opts.decimalSeparator ?? ".";
  const thousandsSep = opts.thousandsSeparator ?? " ";

  const [intPart, fracPart] = value.toFixed(dec).split(".");
  const withThousands = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, thousandsSep);
  const numeric =
    dec <= 0
      ? withThousands
      : `${withThousands}${decimalSep}${fracPart ?? "0".repeat(dec)}`;
  const prefix = opts.prefix ?? "";
  const suffix = opts.suffix ?? "";
  return `${prefix}${numeric}${suffix}`;
}

/**
 * Utilities for handling server-side filtering in DataTable
 */
"use client";

/**
 * Interface for complex filter objects
 */
interface ComplexFilter {
  id: string;
  operator: string;
  value: string;
}

/**
 * Interface for filter objects
 */
interface Filter {
  id: string;
  value: unknown;
}

/**
 * Apply complex filters on the client side
 * @param data Array of data items
 * @param complexFilters Array of complex filters to apply
 * @returns Filtered data
 */
export function applyComplexFilters<T>(
  data: T[],
  complexFilters: ComplexFilter[]
) {
  // If no complex filters, return data as is
  if (complexFilters.length === 0) {
    return data;
  }

  // Apply each complex filter
  return data.filter((item) => {
    // Item must match all complex filters
    return complexFilters.every((filter) => {
      const fieldValue = String(
        (item as Record<string, unknown>)[filter.id] || ""
      ).toLowerCase();

      // Apply the appropriate operator (filter.value already lowercased where needed)
      const filterVal = filter.value.toLowerCase();
      switch (filter.operator) {
        case "contains":
          return fieldValue.includes(filterVal);
        case "equals":
          return fieldValue === filterVal;
        case "startsWith":
          return fieldValue.startsWith(filterVal);
        case "endsWith":
          return fieldValue.endsWith(filterVal);
        case "notContains":
          return !fieldValue.includes(filterVal);
        case "isEmpty":
          return !fieldValue || fieldValue.trim() === "";
        case "isNotEmpty":
          return Boolean(fieldValue && fieldValue.trim() !== "");
        default:
          return true; // Unknown operator, don't filter
      }
    });
  });
}

/**
 * Apply pagination to filtered data
 * @param data Array of filtered data
 * @param pageIndex Current page index (0-based)
 * @param pageSize Number of items per page
 * @returns Paginated data and pagination info
 */
export function applyPagination<T>(
  data: T[],
  pageIndex: number,
  pageSize: number
) {
  const startIndex = pageIndex * pageSize;
  const endIndex = startIndex + pageSize;
  const paginatedData = data.slice(startIndex, endIndex);

  return {
    data: paginatedData,
    pageCount: Math.ceil(data.length / pageSize),
    rowCount: data.length,
  };
}

// Helper function to process object-type filter values
function _processObjectFilter(
  filter: Filter,
  serverFilters: Record<string, unknown>,
  complexFilters: ComplexFilter[]
) {
  const valueObj = filter.value as Record<string, unknown>;

  if (valueObj.contains !== undefined) {
    // For 'contains' operator, store for client-side filtering
    complexFilters.push({
      id: filter.id,
      operator: "contains",
      value: String(valueObj.contains || "").toLowerCase(),
    });
    // Also add to serverFilters in a format the server can understand
    serverFilters[filter.id] = { contains: valueObj.contains };
  } else if (valueObj.value !== undefined) {
    // Use only the value part, not the operator
    serverFilters[filter.id] = valueObj.value;
  } else if (valueObj.equals !== undefined) {
    // For 'equals' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "equals",
      value: String(valueObj.equals),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.equals;
  } else if (valueObj.startsWith !== undefined) {
    // For 'startsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "startsWith",
      value: String(valueObj.startsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.startsWith;
  } else if (valueObj.endsWith !== undefined) {
    // For 'endsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "endsWith",
      value: String(valueObj.endsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.endsWith;
  }
}

/**
 * Process filters for server-side filtering
 * Handles complex filters like 'contains', 'startsWith', etc.
 * @param filters Array of filter objects from DataTable
 * @returns Object with processed filters and complex filters that need client-side processing
 */
export function processServerFilters(filters: Filter[]) {
  const serverFilters: Record<string, unknown> = {};
  const complexFilters: ComplexFilter[] = [];

  // Process each filter
  for (const filter of filters) {
    // Handle different filter types based on the value
    if (typeof filter.value === "object" && filter.value !== null) {
      _processObjectFilter(filter, serverFilters, complexFilters);
    } else if (filter.value !== undefined && filter.value !== "") {
      // For simple equality filters
      serverFilters[filter.id] = filter.value;
    }
  }

  return { complexFilters, serverFilters };
}

/**
 * Utilities for handling table configuration transformations
 * Manages conversions between in-memory TanStack Table state and database-storable format
 */

// Import TanStack Table types
import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  SortingState,
} from "../tanstack";
import type {
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
} from "../types/display-types";
import type { AdvancedFiltersState } from "../types/filter-types";
// Import TableViewConfig type from types
import type { TableViewConfig } from "../types/view-types";
import {
  areTableViewConfigsEqual,
  normalizeTableViewConfig,
} from "./table-view-state";

/**
 * Type definition for a serialized table configuration
 * Ensures all properties are JSON-serializable
 */
export interface SerializedTableViewConfig {
  advancedFilters?: string; // JSON string of advanced filter rules
  columnFilters?: string; // JSON string of filter configurations
  columnOrder?: string; // JSON string of column order
  columnPinning?: string; // JSON string of pinned columns
  columnSizing?: string; // JSON string of user-defined column widths
  columnVisibility?: string; // JSON string of column visibility
  displayMode?: TableDisplayMode; // Display mode for this view
  gallery?: string; // JSON string of Gallery view configuration
  globalSearch?: string; // Global search value
  grouping?: string; // JSON string of grouping columns
  kanban?: string; // JSON string of Kanban view configuration
  pageSize?: number; // Page size restored with the view
  sorting?: string; // JSON string of sort configuration
}

// Define ColumnVisibilityState type if it's not exported from @tanstack/react-table
type ColumnVisibilityState = Record<string, boolean>;

/**
 * Utilities for table configuration
 * Handles conversion between in-memory state and database-storable format
 */
export const tableConfigUtils = {
  /**
   * Determines if two configurations are equivalent
   * Useful for detecting if changes have been made
   * @param config1 - First configuration to compare
   * @param config2 - Second configuration to compare
   * @returns True if configurations are equivalent
   */
  areEqual: (config1: TableViewConfig, config2: TableViewConfig): boolean => {
    return areTableViewConfigsEqual(config1, config2);
  },

  /**
   * Creates a deep clone of a configuration
   * @param config - Configuration to clone
   * @returns Deep copy of the configuration
   */
  clone: (config: TableViewConfig): TableViewConfig => {
    return JSON.parse(JSON.stringify(config)) as TableViewConfig;
  },

  /**
   * Converts a serialized configuration from storage to a usable TableViewConfig
   * @param serializedConfig - Configuration as stored in the database
   * @returns TableViewConfig object ready for use with TanStack Table
   */
  fromStorage: (
    serializedConfig: SerializedTableViewConfig | string
  ): TableViewConfig => {
    // If the input is a string, parse it as JSON
    let config: SerializedTableViewConfig;
    try {
      if (typeof serializedConfig === "string") {
        config = JSON.parse(serializedConfig) as SerializedTableViewConfig;
      } else {
        config = serializedConfig;
      }
    } catch {
      // Return empty config if parsing fails
      return {};
    }

    // Parse column filters and ensure they have the correct structure
    let columnFilters: ColumnFiltersState | undefined;
    if (config.columnFilters) {
      try {
        // Handle the case where columnFilters might already be an object
        const parsedFilters =
          typeof config.columnFilters === "string"
            ? JSON.parse(config.columnFilters)
            : config.columnFilters;

        // Ensure each filter has the correct structure
        if (Array.isArray(parsedFilters)) {
          columnFilters = parsedFilters.map((filter: unknown) => {
            const filterObj = filter as { id?: unknown; value?: unknown };
            // Make sure the ID is a string
            const id =
              typeof filterObj.id === "string"
                ? filterObj.id
                : String(filterObj.id || "");
            return {
              id,
              value: filterObj.value,
            };
          });
        } else {
          columnFilters = [];
        }
      } catch {
        columnFilters = [];
      }
    }

    // Helper function to safely parse JSON or handle already parsed objects
    const safelyParse = <T>(value: unknown, defaultValue: T): T => {
      if (!value) {
        return defaultValue;
      }

      try {
        if (typeof value === "string") {
          return JSON.parse(value) as T;
        }
        // If it's already an object, return it directly
        return value as T;
      } catch {
        return defaultValue;
      }
    };

    const parsedConfig: TableViewConfig = {
      advancedFilters: safelyParse<AdvancedFiltersState>(
        config.advancedFilters,
        []
      ),
      columnFilters,
      columnOrder: safelyParse<ColumnOrderState>(config.columnOrder, []),
      columnPinning: safelyParse<ColumnPinningState>(config.columnPinning, {
        left: [],
        right: [],
      }),
      columnSizing: safelyParse<ColumnSizingState>(config.columnSizing, {}),
      columnVisibility: safelyParse<ColumnVisibilityState>(
        config.columnVisibility,
        {}
      ),
      displayMode:
        config.displayMode === "gallery" ||
        config.displayMode === "kanban" ||
        config.displayMode === "table"
          ? config.displayMode
          : undefined,
      gallery: safelyParse<TableGalleryViewConfig>(config.gallery, {}),
      globalSearch:
        typeof config.globalSearch === "string" ? config.globalSearch : "",
      grouping: safelyParse<string[]>(config.grouping, []),
      kanban: safelyParse<TableKanbanViewConfig>(config.kanban, {}),
      pageSize:
        typeof config.pageSize === "number" && Number.isFinite(config.pageSize)
          ? config.pageSize
          : undefined,
      sorting: safelyParse<SortingState>(config.sorting, []),
    };

    // Create TableViewConfig with parsed JSON properties
    return normalizeTableViewConfig(parsedConfig);
  },

  /**
   * Converts a TableViewConfig to a format that can be stored in the database
   * @param config - In-memory TableViewConfig used by TanStack Table
   * @returns SerializedTableViewConfig ready for database storage
   */
  toStorage: (config: TableViewConfig): SerializedTableViewConfig => {
    // Normalize column filters to ensure only simple data is stored
    const normalizedColumnFilters = config.columnFilters?.map((filter) => {
      // Extract only the essential properties and normalize column IDs
      // This prevents complex objects like functions or module references from being serialized
      let columnId =
        typeof filter.id === "string" ? filter.id : String(filter.id);

      // Clean up Turbopack references if present
      if (columnId.includes("__TURBOPACK_")) {
        // Try to extract a simpler ID from the path
        const simplifiedId = columnId.split("/").pop()?.split("$").pop();
        if (simplifiedId) {
          columnId = simplifiedId;
        }
      }

      return {
        id: columnId,
        value: filter.value,
      };
    });

    const normalizedConfig = normalizeTableViewConfig({
      ...config,
      columnFilters: normalizedColumnFilters,
    });

    // Convert each property to a JSON string for storage
    return {
      advancedFilters: normalizedConfig.advancedFilters
        ? JSON.stringify(normalizedConfig.advancedFilters)
        : undefined,
      columnFilters: normalizedConfig.columnFilters
        ? JSON.stringify(normalizedConfig.columnFilters)
        : undefined,
      columnOrder: normalizedConfig.columnOrder
        ? JSON.stringify(normalizedConfig.columnOrder)
        : undefined,
      columnPinning: normalizedConfig.columnPinning
        ? JSON.stringify(normalizedConfig.columnPinning)
        : undefined,
      columnSizing: normalizedConfig.columnSizing
        ? JSON.stringify(normalizedConfig.columnSizing)
        : undefined,
      columnVisibility: normalizedConfig.columnVisibility
        ? JSON.stringify(normalizedConfig.columnVisibility)
        : undefined,
      displayMode: normalizedConfig.displayMode,
      gallery: normalizedConfig.gallery
        ? JSON.stringify(normalizedConfig.gallery)
        : undefined,
      globalSearch: normalizedConfig.globalSearch,
      grouping: normalizedConfig.grouping
        ? JSON.stringify(normalizedConfig.grouping)
        : undefined,
      kanban: normalizedConfig.kanban
        ? JSON.stringify(normalizedConfig.kanban)
        : undefined,
      pageSize: normalizedConfig.pageSize,
      sorting: normalizedConfig.sorting
        ? JSON.stringify(normalizedConfig.sorting)
        : undefined,
    };
  },
};

/** Framework-independent adapters. Also copied into the standalone Vue registry. */
const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
export type ContractRecord = Record<string, unknown>;
export type ContractColumnSizing = Record<string, number>;

const DEFAULT_COLUMN_RESIZE_STEP = 10;

/** Keep persisted column widths finite, positive, and scoped to known columns. */
export function normalizeColumnSizing(
  value: unknown,
  allowedColumnIds?: readonly string[]
): ContractColumnSizing {
  const allowed = allowedColumnIds ? new Set(allowedColumnIds) : undefined;
  const normalized: ContractColumnSizing = {};
  for (const [columnId, width] of Object.entries(recordValue(value))) {
    const numericWidth = Number(width);
    if (
      (!allowed || allowed.has(columnId)) &&
      Number.isFinite(numericWidth) &&
      numericWidth > 0
    ) {
      normalized[columnId] = Math.round(numericWidth);
    }
  }
  return normalized;
}

/** Resolve the keyboard resize commands shared by the React and Vue headers. */
export function resizedColumnSizeFromKey({
  key,
  maxSize,
  minSize,
  size,
  step = DEFAULT_COLUMN_RESIZE_STEP,
}: {
  key: string;
  maxSize: number;
  minSize: number;
  size: number;
  step?: number;
}): number | undefined {
  let nextSize: number;
  switch (key) {
    case "ArrowLeft":
      nextSize = size - step;
      break;
    case "ArrowRight":
      nextSize = size + step;
      break;
    case "Home":
      nextSize = minSize;
      break;
    case "End":
      nextSize = maxSize;
      break;
    default:
      return undefined;
  }
  return Math.min(maxSize, Math.max(minSize, nextSize));
}

export function recordValue(value: unknown): ContractRecord {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as ContractRecord)
    : {};
}

/** Read both historical arrays and the Vue filter envelope without losing OR semantics. */
export function normalizeFilterEnvelope(value: unknown): {
  filters: ContractRecord[];
  joinOperator: "and" | "or";
} {
  const envelope = recordValue(value);
  const candidates = Array.isArray(value) ? value : envelope.filters;
  const filters = Array.isArray(candidates)
    ? candidates
        .map(recordValue)
        .filter(
          (filter) =>
            typeof filter.columnId === "string" &&
            typeof filter.operator === "string"
        )
    : [];
  const joinOperator =
    envelope.joinOperator === "or" || filters[0]?.joinOperator === "or"
      ? "or"
      : "and";
  return {
    filters: filters.map((filter) => ({
      ...filter,
      isActive: filter.isActive !== false,
      ...(joinOperator === "or" ? { joinOperator } : {}),
    })),
    joinOperator,
  };
}

/** Supply both editions' existing list parameter names to unchanged application handlers. */
export function compatibleListParams(input: ContractRecord): ContractRecord {
  const pageSize = positiveInteger(input.pageSize ?? input.limit, 10);
  const sorting = Array.isArray(input.sorting)
    ? input.sorting
    : Object.entries(recordValue(input.orderBy)).map(([id, direction]) => ({
        id,
        desc: direction === "desc",
      }));
  const orderBy = Object.fromEntries(
    sorting.map((item) => {
      const sort = recordValue(item);
      return [String(sort.id), sort.desc ? "desc" : "asc"];
    })
  );
  const search = String(input.search ?? input.q ?? input.globalSearch ?? "");
  const advanced = normalizeFilterEnvelope(input.advancedFilters);
  return {
    ...input,
    page: positiveInteger(input.page, 1),
    limit: pageSize,
    pageSize,
    orderBy,
    sorting,
    search,
    q: search,
    globalSearch: search,
    filters: recordValue(input.filters),
    advancedFilters: advanced.filters.filter(
      (filter) => filter.isActive !== false
    ),
    advancedFilterJoin: input.advancedFilterJoin ?? advanced.joinOperator,
    grouping: Array.isArray(input.grouping) ? input.grouping : [],
  };
}

export function positiveInteger(value: unknown, fallback: number): number {
  const number = Number(value);
  return Number.isFinite(number) && number > 0
    ? Math.max(1, Math.trunc(number))
    : fallback;
}

/** Collect every result using the server's pagination metadata, including capped page sizes. */
export async function fetchAllContractRows<T>({
  list,
  params,
  maxPages = 1000,
}: {
  list: (params: ContractRecord) => Promise<{
    data: T[];
    meta?: { pageCount?: number; totalCount?: number };
  }>;
  params: ContractRecord;
  maxPages?: number;
}): Promise<T[]> {
  const request = compatibleListParams(params);
  const rows: T[] = [];
  for (let page = 1; page <= maxPages; page += 1) {
    const result = await list({ ...request, page });
    rows.push(...result.data);
    const pageCount = result.meta?.pageCount;
    const totalCount = result.meta?.totalCount;
    const hasPageCount = Number.isFinite(pageCount) && (pageCount ?? 0) > 0;
    const hasTotalCount =
      Number.isFinite(totalCount) && (totalCount ?? -1) >= 0;
    if (
      (hasPageCount && page >= (pageCount ?? 0)) ||
      (hasTotalCount && rows.length >= (totalCount ?? 0)) ||
      (!(hasPageCount || hasTotalCount) &&
        result.data.length < Number(request.pageSize))
    ) {
      return rows;
    }
    if (!result.data.length) {
      throw new Error(
        "The list action returned an empty page before all matching rows were loaded."
      );
    }
  }
  throw new Error(
    "Too many pages to load all matching rows. Narrow the filters and try again."
  );
}

/** Canonical saved-view names are React's; legacy Vue names remain readable. */
export function normalizeViewAliases(value: unknown): ContractRecord {
  const view = recordValue(value);
  return {
    ...view,
    columnFilters: view.columnFilters ?? view.filters ?? [],
    globalSearch: view.globalSearch ?? view.search ?? "",
    columnPinning: view.columnPinning ??
      view.pinning ?? { left: [], right: [] },
    grouping:
      view.grouping ??
      (recordValue(view.kanban).groupBy
        ? [recordValue(view.kanban).groupBy]
        : []),
  };
}

/** Match the shared operators before either framework renders the filtered rows. */
export function matchesContractFilter(
  actual: unknown,
  filter: ContractRecord
): boolean {
  const values = Array.isArray(filter.values) ? filter.values : [filter.values];
  const items = Array.isArray(actual) ? actual : [actual];
  const empty =
    actual == null ||
    actual === "" ||
    (Array.isArray(actual) && !actual.length);
  if (filter.type === "date") {
    return matchesDateFilter(actual, filter.operator, values);
  }
  if (filter.operator === "isEmpty") {
    return empty;
  }
  if (filter.operator === "isNotEmpty") {
    return !empty;
  }
  if (
    [
      "greaterThan",
      "greaterThanOrEqual",
      "lessThan",
      "lessThanOrEqual",
      "between",
    ].includes(String(filter.operator))
  ) {
    return (
      !empty &&
      matchesNumberFilter(
        Number(actual),
        String(filter.operator),
        values.map(Number)
      )
    );
  }
  const textual = ["text", "string"].includes(String(filter.type));
  const text = String(actual ?? "").toLocaleLowerCase();
  const expected = String(values[0] ?? "").toLocaleLowerCase();
  const contains = (item: unknown) =>
    items.some((value) => String(value) === String(item));
  switch (filter.operator) {
    case "isTrue":
      return actual === true;
    case "isFalse":
      return actual === false;
    case "is":
    case "equals":
      return textual ? text === expected : values.some(contains);
    case "isNot":
    case "notEquals":
      return textual ? text !== expected : !values.some(contains);
    case "isAnyOf":
    case "in":
      return values.some(contains);
    case "isNoneOf":
    case "notIn":
    case "containsNone":
      return !values.some(contains);
    case "containsAll":
      return values.every(contains);
    case "contains":
      return Array.isArray(actual)
        ? values.some(contains)
        : text.includes(expected);
    case "notContains":
      return Array.isArray(actual)
        ? !values.some(contains)
        : !text.includes(expected);
    case "startsWith":
      return text.startsWith(expected);
    case "endsWith":
      return text.endsWith(expected);
    default:
      return true;
  }
}

function matchesDateFilter(
  actual: unknown,
  operator: unknown,
  values: unknown[]
): boolean {
  const date = (input: unknown) =>
    input instanceof Date || typeof input === "number"
      ? new Date(input)
      : new Date(
          DATE_ONLY_PATTERN.test(String(input))
            ? `${String(input)}T00:00:00`
            : String(input ?? "")
        );
  const value = date(actual);
  if (operator === "isEmpty" || operator === "isNotEmpty") {
    const valid = Number.isFinite(value.getTime());
    return operator === "isEmpty" ? !valid : valid;
  }
  const start = date(values[0]);
  if (!(Number.isFinite(value.getTime()) && Number.isFinite(start.getTime()))) {
    return false;
  }
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setHours(23, 59, 59, 999);
  switch (operator) {
    case "equals":
      return value >= start && value <= end;
    case "notEquals":
      return value < start || value > end;
    case "before":
    case "lessThan":
      return value < start;
    case "after":
    case "greaterThan":
      return value > end;
    case "greaterThanOrEqual":
      return value >= start;
    case "lessThanOrEqual":
      return value <= end;
    case "between": {
      const last = date(values[1] ?? values[0]);
      if (last < start) {
        const first = new Date(last);
        first.setHours(0, 0, 0, 0);
        return value >= first && value <= end;
      }
      last.setHours(23, 59, 59, 999);
      return value >= start && value <= last;
    }
    default:
      return true;
  }
}

function matchesNumberFilter(
  actual: number,
  operator: string,
  values: number[]
): boolean {
  switch (operator) {
    case "greaterThan":
      return actual > (values[0] ?? Number.NaN);
    case "greaterThanOrEqual":
      return actual >= (values[0] ?? Number.NaN);
    case "lessThan":
      return actual < (values[0] ?? Number.NaN);
    case "lessThanOrEqual":
      return actual <= (values[0] ?? Number.NaN);
    default:
      return (
        actual >= (values[0] ?? Number.NaN) &&
        actual <= (values[1] ?? Number.NaN)
      );
  }
}

import type {
  ColumnFiltersState,
  ColumnPinningState,
  ColumnSizingState,
  SortingState,
  VisibilityState,
} from "../tanstack";
import type {
  TableDisplayMode,
  TableGalleryAspectRatio,
  TableGalleryCardSize,
  TableGalleryImageFit,
} from "../types/display-types";
import type { AdvancedFiltersState } from "../types/filter-types";
import type { TableViewConfig } from "../types/view-types";
import {
  normalizeColumnSizing,
  normalizeFilterEnvelope,
  normalizeViewAliases,
} from "./table-contracts";

const EMPTY_PINNING: ColumnPinningState = { left: [], right: [] };
const SINGLE_GROUP_DISPLAY_MODES = new Set<TableDisplayMode>([
  "gallery",
  "kanban",
]);

function hasArrayValues(value: unknown): value is unknown[] {
  return Array.isArray(value) && value.length > 0;
}

function hasObjectValues(value: unknown): value is Record<string, unknown> {
  return Boolean(
    value && typeof value === "object" && Object.keys(value).length > 0
  );
}

function normalizePageSize(
  value: number | string | undefined
): number | undefined {
  const numericValue = typeof value === "string" ? Number(value) : value;
  if (
    typeof numericValue !== "number" ||
    !Number.isFinite(numericValue) ||
    numericValue <= 0
  ) {
    return;
  }

  return Math.trunc(numericValue);
}

export function normalizeGroupingState(
  value: unknown,
  fallbackGroupBy?: string
): string[] {
  const grouping = Array.isArray(value)
    ? value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.trim())
        .filter(Boolean)
    : [];

  if (grouping.length > 0) {
    return grouping;
  }

  const fallback = fallbackGroupBy?.trim();
  return fallback ? [fallback] : [];
}

export function getPrimaryGrouping(value: unknown): string {
  return normalizeGroupingState(value)[0] ?? "";
}

export function getDisplayModeGrouping({
  displayMode,
  grouping,
}: {
  displayMode: TableDisplayMode;
  grouping: unknown;
}): string[] {
  const normalizedGrouping = normalizeGroupingState(grouping);
  return SINGLE_GROUP_DISPLAY_MODES.has(displayMode)
    ? normalizedGrouping.slice(0, 1)
    : normalizedGrouping;
}

function normalizeDisplayMode(
  value: TableDisplayMode | undefined
): TableDisplayMode | undefined {
  if (value === "gallery" || value === "kanban" || value === "table") {
    return value;
  }

  return;
}

function normalizeKanbanViewConfig(
  config: TableViewConfig["kanban"]
): TableViewConfig["kanban"] {
  if (!config) {
    return;
  }

  const normalized: NonNullable<TableViewConfig["kanban"]> = {};
  const titleColumn = config.titleColumn?.trim();
  const cardColumnIds = normalizeColumnIds(config.cardColumnIds);

  if (titleColumn) {
    normalized.titleColumn = titleColumn;
  }
  if (cardColumnIds !== undefined) {
    normalized.cardColumnIds = cardColumnIds;
  }
  if (typeof config.showCardLabels === "boolean") {
    normalized.showCardLabels = config.showCardLabels;
  }

  return hasObjectValues(normalized) ? normalized : undefined;
}

function normalizeColumnIds(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return;
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean);
}

function normalizeGalleryAspectRatio(
  value: unknown
): TableGalleryAspectRatio | undefined {
  if (
    value === "portrait" ||
    value === "square" ||
    value === "video" ||
    value === "wide"
  ) {
    return value;
  }

  return;
}

function normalizeGalleryImageFit(
  value: unknown
): TableGalleryImageFit | undefined {
  if (value === "contain" || value === "cover") {
    return value;
  }

  return;
}

function normalizeGalleryCardSize(
  value: unknown
): TableGalleryCardSize | undefined {
  if (value === "large" || value === "medium" || value === "small") {
    return value;
  }

  return;
}

function normalizeGalleryViewConfig(
  config: TableViewConfig["gallery"]
): TableViewConfig["gallery"] {
  if (!config) {
    return;
  }

  const normalized: NonNullable<TableViewConfig["gallery"]> = {};
  const imageColumn = config.imageColumn?.trim();
  const titleColumn = config.titleColumn?.trim();
  const cardColumnIds = normalizeColumnIds(config.cardColumnIds);
  const aspectRatio = normalizeGalleryAspectRatio(config.aspectRatio);
  const imageFit = normalizeGalleryImageFit(config.imageFit);
  const cardSize = normalizeGalleryCardSize(config.cardSize);

  if (imageColumn) {
    normalized.imageColumn = imageColumn;
  }
  if (titleColumn) {
    normalized.titleColumn = titleColumn;
  }
  if (cardColumnIds !== undefined) {
    normalized.cardColumnIds = cardColumnIds;
  }
  if (aspectRatio) {
    normalized.aspectRatio = aspectRatio;
  }
  if (imageFit) {
    normalized.imageFit = imageFit;
  }
  if (cardSize) {
    normalized.cardSize = cardSize;
  }
  if (typeof config.showCardLabels === "boolean") {
    normalized.showCardLabels = config.showCardLabels;
  }

  return hasObjectValues(normalized) ? normalized : undefined;
}

export function normalizeColumnPinning(
  pinning: ColumnPinningState | undefined
): ColumnPinningState | undefined {
  const left = Array.isArray(pinning?.left) ? pinning.left : [];
  const right = Array.isArray(pinning?.right) ? pinning.right : [];
  if (left.length === 0 && right.length === 0) {
    return;
  }

  return { left, right };
}

export function normalizeTableViewConfig(
  input: TableViewConfig
): TableViewConfig {
  const config = normalizeViewAliases(input) as TableViewConfig;
  config.advancedFilters = normalizeFilterEnvelope(config.advancedFilters)
    .filters as unknown as AdvancedFiltersState;
  const normalized: TableViewConfig = {};
  const advancedFilters = hasArrayValues(config.advancedFilters)
    ? (config.advancedFilters as AdvancedFiltersState)
    : undefined;
  const columnFilters = hasArrayValues(config.columnFilters)
    ? (config.columnFilters as ColumnFiltersState)
    : undefined;
  const columnOrder = hasArrayValues(config.columnOrder)
    ? config.columnOrder
    : undefined;
  const columnPinning = normalizeColumnPinning(config.columnPinning);
  const columnSizing = normalizeColumnSizing(config.columnSizing);
  const columnVisibility = hasObjectValues(config.columnVisibility)
    ? (config.columnVisibility as VisibilityState)
    : undefined;
  const globalSearch =
    typeof config.globalSearch === "string" && config.globalSearch.trim()
      ? config.globalSearch.trim()
      : undefined;
  const displayMode = normalizeDisplayMode(config.displayMode);
  const grouping = normalizeGroupingState(
    config.grouping,
    config.kanban?.groupBy
  );
  const kanban = normalizeKanbanViewConfig(config.kanban);
  const gallery = normalizeGalleryViewConfig(config.gallery);
  const pageSize = normalizePageSize(config.pageSize);
  const sorting = hasArrayValues(config.sorting)
    ? (config.sorting as SortingState)
    : undefined;

  if (advancedFilters) {
    normalized.advancedFilters = advancedFilters;
  }
  if (columnFilters) {
    normalized.columnFilters = columnFilters;
  }
  if (columnOrder) {
    normalized.columnOrder = columnOrder;
  }
  if (columnPinning) {
    normalized.columnPinning = columnPinning;
  }
  if (hasObjectValues(columnSizing)) {
    normalized.columnSizing = columnSizing;
  }
  if (columnVisibility) {
    normalized.columnVisibility = columnVisibility;
  }
  if (globalSearch) {
    normalized.globalSearch = globalSearch;
  }
  if (displayMode) {
    normalized.displayMode = displayMode;
  }
  if (grouping.length > 0) {
    normalized.grouping = grouping;
  }
  if (kanban) {
    normalized.kanban = kanban;
  }
  if (gallery) {
    normalized.gallery = gallery;
  }
  if (pageSize) {
    normalized.pageSize = pageSize;
  }
  if (sorting) {
    normalized.sorting = sorting;
  }

  return normalized;
}

export function createTableViewConfigSnapshot({
  advancedFiltersParam,
  displayModeParam,
  filtersParam,
  globalSearchParam,
  groupingParam,
  galleryParam,
  kanbanParam,
  kanbanGroupByParam,
  orderParam,
  pageSizeParam,
  pinningParam,
  sizingParam,
  sortParam,
  visibilityParam,
}: {
  advancedFiltersParam: AdvancedFiltersState;
  displayModeParam: TableDisplayMode;
  filtersParam: ColumnFiltersState;
  globalSearchParam: string;
  groupingParam: string[];
  galleryParam: TableViewConfig["gallery"];
  kanbanParam: TableViewConfig["kanban"];
  kanbanGroupByParam: string;
  orderParam: string[];
  pageSizeParam: string;
  pinningParam?: ColumnPinningState;
  sizingParam?: ColumnSizingState;
  sortParam: SortingState;
  visibilityParam: VisibilityState;
}): TableViewConfig {
  return normalizeTableViewConfig({
    advancedFilters: advancedFiltersParam,
    columnFilters: filtersParam,
    columnOrder: orderParam,
    columnPinning: normalizeColumnPinning(pinningParam) ?? EMPTY_PINNING,
    columnSizing: sizingParam ?? {},
    columnVisibility: visibilityParam,
    displayMode: displayModeParam,
    globalSearch: globalSearchParam,
    grouping: normalizeGroupingState(
      groupingParam,
      kanbanParam?.groupBy ?? kanbanGroupByParam
    ),
    gallery: galleryParam,
    kanban: kanbanParam,
    pageSize: normalizePageSize(pageSizeParam),
    sorting: sortParam,
  });
}

export function areTableViewConfigsEqual(
  left: TableViewConfig,
  right: TableViewConfig
): boolean {
  return (
    JSON.stringify(normalizeTableViewConfig(left)) ===
    JSON.stringify(normalizeTableViewConfig(right))
  );
}

import type {
  CreateTableViewInput,
  TableView,
  TableViewActionContext,
  TableViewActionResult,
  TableViewActions,
  UpdateTableViewInput,
} from "../types/view-types";
import { normalizeTableViewConfig } from "./table-view-state";

export const LOCAL_TABLE_VIEWS_STORAGE_PREFIX = "yayaw-table-views";

export interface TableViewStorageAdapter {
  getItem: (key: string) => null | string;
  setItem: (key: string, value: string) => void;
}

interface LocalTableViewActionsOptions {
  idFactory?: () => string;
  now?: () => Date;
  storage?: TableViewStorageAdapter;
}

const memoryStorageMap = new Map<string, string>();

const memoryStorage: TableViewStorageAdapter = {
  getItem: (key) => memoryStorageMap.get(key) ?? null,
  setItem: (key, value) => {
    memoryStorageMap.set(key, value);
  },
};

function getBrowserStorage(): TableViewStorageAdapter | undefined {
  if (typeof window === "undefined" || !window.localStorage) {
    return;
  }

  try {
    return window.localStorage;
  } catch {
    return;
  }
}

function resolveStorage(
  storage?: TableViewStorageAdapter
): TableViewStorageAdapter {
  return storage ?? getBrowserStorage() ?? memoryStorage;
}

export function getTableViewsStorageKey(tableId: string): string {
  return `${LOCAL_TABLE_VIEWS_STORAGE_PREFIX}:${tableId}`;
}

function parseDate(value: unknown): Date | undefined {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  if (typeof value === "string" || typeof value === "number") {
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? undefined : parsed;
  }

  return;
}

function normalizeStoredView(rawView: unknown): TableView | undefined {
  if (!rawView || typeof rawView !== "object") {
    return;
  }

  const record = rawView as Record<string, unknown>;
  if (
    typeof record.id !== "string" ||
    typeof record.name !== "string" ||
    typeof record.tableId !== "string" ||
    !record.config ||
    typeof record.config !== "object"
  ) {
    return;
  }

  return {
    config: normalizeTableViewConfig(record.config),
    createdAt: parseDate(record.createdAt),
    createdById:
      typeof record.createdById === "string" ? record.createdById : "local",
    id: record.id,
    isDefault: record.isDefault === true,
    isGlobal: record.isGlobal === true,
    isSystem: record.isSystem === true,
    name: record.name,
    ownerId:
      typeof record.ownerId === "string" || record.ownerId === null
        ? record.ownerId
        : undefined,
    tableId: record.tableId,
    updatedAt: parseDate(record.updatedAt),
  };
}

function readViews(
  storage: TableViewStorageAdapter,
  tableId: string
): TableView[] {
  const raw = storage.getItem(getTableViewsStorageKey(tableId));
  if (!raw) {
    return [];
  }

  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .map(normalizeStoredView)
      .filter((view): view is TableView => Boolean(view));
  } catch {
    return [];
  }
}

function writeViews(
  storage: TableViewStorageAdapter,
  tableId: string,
  views: TableView[]
): void {
  storage.setItem(getTableViewsStorageKey(tableId), JSON.stringify(views));
}

function normalizeDefaultViews(
  views: TableView[],
  defaultViewId: string | undefined
): TableView[] {
  if (!defaultViewId) {
    return views;
  }

  return views.map((view) => ({
    ...view,
    isDefault: view.id === defaultViewId,
  }));
}

function createSuccess<TData>(data: TData): TableViewActionResult<TData> {
  return { success: true, data };
}

function createError<TData>(error: string): TableViewActionResult<TData> {
  return { success: false, error };
}

export function createLocalTableViewActions(
  options: LocalTableViewActionsOptions = {}
): Required<TableViewActions> {
  const storage = resolveStorage(options.storage);
  const now = options.now ?? (() => new Date());
  const idFactory =
    options.idFactory ??
    (() =>
      `view-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`);

  return {
    create: (
      input: CreateTableViewInput
    ): Promise<TableViewActionResult<TableView>> => {
      const name = input.name.trim();
      if (!name) {
        return Promise.resolve(createError("View name is required"));
      }

      const date = now();
      const view: TableView = {
        config: normalizeTableViewConfig(input.config),
        createdAt: date,
        createdById: "local",
        id: idFactory(),
        isDefault: input.isDefault === true,
        isGlobal: input.isGlobal === true,
        isSystem: false,
        name,
        tableId: input.tableId,
        updatedAt: date,
      };
      const currentViews = readViews(storage, input.tableId);
      const nextViews = normalizeDefaultViews(
        [...currentViews, view],
        view.isDefault ? view.id : undefined
      );

      writeViews(storage, input.tableId, nextViews);
      return Promise.resolve(createSuccess(view));
    },
    delete: (
      id: string,
      context: TableViewActionContext
    ): Promise<TableViewActionResult<{ id: string }>> => {
      const currentViews = readViews(storage, context.tableId);
      const targetView = currentViews.find((view) => view.id === id);
      if (!targetView) {
        return Promise.resolve(createError("View not found"));
      }
      if (targetView.isSystem) {
        return Promise.resolve(createError("Cannot delete a system view"));
      }

      writeViews(
        storage,
        context.tableId,
        currentViews.filter((view) => view.id !== id)
      );
      return Promise.resolve(createSuccess({ id }));
    },
    list: (context: TableViewActionContext) =>
      Promise.resolve({
        data: readViews(storage, context.tableId),
      }),
    update: (
      id: string,
      input: UpdateTableViewInput
    ): Promise<TableViewActionResult<TableView>> => {
      const currentViews = readViews(storage, input.tableId);
      const targetIndex = currentViews.findIndex((view) => view.id === id);
      if (targetIndex === -1) {
        return Promise.resolve(createError("View not found"));
      }

      const currentView = currentViews[targetIndex];
      if (currentView.isSystem) {
        return Promise.resolve(createError("Cannot update a system view"));
      }

      const nextView: TableView = {
        ...currentView,
        config: input.config
          ? normalizeTableViewConfig(input.config)
          : currentView.config,
        isDefault: input.isDefault ?? currentView.isDefault,
        isGlobal: input.isGlobal ?? currentView.isGlobal,
        name: input.name?.trim() || currentView.name,
        updatedAt: now(),
      };
      const nextViews = [...currentViews];
      nextViews[targetIndex] = nextView;

      writeViews(
        storage,
        input.tableId,
        normalizeDefaultViews(
          nextViews,
          nextView.isDefault ? nextView.id : undefined
        )
      );
      return Promise.resolve(createSuccess(nextView));
    },
  };
}
